window.READER_DATA={"title":"The Bloodsworn Saga","language":"en","description":"An illustrated companion to The Bloodsworn Saga. Follow its people, explore its places, and uncover its world one chapter at a time. Choose your reading position; the rest will wait.","storageKey":"reader:bloodsworn-saga","chapters":[{"id":"B01-C001","book":"The Shadow of the Gods","number":1,"rank":1},{"id":"B01-C002","book":"The Shadow of the Gods","number":2,"rank":2},{"id":"B01-C003","book":"The Shadow of the Gods","number":3,"rank":3},{"id":"B01-C004","book":"The Shadow of the Gods","number":4,"rank":4},{"id":"B01-C005","book":"The Shadow of the Gods","number":5,"rank":5},{"id":"B01-C006","book":"The Shadow of the Gods","number":6,"rank":6},{"id":"B01-C007","book":"The Shadow of the Gods","number":7,"rank":7},{"id":"B01-C008","book":"The Shadow of the Gods","number":8,"rank":8},{"id":"B01-C009","book":"The Shadow of the Gods","number":9,"rank":9},{"id":"B01-C010","book":"The Shadow of the Gods","number":10,"rank":10},{"id":"B01-C011","book":"The Shadow of the Gods","number":11,"rank":11},{"id":"B01-C012","book":"The Shadow of the Gods","number":12,"rank":12},{"id":"B01-C013","book":"The Shadow of the Gods","number":13,"rank":13},{"id":"B01-C014","book":"The Shadow of the Gods","number":14,"rank":14},{"id":"B01-C015","book":"The Shadow of the Gods","number":15,"rank":15},{"id":"B01-C016","book":"The Shadow of the Gods","number":16,"rank":16},{"id":"B01-C017","book":"The Shadow of the Gods","number":17,"rank":17},{"id":"B01-C018","book":"The Shadow of the Gods","number":18,"rank":18},{"id":"B01-C019","book":"The Shadow of the Gods","number":19,"rank":19},{"id":"B01-C020","book":"The Shadow of the Gods","number":20,"rank":20},{"id":"B01-C021","book":"The Shadow of the Gods","number":21,"rank":21},{"id":"B01-C022","book":"The Shadow of the Gods","number":22,"rank":22},{"id":"B01-C023","book":"The Shadow of the Gods","number":23,"rank":23},{"id":"B01-C024","book":"The Shadow of the Gods","number":24,"rank":24},{"id":"B01-C025","book":"The Shadow of the Gods","number":25,"rank":25},{"id":"B01-C026","book":"The Shadow of the Gods","number":26,"rank":26},{"id":"B01-C027","book":"The Shadow of the Gods","number":27,"rank":27},{"id":"B01-C028","book":"The Shadow of the Gods","number":28,"rank":28},{"id":"B01-C029","book":"The Shadow of the Gods","number":29,"rank":29},{"id":"B01-C030","book":"The Shadow of the Gods","number":30,"rank":30},{"id":"B01-C031","book":"The Shadow of the Gods","number":31,"rank":31},{"id":"B01-C032","book":"The Shadow of the Gods","number":32,"rank":32},{"id":"B01-C033","book":"The Shadow of the Gods","number":33,"rank":33},{"id":"B01-C034","book":"The Shadow of the Gods","number":34,"rank":34},{"id":"B01-C035","book":"The Shadow of the Gods","number":35,"rank":35},{"id":"B01-C036","book":"The Shadow of the Gods","number":36,"rank":36},{"id":"B01-C037","book":"The Shadow of the Gods","number":37,"rank":37},{"id":"B01-C038","book":"The Shadow of the Gods","number":38,"rank":38},{"id":"B01-C039","book":"The Shadow of the Gods","number":39,"rank":39},{"id":"B01-C040","book":"The Shadow of the Gods","number":40,"rank":40},{"id":"B01-C041","book":"The Shadow of the Gods","number":41,"rank":41},{"id":"B01-C042","book":"The Shadow of the Gods","number":42,"rank":42},{"id":"B01-C043","book":"The Shadow of the Gods","number":43,"rank":43},{"id":"B01-C044","book":"The Shadow of the Gods","number":44,"rank":44},{"id":"B01-C045","book":"The Shadow of the Gods","number":45,"rank":45},{"id":"B01-C046","book":"The Shadow of the Gods","number":46,"rank":46},{"id":"B01-C047","book":"The Shadow of the Gods","number":47,"rank":47},{"id":"B01-C048","book":"The Shadow of the Gods","number":48,"rank":48},{"id":"B01-C049","book":"The Shadow of the Gods","number":49,"rank":49},{"id":"B01-C050","book":"The Shadow of the Gods","number":50,"rank":50},{"id":"B01-C051","book":"The Shadow of the Gods","number":51,"rank":51},{"id":"B01-C052","book":"The Shadow of the Gods","number":52,"rank":52},{"id":"B01-C053","book":"The Shadow of the Gods","number":53,"rank":53}],"categories":{"books":"Books","characters":"People","places":"Places","factions":"Companies & allegiances","creatures":"Creatures","lore":"Lore & traditions","artifacts":"Objects & relics","ships":"Ships"},"pages":[{"id":"e-055","file":"e-055.html","source":"characters/Agnar","category":"characters","from":5,"names":[{"from":5,"text":"Agnar"}],"featured":false,"blocks":[{"refs":["f-b01-c005-003","f-b01-c005-005"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Agnar is Elvar’s chief. He steers the Wave-Jarl."}]},{"refs":["f-b01-c005-018","f-b01-c005-027","f-b01-c005-028"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"He demands the surrender of Berak. He claims Berak is gods-touched and dangerous to the villagers."}]},{"refs":["f-b01-c005-046","f-b01-c005-047"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"He throws a coin pouch on the beach and offers the villagers a choice to prosper or die."}]},{"refs":["f-b01-c005-031","f-b01-c005-042"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"He cuts Hrut’s chin and lower lip with his sword. He orders pursuit at the chapter’s close."}]},{"refs":["f-b01-c007-030","f-b01-c007-031","f-b01-c007-034"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar identifies the captive as Berak Bjornasson, despite his denial. He threatens a boy with his sword, drawing blood."}]},{"refs":["f-b01-c007-038","f-b01-c007-039","f-b01-c007-041","f-b01-c007-045"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"He commands HALDA and the collar flashes red as the captive halts. After Á HNÉN the man drops. Agnar intends to sell him."}]},{"refs":["f-b01-c021-047","f-b01-c021-017","f-b01-c021-035","f-b01-c021-026"],"from":21,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Störr addresses him as Agnar Broksson, chief of the Battle-Grim, in B01-C021. Agnar pays harbour dues and further coin for speedier passage through checkpoints; he orders Thrud to find lodgings."}]},{"refs":["f-b01-c021-048","f-b01-c021-049","f-b01-c021-060","f-b01-c021-062","f-b01-c021-063","f-b01-c021-064","f-b01-c021-065"],"from":21,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"He offers Berak to Störr, claiming he is wanted by three jarls for murder, blood-debt and weregild and that his Seiðr-witch has confirmed his lineage. After Hrung’s blood-tasting pronouncement, Agnar accepts Störr’s offer of twice what he would receive elsewhere and promises loyalty. Silrið leads Berak away; Störr says she will bring the payment, which is not shown received here."}]},{"refs":["f-b01-c023-013","f-b01-c023-015"],"from":23,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Gytha delivers a chest for Agnar, identified by Elvar as payment for Berak. Agnar takes the Battle-Grim and chest towards the Wave-Jarl to give Störr privacy."}]},{"refs":["f-b01-c025-009","f-b01-c025-010","f-b01-c025-011"],"from":25,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Agnar knew Elvar's background when taking her in at seventeen and kept it private for almost four years. Agnar gives Elvar and Grend their shares of the Battle-Grim's spoils; Grend collects both pouches. Agnar assures Elvar that she will always have an oar-bench on the Wave-Jarl whatever she chooses."}]},{"refs":["f-b01-c027-013","f-b01-c027-017","f-b01-c027-020","f-b01-c027-024","f-b01-c027-026"],"from":27,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Agnar and the Battle-Grim pursue the attackers to the docks but arrive after their ship has departed. Agnar vows that Ilska will regret stealing from him. Agnar pays the landlord for the tavern's damage. Agnar confirms Ilska's Raven-Feeders took Bjarn and initially declines a costly pursuit. Agnar bargains for Uspa's secret in exchange for recovering Bjarn."}]},{"refs":["f-b01-c029-006","f-b01-c029-016","f-b01-c029-022"],"from":29,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Agnar says the gods-fall is dated to two hundred and ninety-seven years earlier. Uspa agrees to guide the group to Oskutreð first if all present swear the blóð svarið. Uspa, Elvar, Grend, Agnar, Sighvat and Kráka mingle blood over the carved runes."}]},{"refs":["f-b01-c032-003","f-b01-c032-005","f-b01-c032-007","f-b01-c032-013","f-b01-c032-014","f-b01-c032-015","f-b01-c032-016","f-b01-c032-017"],"from":32,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Agnar buys five dismantled carts and eight pack-ponies in Starl. The oath participants keep Oskutreð secret from the rest of the Battle-Grim until reaching the lake's north shore. Agnar questions whether Ilska knowingly kept a Tainted warrior without a thrall-collar. Agnar tells the crew their destination is Oskutreð and that Uspa learned the route before burning the book. Agnar admits the idea that Bjarn was taken for bargaining is a theory. Agnar has seen no sign of Ilska following but hopes she does, to make the rescue easier. Agnar publicly promises to recover Uspa's son or die trying. Agnar tells even the unmarked crew they are bound by the oath if they follow him; no new magical binding is demonstrated."}]},{"refs":["f-b01-c042-010","f-b01-c042-011","f-b01-c042-012","f-b01-c042-013","f-b01-c042-014"],"from":42,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Agnar describes the Battle-Grim as his chosen family, saying he would die for them and will not abandon those bound to him. He tells Elvar that his mother died when he was ten, his father tried to sell him after crop failure when he was eleven, and he killed the would-be buyer with a wood-axe before fleeing. These childhood events are his testimony."}]},{"refs":["f-b01-c005-055","f-b01-c029-025","f-b01-c032-022"],"from":32,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Agnar has blond hair in a central warrior-braid with the rest of his scalp shaved to stubble, and a blond braid in his beard. In the chapter 32 camp address he reveals spiralling oath scars around his hand, wrist and forearm. A documented "},{"text":" distinguishes source details from artistic choices."}]},{"refs":["f-b01-c048-026","f-b01-c048-029","f-b01-c048-030"],"from":48,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"He pledges that his company will not approach the dead tree after Vörn binds Sighvat, then sends the Battle-Grim to gather relics on the surrounding plain."}]},{"refs":["f-b01-c050-008","f-b01-c050-009","f-b01-c050-010","f-b01-c050-013","f-b01-c050-014","f-b01-c050-015","f-b01-c050-016","f-b01-c050-017","f-b01-c050-023","f-b01-c050-024"],"from":50,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"At Oskutreð he accepts a holmganga against Ilska’s brother Skrið and kills him despite severe wounds. Biórr then approaches and drives a spear into Agnar’s open mouth and throat, causing him to fall backwards."}]},{"refs":["f-b01-c052-001"],"from":52,"heading":"Sale at Snakavik","kind":"story","tokens":[{"text":"Chapter 52 confirms his death after Biórr’s spear thrust. His victory over Skrið precedes the betrayal and remains part of that sequence."}]}],"images":[{"file":"assets/43ef87fc7e41c5.jpg","from":43,"role":"primary","spoiler":false}],"curated":false},{"id":"e-080","file":"e-080.html","source":"characters/Arild","category":"characters","from":8,"names":[{"from":8,"text":"Arild"}],"featured":false,"blocks":[{"refs":["f-b01-c008-030"],"from":8,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Guðvarr addresses the drengr woman as Arild."}]},{"refs":["f-b01-c008-029"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"She tells the family that residents of Sigrún’s realm must attend the Althing or find somewhere else to live."}]}],"images":[],"curated":false},{"id":"e-194","file":"e-194.html","source":"characters/Aska","category":"characters","from":48,"names":[{"from":48,"text":"Aska"}],"featured":false,"blocks":[{"refs":["f-b01-c048-016","f-b01-c048-017"],"from":48,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Vörn identifies the enormous shattered wooden body beside Oskutreð as Aska, her mother and the tree’s former Froa."}]}],"images":[],"curated":false},{"id":"e-139","file":"e-139.html","source":"characters/Aslog","category":"characters","from":18,"names":[{"from":18,"text":"Aslog"}],"featured":false,"blocks":[{"refs":["f-b01-c018-032","f-b01-c018-031","f-b01-c018-033"],"from":18,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Glornir says Aslog owned the spear now given to Varg, who will occupy Aslog’s oar-bench seat. He says Aslog has taken the soul road and did not keep his head. Aslog is not identified with the unspecified slain warrior mentioned earlier."}]}],"images":[],"curated":false},{"id":"e-061","file":"e-061.html","source":"characters/Berak","category":"characters","from":5,"names":[{"from":5,"text":"Berak"}],"featured":false,"blocks":[{"refs":["f-b01-c005-018","f-b01-c005-019"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Agnar demands the villagers surrender Berak. He says a woman and child accompany Berak."}]},{"refs":["f-b01-c005-027","f-b01-c005-028"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar claims Berak is gods-touched. He claims Berak will bring blood and slaughter upon the villagers."}]},{"refs":["f-b01-c005-026"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"Hrut denies knowing a Berak living on Iskalt."}]},{"refs":["f-b01-c007-030","f-b01-c007-031"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar names the fur-clad captive Berak Bjornasson. The captive denies the identification. See "},{"page":"e-061"},{"text":"."}]},{"refs":["f-b01-c009-001","f-b01-c009-002","f-b01-c009-003"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"B01-C009 identifies the captive as Berak, resolving the earlier disputed identity. The captured woman is his wife and the boy his son."}]},{"refs":["f-b01-c009-023"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"His chains prevent him diving after his son during the sea-serpent attack."}]},{"refs":["f-b01-c014-007","f-b01-c014-008"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Berak’s wife and son are named Uspa and Bjarn in B01-C014."}]},{"refs":["f-b01-c014-032"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"He tears himself free of the night-wyrms and frees them."}]},{"refs":["f-b01-c021-048","f-b01-c021-054","f-b01-c021-055","f-b01-c021-059","f-b01-c021-060"],"from":21,"heading":"Handover to Störr","kind":"story","tokens":[{"text":"In B01-C021, Agnar offers Berak to Störr and says he is wanted by three jarls; the charges remain Agnar’s account. Agnar has warned him about consequences to his wife and child if he causes trouble. Silrið cuts his arm and gives the blood to Hrung, who declares it Berser’s blood. This is Hrung’s identification after an observed test."}]},{"refs":["f-b01-c021-061","f-b01-c021-062","f-b01-c021-063","f-b01-c021-064"],"from":21,"heading":"Handover to Störr","kind":"story","tokens":[{"text":"Störr orders him taken. Agnar accepts the offered price, and Silrið takes Berak’s chain and leads him away with two Berserkirs. See "},{"text":"the unresolved fate of his family"},{"text":"."}]},{"refs":["f-b01-c029-011"],"from":29,"heading":"Handover to Störr","kind":"story","tokens":[{"text":"Uspa says Berak killed Raven-Feeders and others during their escape."}]}],"images":[],"curated":false},{"id":"e-176","file":"e-176.html","source":"characters/Bersi","category":"characters","from":33,"names":[{"from":33,"text":"Bersi"}],"featured":false,"blocks":[{"refs":["f-b01-c033-014","f-b01-c033-011"],"from":33,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"A girl identifies the axe-struck guard as Bersi. Orka throws her axe into the first guard's face and he falls into the canal."}]}],"images":[],"curated":false},{"id":"e-057","file":"e-057.html","source":"characters/Biórr","category":"characters","from":9,"names":[{"from":5,"text":"Biórr"}],"featured":false,"blocks":[{"refs":["f-b01-c009-049"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Biórr has black hair."}]},{"refs":["f-b01-c009-018"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"He brings porridge to Berak’s wife and son."}]},{"refs":["f-b01-c014-002","f-b01-c014-036"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr finds the campsite overlooking the Wave-Jarl. He and others burn the night-wyrms with flaming branches."}]},{"refs":["f-b01-c023-007"],"from":23,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr tells Bjarn that his father has gone away and asked them to care for him; this is Biórr's comforting account."}]},{"refs":["f-b01-c025-006"],"from":25,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr compliments Elvar's appearance and offers to help with her inner struggle."}]},{"refs":["f-b01-c027-008"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr is found unconscious, bleeding from a shoulder wound and his face."}]},{"refs":["f-b01-c032-019","f-b01-c032-020","f-b01-c032-021"],"from":32,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr expresses guilt for Thrud's death; this does not establish responsibility. Biórr promises to follow Elvar as well as Agnar and calls her Elvar Fire-Fist. Biórr kisses Elvar, who pulls back startled before Grend arrives to send her to watch."}]},{"refs":["f-b01-c042-020","f-b01-c042-021","f-b01-c042-022"],"from":42,"heading":"Story and connections","kind":"story","tokens":[{"text":"Elvar thanks Biórr for saving her and Grend, kisses him and leads him away from camp beneath a willow. Her close view also reveals freckles on his cheek."}]},{"refs":["f-b01-c042-023"],"from":42,"heading":"Story and connections","kind":"story","tokens":[{"text":"In the chapter 42 streamside scene, his hair is braided, with a loose strand falling across his face. A documented "},{"text":" separates observed features from the portrait's artistic choices."}]},{"refs":["f-b01-c044-007","f-b01-c044-008","f-b01-c044-009","f-b01-c044-010","f-b01-c044-011"],"from":44,"heading":"Story and connections","kind":"story","tokens":[{"text":"His shoulder bears a curling blue tattoo, and pale diagonal scars cross his dark-haired chest. He attributes the scars to a knotted leather whip. He tells Elvar he is twenty-two and that all his kin are dead; these personal disclosures remain his account."}]},{"refs":["f-b01-c050-023","f-b01-c050-024"],"from":50,"heading":"Story and connections","kind":"story","tokens":[{"text":"Chapter 50 reveals his betrayal: after the duel he approaches wounded Agnar and thrusts his spear into the chief’s mouth and throat. His motive is not explained in this chapter."}]},{"refs":["f-b01-c052-001","f-b01-c052-002","f-b01-c052-003","f-b01-c052-004","f-b01-c052-005","f-b01-c052-006"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"After killing Agnar he uses the chief’s keys to free Ilmur and Kráka. He declares himself Tainted, says Ilska offers the Tainted a home and condemns their enslavement. He acknowledges Thrud’s killing. Elvar identifies him with Rotta’s blood, but that lineage identification is her conclusion."}]},{"refs":["f-b01-c052-007"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"He avoids Elvar’s thrown spear with unnatural speed."}]}],"images":[{"file":"assets/7defc154812176.jpg","from":43,"role":"primary","spoiler":false}],"curated":false},{"id":"e-073","file":"e-073.html","source":"characters/Bjarn","category":"characters","from":9,"names":[{"from":7,"text":"Berak’s son"},{"from":14,"text":"Bjarn"}],"featured":false,"blocks":[{"refs":["f-b01-c009-003"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The boy is Berak’s son."}]},{"refs":["f-b01-c009-022","f-b01-c009-024","f-b01-c009-029"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"A sea serpent knocks him overboard and Elvar dives to take his wrist. Grend helps bring them back to the ship."}]},{"refs":["f-b01-c014-008"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa calls her son Bjarn in B01-C014."}]},{"refs":["f-b01-c014-032"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Berak frees his wife and son from the night-wyrms."}]},{"refs":["f-b01-c027-024"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar confirms Ilska's Raven-Feeders took Bjarn and initially declines a costly pursuit."}]},{"refs":["f-b01-c050-006","f-b01-c050-021","f-b01-c050-022"],"from":50,"heading":"Story and connections","kind":"story","tokens":[{"text":"Ilska says he lives but refuses to return him. When the carts of collared children are uncovered at Oskutreð, Uspa recognises him."}]},{"refs":["f-b01-c052-020","f-b01-c052-022","f-b01-c052-023","f-b01-c052-040"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"Elvar directly sees him on the trapdoor among the collared children used in Ilska’s ritual. The company later reloads the captive children and departs; no rescue of Bjarn is shown."}]}],"images":[],"curated":false},{"id":"e-003","file":"e-003.html","source":"characters/Breca","category":"characters","from":1,"names":[{"from":1,"text":"Breca"}],"featured":false,"blocks":[{"refs":["f-b01-c001-003","f-b01-c001-004"],"from":1,"heading":"Orka and Thorkel’s son","kind":"introduction","tokens":[{"text":"Breca is Orka and Thorkel's son, ten summers old according to his father."}]},{"refs":["f-b01-c001-015","f-b01-c001-016"],"from":1,"heading":"Appearance","kind":"appearance","tokens":[{"text":"He has grey-green eyes and crow-black hair."}]},{"refs":["f-b01-c001-008","f-b01-c001-026","f-b01-c001-052","f-b01-c001-051","f-b01-c001-071"],"from":1,"heading":"A child meeting the wider world","kind":"story","tokens":[{"text":"On the hunt, Breca's spear hits a tree instead of the reindeer. He has helped slaughter animals for food, but Asgrim is the first dead person he has seen. His question at the steading is where Harek has gone, the boy he has played with on Fellur's beach."}]},{"refs":["f-b01-c003-002","f-b01-c003-001","f-b01-c003-004","f-b01-c003-058"],"from":3,"heading":"A child meeting the wider world","kind":"story","tokens":[{"text":"Orka gives him the pony and wagon to lead back to Fellur, focusing his attention after what he has seen. Before the gathered villagers, he says that Harek has been taken."}]},{"refs":["f-b01-c006-032","f-b01-c006-034","f-b01-c006-035","f-b01-c006-036"],"from":6,"heading":"A child meeting the wider world","kind":"story","tokens":[{"text":"Hearing an injured tennúr scream leads him to the creature he later calls Vesli. He gives her a loose first tooth and asks whether the family can keep her."}]},{"refs":["f-b01-c015-014","f-b01-c015-019","f-b01-c015-025","f-b01-c015-032","f-b01-c015-033","f-b01-c015-023"],"from":15,"heading":"A child meeting the wider world","kind":"story","tokens":[{"text":"Anger at Guðvarr and Sigrún makes him want to learn sword craft, yet he also argues that a trapped creature facing death deserves help. His appeal persuades Orka to free a moth from a web. He wears a small wooden sword pendant and later carries the dishes to the stream with Vesli riding on the load."}]},{"refs":["f-b01-c017-051","f-b01-c017-019","f-b01-c017-061","f-b01-c017-067","f-b01-c017-062"],"from":17,"heading":"The search for Breca","kind":"story","tokens":[{"text":"After the attack on the steading, Thorkel tells Orka that Breca has been taken. A captive later names Drekr and says the boy was carried onto the river, but claims not to know the route or destination. That testimony is obtained under violent coercion."}]},{"refs":["f-b01-c053-011","f-b01-c053-014","f-b01-c053-015"],"from":53,"heading":"The search for Breca","kind":"story","tokens":[{"text":"At the end of book one, Orka tells Glornir her son was taken and says the person she seeks is not at Grimholt. The children she has found do not establish that Breca is among them or has been recovered."}]}],"images":[],"curated":true},{"id":"e-162","file":"e-162.html","source":"characters/Broðir","category":"characters","from":23,"names":[{"from":23,"text":"Broðir"}],"featured":false,"blocks":[{"refs":["f-b01-c023-005","f-b01-c023-025"],"from":23,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Broðir is Elvar's younger brother. Broðir asks Elvar to return and says he has missed her."}]}],"images":[],"curated":false},{"id":"e-138","file":"e-138.html","source":"characters/Drekr","category":"characters","from":17,"names":[{"from":17,"text":"Drekr"}],"featured":false,"blocks":[{"refs":["f-b01-c017-067","f-b01-c017-066"],"from":17,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"A "},{"page":"e-134"},{"text":", questioned violently by Orka about the chief who took Breca, supplies the name Drekr. He says he fears the chief. This is the captive’s account under coercion; this initial identification is not direct observation of Drekr."}]},{"refs":["f-b01-c022-024","f-b01-c022-025","f-b01-c022-026","f-b01-c022-027"],"from":22,"heading":"Story and connections","kind":"story","tokens":[{"text":"Under Orka’s threat in B01-C022, Vafri independently supplies Drekr’s name as the recipient of her reports about the Tainted. She says she does not know where he is taking Breca and, forced to guess, suggests Darl. The destination remains uncertain."}]},{"refs":["f-b01-c033-017"],"from":33,"heading":"Story and connections","kind":"story","tokens":[{"text":"The older boy says Drekr is inside the Dead Drengr."}]},{"refs":["f-b01-c035-007","f-b01-c035-010","f-b01-c035-011","f-b01-c035-018","f-b01-c035-019","f-b01-c035-020","f-b01-c035-022","f-b01-c035-023","f-b01-c035-024","f-b01-c035-029","f-b01-c035-031"],"from":35,"heading":"Story and connections","kind":"story","tokens":[{"text":"Drekr is huge and raven-haired, with silver rings in his beard and four recently stitched claw scars from forehead to chin. Drekr reacts to the seax Orka recovered from Thorkel's body, and the narrative names him after her identification. Drekr boasts that he stabbed Orka's husband and that he squealed; the boast is Drekr's account. Drekr headbutts Orka and throws her off him. Drekr orders his companions to let him fight Orka, and a crowd forms around them and bets on the fight. Drekr says Breca is gone but gives no destination. Drekr has a serpent tattoo across his shoulder and chest, with open jaws and a knotwork body; no ancestry is established by it. Drekr cuts Orka's forearm, disarms her axe and catches her throat in his axe shaft. Drekr claims Orka's son will change the world. Drekr orders his men to surround Orka so she cannot escape. Orka climbs behind Lif and escapes down an alley, leaving Drekr alive on the street."}]},{"refs":["f-b01-c035-032","f-b01-c035-033","f-b01-c035-035"],"from":35,"heading":"Story and connections","kind":"story","tokens":[{"text":"At the Dead Drengr, his bunched shoulders make him appear almost neckless, and his dark tunic has knot-weave embroidery around the neck and chest. His axe is shorter than a long-axe but can be gripped two-handed."}]},{"refs":["f-b01-c050-011","f-b01-c050-018","f-b01-c050-019"],"from":50,"heading":"Story and connections","kind":"story","tokens":[{"text":"Chapter 50 names him beside Ilska at Oskutreð and identifies him and Skrið as her brothers. Elvar concludes they are dragon-born after Vörn’s response to Skrið, but that collective identification remains Elvar’s conclusion at this point."}]},{"refs":["f-b01-c052-031","f-b01-c052-034"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"At the released dragon’s side he attacks the golden-winged gaoler with Ilska, then kneels before Lik-Rifa with the others."}]}],"images":[{"file":"assets/046693988e5baf.jpg","from":35,"role":"primary","spoiler":false}],"curated":false},{"id":"e-045","file":"e-045.html","source":"characters/Edel","category":"characters","from":4,"names":[{"from":4,"text":"Unnamed silver-haired woman"},{"from":13,"text":"Edel"}],"featured":false,"blocks":[{"refs":["f-b01-c004-001","f-b01-c004-002","f-b01-c004-003"],"from":4,"heading":"Appearance","kind":"introduction","tokens":[{"text":"The woman watching Varg’s trial has silver-grey hair. A white scar runs through a ruined eye. Two wolfhounds are at her feet."}]},{"refs":["f-b01-c004-085","f-b01-c004-088"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"She later appears at Varg’s camp with two wolfhounds. The hounds drag one of the pursuers to the ground."}]},{"refs":["f-b01-c013-007","f-b01-c013-006"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Torvik identifies Edel as the scoutmaster in B01-C013. He says he scouts under her."}]},{"refs":["f-b01-c013-007"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"The narrator identifies Edel as scoutmaster in B01-C016, confirming Torvik’s earlier identification."}]},{"refs":["f-b01-c018-072"],"from":18,"heading":"Story and connections","kind":"story","tokens":[{"text":"During the dockside battle in B01-C018, Edel and her hounds bring down a horse."}]},{"refs":["f-b01-c030-015","f-b01-c030-016"],"from":30,"heading":"Story and connections","kind":"story","tokens":[{"text":"Edel gives her wolfhounds halves of a tunic to sniff. Edel leads Torvik and the other scouts north through the fields, with the rest following."}]},{"refs":["f-b01-c047-010","f-b01-c047-018"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"She reveals Hundur ancestry and says she recognised wolf blood in Varg at his Liga trial. She explains the Bloodsworn’s secrecy as protection against persecution and a means of establishing trust."}]},{"refs":["f-b01-c053-004"],"from":53,"heading":"Story and connections","kind":"story","tokens":[{"text":"While tracking Skalk she tells Varg he has the makings of a fine scout, recalling Torvik’s favourable assessment."}]}],"images":[],"curated":false},{"id":"e-022","file":"e-022.html","source":"characters/Einar Half-Troll","category":"characters","from":2,"names":[{"from":2,"text":"Einar Half-Troll"}],"featured":false,"blocks":[{"refs":["f-b01-c002-078","f-b01-c002-087","f-b01-c002-090"],"from":2,"heading":"The trial fighter","kind":"introduction","tokens":[{"text":"Einar Half-Troll is the fighter whom Svik names at the weapons trial. Svik says he fights without a shield to give challengers a chance."}]},{"refs":["f-b01-c002-079","f-b01-c002-080"],"from":2,"heading":"Appearance","kind":"appearance","tokens":[{"text":"At the trial his red beard is braided to his waist, and he fights stripped to the waist."}]},{"refs":["f-b01-c002-098","f-b01-c004-105","f-b01-c004-106"],"from":4,"heading":"Appearance","kind":"appearance","tokens":[{"text":"Einar has a thick body and knotted muscles, with a slab-boned face framed by red hair and enormous fists."}]},{"refs":["f-b01-c002-086","f-b01-c002-088","f-b01-c002-089","f-b01-c002-087","f-b01-c002-090"],"from":2,"heading":"An opponent and a companion","kind":"story","tokens":[{"text":"A challenger sees his shield shattered by Einar's punch before being thrown down and carried away unconscious. Varg agrees to face the same fighter."}]},{"refs":["f-b01-c004-023","f-b01-c004-024","f-b01-c004-028","f-b01-c004-029","f-b01-c004-089"],"from":4,"heading":"An opponent and a companion","kind":"story","tokens":[{"text":"Varg's attempt to strike his groin finds iron-hard protection made by Jökul. A kick sends Einar to one knee, and Varg bites his calf. Later at the camp, Einar punches one of Leif's men through the branches."}]},{"refs":["f-b01-c011-011","f-b01-c011-016"],"from":11,"heading":"An opponent and a companion","kind":"story","tokens":[{"text":"The bite still leaves him limping when Svik mentions it, but he can spar with two of Logur's warriors at once."}]},{"refs":["f-b01-c018-058","f-b01-c018-059","f-b01-c020-051","f-b01-c020-060"],"from":20,"heading":"An opponent and a companion","kind":"story","tokens":[{"text":"At the docks, Einar helps shield Glornir from arrows and knocks a mounted warrior from the saddle with a spear. At departure he hammers the Sea-Wolf's mast-lock into place and calls the rowing commands."}]},{"refs":["f-b01-c026-014"],"from":26,"heading":"An opponent and a companion","kind":"story","tokens":[{"text":"His dealings with Varg also become less combative: after Varg promises not to bite again, Einar offers him bread and a seat."}]},{"refs":["f-b01-c034-003"],"from":34,"heading":"An opponent and a companion","kind":"story","tokens":[{"text":"Asked about his name, he denies being a troll and says he merely has big bones."}]},{"refs":["f-b01-c041-017","f-b01-c043-009","f-b01-c043-020","f-b01-c043-023"],"from":43,"heading":"An opponent and a companion","kind":"story","tokens":[{"text":"For the excavation he prepares a table-sized shield and a hooked, bearded axe. He kills the skraeling threatening Varg and Torvik, then joins the others against the troll and opens its thigh with his axe."}]},{"refs":["f-b01-c047-022"],"from":47,"heading":"An opponent and a companion","kind":"story","tokens":[{"text":"During the later disclosures he explicitly says that he is not actually a half-troll. His epithet does not establish literal parentage."}]}],"images":[{"file":"assets/64775bcf5ec531.jpg","from":43,"role":"primary","spoiler":false}],"curated":true},{"id":"e-052","file":"e-052.html","source":"characters/Elvar","category":"characters","from":5,"names":[{"from":5,"text":"Elvar"}],"featured":true,"blocks":[{"refs":["f-b01-c005-012","f-b01-c005-010","f-b01-c005-013"],"from":5,"heading":"A place in the warband","kind":"introduction","tokens":[{"text":"Elvar is the youngest member of Agnar's warband. Grend has taught her to check that her sword draws freely, and she regards bows as cowardly weapons."}]},{"refs":["f-b01-c005-001","f-b01-c005-009","f-b01-c005-011"],"from":5,"heading":"Appearance","kind":"appearance","tokens":[{"text":"She has blonde hair. At her first disembarkation she carries a sword, seax and axe, and a red shield bearing a crossed sword, axe and spear."}]},{"refs":["f-b01-c007-008","f-b01-c007-025","f-b01-c009-017","f-b01-c009-004","f-b01-c009-015","f-b01-c009-024","f-b01-c009-041"],"from":9,"heading":"Earning her place","kind":"story","tokens":[{"text":"Elvar scouts with Grend and Biórr and helps kill a troll by finding its thigh artery with her sword. She has sailed with the Battle-Grim for a little over three years and holds a front-row shield-wall place. Agnar gives her a troll-tusk necklace, and later rewards her rescue of Berak's son from the sea with a gold arm ring."}]},{"refs":["f-b01-c007-005","f-b01-c007-006","f-b01-c021-010","f-b01-c021-066","f-b01-c021-067","f-b01-c021-068","f-b01-c021-069"],"from":21,"heading":"The home she left behind","kind":"story","tokens":[{"text":"Returning to Snakavik brings back the insignificance Elvar once felt there. At the fortress she pulls back her hood and addresses Störr as her father. The relationship becomes known at this meeting; her earlier rejection of Biórr's suggestion that Grend was her father remains a separate exchange."}]},{"refs":["f-b01-c023-018","f-b01-c023-020","f-b01-c025-001","f-b01-c025-005","f-b01-c025-014","f-b01-c025-019","f-b01-c025-024"],"from":25,"heading":"The home she left behind","kind":"story","tokens":[{"text":"Störr's plans would marry her to Hakon and use her children to extend his rule. Elvar wants to earn a reputation of her own, rather than serve as a piece in her father's plans. She seeks Hrung's advice, but leaves as Störr approaches without a direct answer."}]},{"refs":["f-b01-c027-021","f-b01-c029-001","f-b01-c032-006"],"from":32,"heading":"The home she left behind","kind":"story","tokens":[{"text":"She chooses the Battle-Grim over her father. Her judgement of the blond attacker as Tainted remains uncertain: she later points out that the fight was dark and brief. She gives Grend a silver arm ring as a gift of friendship."}]},{"refs":["f-b01-c038-018","f-b01-c038-020","f-b01-c038-021","f-b01-c042-004","f-b01-c042-016","f-b01-c042-018","f-b01-c042-020","f-b01-c042-021"],"from":42,"heading":"The kin she chooses","kind":"story","tokens":[{"text":"During the ambush at the vaesen pit, Elvar defends the fallen Grend, covers Biórr as he carries him out and rescues Sólín on the return to the shield wall. Afterwards she tends Grend until he wakes. Sólín thanks her as a rescuer and shield-sister, while Elvar's gratitude to Biórr leads to a kiss and a private encounter beneath a willow."}]},{"refs":["f-b01-c044-004","f-b01-c044-016","f-b01-c044-019","f-b01-c044-020","f-b01-c048-012","f-b01-c048-031"],"from":48,"heading":"The kin she chooses","kind":"story","tokens":[{"text":"Her relationship with Biórr continues. She still values battle-fame, but calls Grend and her chosen companions better kin than her blood family. At Oskutreð she identifies the immense wolf skeleton as Ulfrir and joins Grend in uncovering ancient remains and weapons."}]},{"refs":["f-b01-c050-014","f-b01-c050-015","f-b01-c050-016","f-b01-c050-017","f-b01-c052-008","f-b01-c052-009","f-b01-c052-010","f-b01-c052-011","f-b01-c052-012","f-b01-c052-013","f-b01-c052-014"],"from":52,"heading":"The breaking of the shield wall","kind":"story","tokens":[{"text":"Elvar watches Agnar defeat Skrið, only for Biórr to spear the wounded chief. Grend prevents her from pursuing Biórr alone and takes her back to the shield wall. A spear wounds her shoulder; he carries her behind the line and advises fighting left-handed, something she remembers practising."}]},{"refs":["f-b01-c052-020","f-b01-c052-021","f-b01-c052-022","f-b01-c052-023","f-b01-c052-024","f-b01-c052-026","f-b01-c052-033","f-b01-c052-040","f-b01-c052-041"],"from":52,"heading":"The breaking of the shield wall","kind":"story","tokens":[{"text":"She witnesses the blood ritual, the opening of Oskutreð and Lik-Rifa's release. She and Grend survive the blast, but cannot stop Ilska's company leaving with the children."}]}],"images":[{"file":"assets/91d3355cbe7499.jpg","from":35,"role":"secondary","spoiler":true},{"file":"assets/083c8ff0642a62.jpg","from":21,"role":"primary","spoiler":false}],"curated":true},{"id":"e-041","file":"e-041.html","source":"characters/Frøya","category":"characters","from":4,"names":[{"from":4,"text":"Frøya"}],"featured":false,"blocks":[{"refs":["f-b01-c004-046","f-b01-c004-047"],"from":4,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Frøya is "},{"page":"e-014"},{"text":"’s sister. He remembers her as his only friend."}]},{"refs":["f-b01-c004-048","f-b01-c004-049","f-b01-c004-051"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-015"},{"text":" bought both children. According to what Kolskegg told Varg, their parents sold them for a loaf of bread and twelve duck eggs. In that account Frøya was four winters old."}]},{"refs":["f-b01-c004-018","f-b01-c004-019"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"Varg’s first fight among the thralls was for an extra bowl of broth for her. She was shivering with fever then."}]},{"refs":["f-b01-c004-052","f-b01-c004-053"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"Varg thinks of her as dead. He wants to avenge her but does not know how. See "},{"text":"the circumstances of her death"},{"text":"."}]}],"images":[],"curated":false},{"id":"e-107","file":"e-107.html","source":"characters/Galinn","category":"characters","from":13,"names":[{"from":13,"text":"Galinn"}],"featured":false,"blocks":[{"refs":["f-b01-c013-015","f-b01-c013-016"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Logur introduces Galinn as the Skáld of Liga. He carries a seven-stringed lyre."}]},{"refs":["f-b01-c013-025","f-b01-c013-027","f-b01-c013-028"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"His saga describes the gods’ war, fallen gods, Snaka’s fall and vaesen from the pit. This is an attributed telling."}]}],"images":[],"curated":false},{"id":"e-051","file":"e-051.html","source":"characters/Glornir","category":"characters","from":4,"names":[{"from":4,"text":"Unnamed grey-bearded rescuer"},{"from":11,"text":"Glornir"}],"featured":false,"blocks":[{"refs":["f-b01-c004-084","f-b01-c004-086","f-b01-c004-087","f-b01-c004-095"],"from":4,"heading":"A warrior at the camp","kind":"introduction","tokens":[{"text":"The bald, grey-bearded warrior who arrives at Varg's camp carries a bearded long-axe. He orders Varg released and declares him one of the Bloodsworn."}]},{"refs":["f-b01-c011-018","f-b01-c011-003","f-b01-c011-004"],"from":11,"heading":"The chief and his promises","kind":"story","tokens":[{"text":"The rescuer is named as Glornir. Røkia calls him their chief and Shield-Breaker; to Svik he is Gold-Giver."}]},{"refs":["f-b01-c013-039","f-b01-c013-038","f-b01-c013-041","f-b01-c013-040"],"from":13,"heading":"The chief and his promises","kind":"story","tokens":[{"text":"Glornir describes protection as part of his oath to the crew. When asked to surrender Sulich, he refuses because their promise has been sealed in blood. Svik also calls him Soul-Stealer."}]},{"refs":["f-b01-c016-031","f-b01-c016-033","f-b01-c004-095","f-b01-c016-035","f-b01-c016-039","f-b01-c016-036","f-b01-c016-037","f-b01-c016-038","f-b01-c016-040","f-b01-c016-041","f-b01-c016-019","f-b01-c016-043","f-b01-c016-044"],"from":16,"heading":"The chief and his promises","kind":"story","tokens":[{"text":"Varg discovers that the declaration made at his camp did not settle his place in the company. Glornir now calls him an apprentice, saved for the potential he saw in him. He refuses the akáll, demands skill and loyalty, and offers teaching, food and protection in exchange for learning, obedience and fighting. With the ship due to sail, he gives Varg money for equipment."}]},{"refs":["f-b01-c018-031","f-b01-c018-032","f-b01-c018-053","f-b01-c018-055","f-b01-c018-056","f-b01-c018-057","f-b01-c018-058","f-b01-c018-060","f-b01-c018-061"],"from":18,"heading":"The chief and his promises","kind":"story","tokens":[{"text":"The chief gives Varg Aslog's old spear and the dead man's oar-bench place. At the docks, his refusal to hand Sulich over to Jaromir brings another confrontation. He swings his long-axe as the first arrow splinters at his feet, then his company shields him from the volley and forms against the cavalry charge."}]},{"refs":["f-b01-c020-025","f-b01-c020-048","f-b01-c020-049","f-b01-c020-056","f-b01-c020-057","f-b01-c020-058","f-b01-c020-062","f-b01-c020-059"],"from":20,"heading":"Taking the company north","kind":"story","tokens":[{"text":"After meeting Helka in Logur's hall, Glornir returns with Skalk and orders the crew to sail. Their work is to find and kill whatever is eating Helka's people in the north, although the ship first heads south and west out of Liga. Glornir takes the steering oar, makes the passengers row and leaves Vol at the prow."}]},{"refs":["f-b01-c026-016","f-b01-c026-027"],"from":26,"heading":"Taking the company north","kind":"story","tokens":[{"text":"He insists that Vol receive the same respect as any crew member risking a life aboard his ship. Svik's account also presents a private grief: Glornir still mourns Skullsplitter, whom Svik calls his brother."}]},{"refs":["f-b01-c030-014","f-b01-c034-001","f-b01-c034-011","f-b01-c034-017","f-b01-c034-018"],"from":34,"heading":"Taking the company north","kind":"story","tokens":[{"text":"At the farm, Glornir reports neither bodies nor blood. Later, in the Boneback foothills, he orders quiet and forbids campfires. He admits that he worries too, but says he does not know where to search and has made their route public so the woman can find them. Varg's renewed request for an akáll meets a final refusal."}]},{"refs":["f-b01-c043-017","f-b01-c043-025","f-b01-c043-026","f-b01-c043-028","f-b01-c043-029"],"from":43,"heading":"The fight and its aftermath","kind":"story","tokens":[{"text":"The bone-sword wielder throws Glornir through the air and wounds him through his mail. Vol's rune briefly protects him, but its destruction brings them both down; Varg intervenes before the next sword stroke."}]},{"refs":["f-b01-c047-002","f-b01-c047-003","f-b01-c047-004","f-b01-c047-029","f-b01-c047-024","f-b01-c047-025","f-b01-c047-026","f-b01-c047-027","f-b01-c047-028"],"from":47,"heading":"The fight and its aftermath","kind":"story","tokens":[{"text":"After Vol is taken, his grief is violent enough that Einar and others must brace a door against him. Svik identifies him as Berserkir, and Glornir explicitly names Vol as his wife, correcting the earlier impression that she was a thrall. He invites Varg into the company and gives him a silver arm ring, postponing the formal oath-words so they can pursue her rescue."}]},{"refs":["f-b01-c053-006","f-b01-c053-008","f-b01-c053-012","f-b01-c053-013","f-b01-c053-015","f-b01-c053-016"],"from":53,"heading":"The fight and its aftermath","kind":"story","tokens":[{"text":"Two days of tracking Skalk bring him to the burning Grimholt. He recognises Orka as Skullsplitter, asks after his brother and embraces her after hearing of a killing and her son's abduction. The exchange establishes the recognition without making every earlier use of 'brother' a statement of biological kinship."}]}],"images":[{"file":"assets/5221e00c3e48ab.jpg","from":21,"role":"primary","spoiler":false}],"curated":true},{"id":"e-053","file":"e-053.html","source":"characters/Grend","category":"characters","from":5,"names":[{"from":5,"text":"Grend"}],"featured":false,"blocks":[{"refs":["f-b01-c005-059","f-b01-c005-060","f-b01-c005-061","f-b01-c009-054","f-b01-c009-053"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Grend has a broad back, grey streaks in his hair and beard, and a creased, dour face. He is described as no longer young, without a precise age."}]},{"refs":["f-b01-c005-010"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Grend taught Elvar to check that her sword draws freely."}]},{"refs":["f-b01-c005-035"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"He kills the spear-bearing woman attacking Elvar with his axe."}]},{"refs":["f-b01-c005-039","f-b01-c005-041"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"He breaks a section of the hut wall with his axe. After searching for tracks, he points towards the treeline."}]},{"refs":["f-b01-c009-009","f-b01-c009-010"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Grend says Lik-Rifa survived Guðfalla and is chained beneath Oskutreð."}]},{"refs":["f-b01-c009-025","f-b01-c009-029"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"He stabs the sea serpent and drags Elvar and the boy back towards the ship."}]},{"refs":["f-b01-c021-011","f-b01-c021-022","f-b01-c021-069"],"from":21,"heading":"Story and connections","kind":"story","tokens":[{"text":"Snakavik was Grend’s home for longer than Elvar has been alive. On this visit he wears mail and carries axe and seax, with a wool hood over black braided hair. He is beside Elvar when she is identified in Störr’s hall and addresses the jarl as her father."}]},{"refs":["f-b01-c023-016","f-b01-c023-022"],"from":23,"heading":"Story and connections","kind":"story","tokens":[{"text":"Grend remains with Elvar during her meeting with her father. Grend defends Elvar's independently earned renown."}]},{"refs":["f-b01-c025-002","f-b01-c025-003","f-b01-c025-004","f-b01-c025-007","f-b01-c025-023"],"from":25,"heading":"Story and connections","kind":"story","tokens":[{"text":"Grend advises taking Störr's offer but warns that Störr hides plans within plans. Grend promises to follow Elvar whatever she chooses. Elvar remembers Grend's blood oath when she sees the white scar across his palm. Grend grips Biórr's wrist while warning that he protects Elvar from concealed intentions. Hrung calls Grend 'Grend the Talker'."}]},{"refs":["f-b01-c027-006","f-b01-c027-021","f-b01-c027-022"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Grend kills the female attacker outside the tavern. Elvar gives Grend a silver arm ring as a gift of friendship. The gifted arm ring has terminals carved as a snarling wolf or hound."}]},{"refs":["f-b01-c029-019","f-b01-c029-020"],"from":29,"heading":"Story and connections","kind":"story","tokens":[{"text":"Grend initially refuses another oath but finally agrees only for Elvar. Grend's existing oath to Elvar's dead mother drives his sacrifice for Elvar."}]},{"refs":["f-b01-c038-017","f-b01-c038-018","f-b01-c038-020","f-b01-c038-022"],"from":38,"heading":"Story and connections","kind":"story","tokens":[{"text":"At the vaesen pit, Grend protects Elvar despite wounds from tennúr and is struck down by a creature carrying a stone. Elvar guards him until Biórr carries him into the shield wall. Elvar subsequently finds his pulse; the chapter leaves him alive but unconscious."}]},{"refs":["f-b01-c042-004","f-b01-c042-005","f-b01-c042-006","f-b01-c042-016"],"from":42,"heading":"Story and connections","kind":"story","tokens":[{"text":"After the crossing, Uspa cleans and dresses Grend's head wound and says his skull is not broken. He remains unconscious during transport, but at the next camp he wakes, recognises Elvar, speaks and drinks water before sleeping again. Full recovery is not yet established."}]},{"refs":["f-b01-c044-002"],"from":44,"heading":"Story and connections","kind":"story","tokens":[{"text":"By chapter 44 he is marching again, nearly two days after waking, with bandaging and scrapes still visible."}]},{"refs":["f-b01-c052-001","f-b01-c052-008","f-b01-c052-009","f-b01-c052-011","f-b01-c052-012","f-b01-c052-013","f-b01-c052-033"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"He rallies the Battle-Grim after Agnar’s death, protects Elvar in the shield wall and carries her out after a spear wounds her shoulder. He survives the great blast and crawls back to her."}]}],"images":[{"file":"assets/3ea9fdfca3920d.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-033","file":"e-033.html","source":"characters/Guðvarr","category":"characters","from":3,"names":[{"from":3,"text":"Guðvarr"}],"featured":false,"blocks":[{"refs":["f-b01-c003-028","f-b01-c003-029"],"from":3,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Guðvarr is "},{"page":"e-032"},{"text":"’s nephew. He is one of her drengrs."}]},{"refs":["f-b01-c003-033","f-b01-c003-034","f-b01-c003-035","f-b01-c003-031","f-b01-c003-032","f-b01-c003-030"],"from":3,"heading":"Appearance","kind":"appearance","tokens":[{"text":"He has black hair. In Fellur’s courtyard it is oiled and tied at his neck. He has the beginnings of a beard. He wears an embroidered red woollen tunic and a silver arm ring. He carries a sword at his hip."}]},{"refs":["f-b01-c003-036"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-034"},{"text":" says he arrived downriver by snekke that morning."}]},{"refs":["f-b01-c003-043","f-b01-c003-048","f-b01-c003-046","f-b01-c003-047"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"Guðvarr promotes oaths to "},{"page":"e-018"},{"text":" as beneficial. He calls Helka the strongest. He claims Jarl Störr threatens from the west. He claims vaesen are growing bolder, murdering and stealing."}]},{"refs":["f-b01-c003-053","f-b01-c003-054","f-b01-c003-062"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"He blames the killings at "},{"page":"e-013"},{"text":"on vaesen. "},{"page":"e-001"},{"text":" denies that accusation. He tells Orka she is asking for trouble."}]},{"refs":["f-b01-c003-049","f-b01-c003-072"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"He announces an "},{"page":"e-040"},{"text":" after Sigrún’s return. He says they will look into the killings."}]},{"refs":["f-b01-c010-010","f-b01-c010-036","f-b01-c010-037"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Virk says Guðvarr sent scouts but no river boats or hounds. Sigrún defends him, and Virk calls the defence a lie."}]},{"refs":["f-b01-c010-038","f-b01-c010-047"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Guðvarr publicly challenges Virk to holmganga. He says the challenge cannot be withdrawn."}]},{"refs":["f-b01-c012-007","f-b01-c012-010","f-b01-c012-012"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"Guðvarr chooses a fight to submission and is wounded by Virk. He insults Virk while down."}]},{"refs":["f-b01-c012-029"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sigrún says Virk broke the duel by striking for death after submission."}]},{"refs":["f-b01-c022-008","f-b01-c022-038","f-b01-c022-039","f-b01-c022-047"],"from":22,"heading":"Story and connections","kind":"story","tokens":[{"text":"Lif says he and Mord tried unsuccessfully to kill Guðvarr before their capture. During Orka’s raid, Guðvarr is first through Sigrún’s chamber door, his shoulder still bandaged. He leaps back from Orka’s thrown seax, which strikes the doorpost. He later shouts vengeance from the pier while Orka and the brothers escape."}]},{"refs":["f-b01-c040-008","f-b01-c040-010","f-b01-c040-016"],"from":40,"heading":"Story and connections","kind":"story","tokens":[{"text":"Guðvarr pursues Orka, Lif and Mord from their lodging farm with mounted drengrs. Arild rides behind him. He tries to cross the bridge Orka sets alight but retreats when its timber cracks."}]},{"refs":["f-b01-c046-002","f-b01-c046-003","f-b01-c046-020"],"from":46,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka sees the smoke of his pursuing campfires and estimates his party is about a day and a half behind. She suspects river pursuit as well, without seeing boats."}]},{"refs":["f-b01-c051-011","f-b01-c051-012","f-b01-c051-024"],"from":51,"heading":"Story and connections","kind":"story","tokens":[{"text":"He arrives in Grimholt with Arild and stabs bound Mord despite Skalk’s command to wait. Orka later sees him among those fleeing towards the boats."}]}],"images":[],"curated":false},{"id":"e-163","file":"e-163.html","source":"characters/Gytha","category":"characters","from":23,"names":[{"from":23,"text":"Gytha"}],"featured":false,"blocks":[{"refs":["f-b01-c023-011","f-b01-c023-012"],"from":23,"heading":"Appearance","kind":"introduction","tokens":[{"text":"Gytha is Störr's champion. Gytha has braided dark hair and a scar through a cheek into her upper lip."}]},{"refs":["f-b01-c025-017"],"from":25,"heading":"Story and connections","kind":"story","tokens":[{"text":"Gytha brushes Grend's arm as she passes; no relationship is established by this gesture."}]}],"images":[],"curated":false},{"id":"e-146","file":"e-146.html","source":"characters/Hakon","category":"characters","from":20,"names":[{"from":20,"text":"Hakon"}],"featured":false,"blocks":[{"refs":["f-b01-c020-031","f-b01-c020-016"],"from":20,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Svik identifies the young man following Helka as her son Hakon. He is tall, broad and black-haired, with fine clothing and silver ornaments rather than Helka’s gold."}]},{"refs":["f-b01-c022-023","f-b01-c022-024","f-b01-c022-025"],"from":22,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C022, Vafri identifies Hakon as her master. She says she was ordered to report signs of the Tainted and names Drekr as the recipient; this remains her testimony under threat."}]},{"refs":["f-b01-c035-009","f-b01-c035-012","f-b01-c035-028"],"from":35,"heading":"Story and connections","kind":"story","tokens":[{"text":"The hooded young man at Drekr's table is Hakon, whom Orka recognises from the docks. Hakon orders his guarding drengr to kill Orka. Hakon flees with his guard as the drengrs approach."}]},{"refs":["f-b01-c051-007","f-b01-c051-009","f-b01-c051-010"],"from":51,"heading":"Story and connections","kind":"story","tokens":[{"text":"Skapti admits that Hakon ordered Grimholt to permit Drekr to bring and store goods and move freely north or west. This testimony adds a specific arrangement to the earlier observed meeting in Darl; the prince’s complete purpose remains undisclosed."}]}],"images":[],"curated":false},{"id":"e-006","file":"e-006.html","source":"characters/Harek","category":"characters","from":1,"names":[{"from":1,"text":"Harek"}],"featured":false,"blocks":[{"refs":["f-b01-c001-025","f-b01-c003-059"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"Harek is Asgrim’s son. Breca identifies him as Idrun’s son as well."}]},{"refs":["f-b01-c001-026"],"from":1,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-003"},{"text":"has played with him on the beach at "},{"page":"e-007"},{"text":"."}]},{"refs":["f-b01-c003-005","f-b01-c003-058"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"The family searches Asgrim’s steading and finds no sign of him. Breca says he has been taken. See "},{"text":"his unresolved whereabouts"},{"text":"."}]}],"images":[],"curated":false},{"id":"e-018","file":"e-018.html","source":"characters/Helka","category":"characters","from":2,"names":[{"from":2,"text":"Helka"}],"featured":false,"blocks":[{"refs":["f-b01-c002-034","f-b01-c002-064"],"from":2,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-014"},{"text":"refers to Helka as Queen Helka. A local drengr has collected tax due to her at "},{"page":"e-015"},{"text":"’s farm."}]},{"refs":["f-b01-c002-033","f-b01-c002-032"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"A trader calls Varg’s bronze coin a Helka. The coin bears a woman’s profile."}]},{"refs":["f-b01-c002-035","f-b01-c002-036","f-b01-c002-037"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"Varg has heard talk that she seeks to rule and control half of "},{"page":"e-011"},{"text":". He has also heard of her ruthlessness towards enemies. The stew trader complains that her queenship serves heavy taxation."}]},{"refs":["f-b01-c003-038"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-034"},{"text":"says "},{"page":"e-032"},{"text":" went to Helka’s court in Darl."}]},{"refs":["f-b01-c003-042","f-b01-c003-043","f-b01-c003-045"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-033"},{"text":" reports Sigrún calling Helka just, good and wise. He promotes swearing oaths to her as beneficial to Fellur. Virk objects that her care would be rule."}]},{"refs":["f-b01-c010-021","f-b01-c010-032"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sigrún announces she has sworn her blood oath to Helka. She says Helka will demand coin and oaths."}]},{"refs":["f-b01-c010-034"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sigrún says the bones of Orna tower over Helka’s fortress at Darl."}]},{"refs":["f-b01-c018-074","f-b01-c018-075"],"from":18,"heading":"Story and connections","kind":"story","tokens":[{"text":"At the end of B01-C018, three drakkar bearing eagle images on black sails approach Liga, and Helka comes to the port."}]},{"refs":["f-b01-c020-013","f-b01-c020-014","f-b01-c020-015","f-b01-c020-009","f-b01-c020-008"],"from":20,"heading":"Appearance and visit to Liga","kind":"story","tokens":[{"text":"In B01-C020, Helka is tall, with long black hair braided with gold wire, a red cloak pinned with a gold brooch and an ornate gold-trimmed sword. Her banner is Orna in gold against black sails, and her first moored drakkar is nearly twice the size of the Sea-Wolf."}]},{"refs":["f-b01-c020-010","f-b01-c020-020","f-b01-c020-031","f-b01-c020-032"],"from":20,"heading":"Appearance and visit to Liga","kind":"story","tokens":[{"text":"Her mail-clad, collared "},{"page":"e-148"},{"text":"control access to her. Svik identifies "},{"page":"e-146"},{"text":"as her son and "},{"page":"e-147"},{"text":" as her skáld and Galdurman."}]},{"refs":["f-b01-c020-024","f-b01-c020-025","f-b01-c020-056","f-b01-c020-057"],"from":20,"heading":"Appearance and visit to Liga","kind":"story","tokens":[{"text":"She takes Jaromir’s grievance to Logur’s hall and invites Glornir to join her. Glornir later announces work for her against something eating people in the north; Skalk and two of her warriors travel aboard the Sea-Wolf."}]},{"refs":["f-b01-c031-015","f-b01-c031-018"],"from":31,"heading":"Appearance and visit to Liga","kind":"story","tokens":[{"text":"Helka arrives wearing gold-threaded black braids, a red cloak and gold arm rings. People kneel to Helka as an honour guard escorts her into Darl."}]}],"images":[],"curated":false},{"id":"e-063","file":"e-063.html","source":"characters/Hrut","category":"characters","from":5,"names":[{"from":5,"text":"Hrut"}],"featured":false,"blocks":[{"refs":["f-b01-c005-025","f-b01-c005-026"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Hrut identifies himself as Jarl of Iskalt. He denies knowing a Berak living on his island."}]},{"refs":["f-b01-c005-031"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar cuts his chin and lower lip with a sword."}]},{"refs":["f-b01-c007-001"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"B01-C007 establishes that Agnar has slain Hrut."}]}],"images":[],"curated":false},{"id":"e-154","file":"e-154.html","source":"characters/Huld","category":"characters","from":21,"names":[{"from":21,"text":"Huld"}],"featured":false,"blocks":[{"refs":["f-b01-c032-011"],"from":32,"heading":"Story and connections","kind":"story","tokens":[{"text":"Huld is the next youngest Battle-Grim warrior after Elvar and wears a bear-claw pendant."}]},{"refs":["f-b01-c021-027","f-b01-c021-033"],"from":21,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Huld is named among Agnar’s companions at Snakavik. Their red shields bear the Battle-Grim’s spear-and-axe sigil."}]}],"images":[],"curated":false},{"id":"e-119","file":"e-119.html","source":"characters/Ilia","category":"characters","from":18,"names":[{"from":13,"text":"Ilia"}],"featured":false,"blocks":[{"refs":["f-b01-c013-043","f-b01-c013-044","f-b01-c018-050"],"from":18,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The druzhina woman who threatens Glornir is addressed as Ilia by Jaromir in B01-C013. In B01-C018, she is beside Jaromir at the head of the mounted warriors blocking the docks."}]}],"images":[],"curated":false},{"id":"e-157","file":"e-157.html","source":"characters/Ilska Raven-Feeder","category":"characters","from":21,"names":[{"from":21,"text":"Ilska Raven-Feeder"}],"featured":false,"blocks":[{"refs":["f-b01-c021-031","f-b01-c021-032"],"from":21,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Ilska leads the Raven-Feeders and is also called Ilska the Cruel. Elvar knows the crew by a ruthless reputation."}]},{"refs":["f-b01-c027-015","f-b01-c027-016","f-b01-c027-017"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Ilska has dark hair bound with silver at her nape and wears a grey wool tunic during the escape. Elvar knows the reputational names Ilska the Ruthless and Ilska the Cruel. Agnar vows that Ilska will regret stealing from him."}]},{"refs":["f-b01-c048-032"],"from":48,"heading":"Story and connections","kind":"story","tokens":[{"text":"She arrives at Oskutreð with riders and many wagons while the Battle-Grim gather relics."}]},{"refs":["f-b01-c050-026","f-b01-c050-027","f-b01-c050-004"],"from":50,"heading":"Story and connections","kind":"story","tokens":[{"text":"In the chapter 50 approach, her black hair is wind-whipped behind her and deep lines show around her eyes. She wears fine mail and a dark cloak, carrying a spear with sword and helm at her belt and a round shield on her back."}]},{"refs":["f-b01-c050-006","f-b01-c050-008","f-b01-c050-009","f-b01-c050-011","f-b01-c050-017","f-b01-c050-020","f-b01-c050-021"],"from":50,"heading":"Story and connections","kind":"story","tokens":[{"text":"At Oskutreð she proposes a holmganga and supplies her brother Skrið as champion; Drekr is her other brother. She refuses to release Bjarn, then sends carts of collared children towards the dead tree after Skrið’s defeat."}]},{"refs":["f-b01-c052-016","f-b01-c052-017","f-b01-c052-018","f-b01-c052-019","f-b01-c052-020","f-b01-c052-021","f-b01-c052-022","f-b01-c052-023","f-b01-c052-024","f-b01-c052-026","f-b01-c052-031","f-b01-c052-034","f-b01-c052-037"],"from":52,"heading":"Chapter 52 — The ritual at Oskutreð","kind":"story","tokens":[{"text":"She overcomes Vörn and Uspa, then reads from a red-hide book and uses the collared children, including Bjarn, in a blood rite at the trapdoor. Its opening frees Lik-Rifa. Ilska helps Drekr defeat the golden-winged gaoler and kneels to the dragon, explaining that her people have worked to free her."}]},{"refs":["f-b01-c052-040","f-b01-c052-041"],"from":52,"heading":"Chapter 52 — The ritual at Oskutreð","kind":"story","tokens":[{"text":"Her force reloads the surviving children and follows Lik-Rifa south."}]}],"images":[{"file":"assets/9556c706ab833e.jpg","from":53,"role":"scene","spoiler":true},{"file":"assets/56b2fb6d00346f.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-117","file":"e-117.html","source":"characters/Jaromir","category":"characters","from":13,"names":[{"from":13,"text":"Jaromir"}],"featured":false,"blocks":[{"refs":["f-b01-c013-033"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sergei identifies Prince Jaromir as the Great Khagan’s son."}]},{"refs":["f-b01-c013-042","f-b01-c013-048"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Jaromir accuses Sulich of great crimes. He promises to return next day with evidence and witnesses."}]},{"refs":["f-b01-c018-049","f-b01-c018-050","f-b01-c018-051","f-b01-c018-052"],"from":18,"heading":"Confrontation at the docks","kind":"story","tokens":[{"text":"In B01-C018, Jaromir blocks the Bloodsworn with mounted druzhina, Ilia beside him. He says he intended to present a petition and evidence to Logur, then accuses the Bloodsworn of fleeing because they are guilty. No evidence is presented in this chapter."}]},{"refs":["f-b01-c018-053","f-b01-c018-054","f-b01-c018-055","f-b01-c018-056","f-b01-c018-057","f-b01-c018-060","f-b01-c018-073","f-b01-c018-074"],"from":18,"heading":"Confrontation at the docks","kind":"story","tokens":[{"text":"He demands Sulich and threatens the crew and ship; two torch-bearing riders wait at the pier entrance. When Glornir refuses, Jaromir shoots an arrow, orders a large volley and leads a lance charge. The fighting stops when the three eagle-bannered drakkar appear."}]},{"refs":["f-b01-c020-021","f-b01-c020-023","f-b01-c020-024"],"from":20,"heading":"Confrontation at the docks","kind":"story","tokens":[{"text":"Jaromir introduces himself to Helka as Kirill the Great’s son and complains about Logur denying his request and his warriors’ blood being spilled. Helka takes the grievance to Logur’s hall. No verdict on his allegations is shown in B01-C020."}]}],"images":[],"curated":false},{"id":"e-044","file":"e-044.html","source":"characters/Jökul","category":"characters","from":13,"names":[{"from":4,"text":"Jökul"}],"featured":false,"blocks":[{"refs":["f-b01-c013-008","f-b01-c013-009"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Torvik calls the smith Jökul Hammer-Hand and says he is apprenticed to him. Torvik calls him the best smith in Vigrið."}]},{"refs":["f-b01-c013-052","f-b01-c041-024","f-b01-c041-025"],"from":41,"heading":"Story and connections","kind":"story","tokens":[{"text":"He is broad and thick-waisted in the mead hall. Before the chapter 41 advance, his brows are heavy and his expression dour; he puts on his helm and takes his shield from his back."}]},{"refs":["f-b01-c030-013"],"from":30,"heading":"Story and connections","kind":"story","tokens":[{"text":"Jökul catches two ponies with apples and loads them with supplies using tack found in the stable."}]},{"refs":["f-b01-c041-016"],"from":41,"heading":"Story and connections","kind":"story","tokens":[{"text":"At the guarded excavation, Jökul wears a pitted leather apron over mail and carries a long-hafted hammer with a pitted, stained black-iron head."}]},{"refs":["f-b01-c043-011","f-b01-c043-023","f-b01-c043-024"],"from":43,"heading":"Story and connections","kind":"story","tokens":[{"text":"Jökul's hammer helps break an enemy shield wall. While attacking the troll's toes, he is hit by a flailing limb and lands with twisted limbs; his condition is unresolved at the chapter's end."}]},{"refs":["f-b01-c045-002","f-b01-c045-013"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"After the battle he remains unconscious with a bandaged head wound, but Varg sees him breathing."}]},{"refs":["f-b01-c047-016","f-b01-c047-017"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"By chapter 47 he is awake and freeing captives from their collars with hammer and chisel, still wearing a head bandage. He reveals descent from Gröfu the badger."}]}],"images":[{"file":"assets/b60c517b2408d3.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-099","file":"e-099.html","source":"characters/Kirill","category":"characters","from":20,"names":[{"from":10,"text":"Kirill"}],"featured":false,"blocks":[{"refs":["f-b01-c010-027","f-b01-c013-030","f-b01-c020-021"],"from":20,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sigrún describes Iskidan as ruled by Kirill from Gravka; Sergei calls him the Great Khagan and Kirill the Magnificent. In B01-C020, Jaromir names his father Kirill the Great, Khagan of all Iskidan. These are attributed accounts."}]}],"images":[],"curated":false},{"id":"e-015","file":"e-015.html","source":"characters/Kolskegg","category":"characters","from":2,"names":[{"from":2,"text":"Kolskegg"}],"featured":false,"blocks":[{"refs":["f-b01-c002-012","f-b01-c002-010"],"from":2,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Kolskegg was "},{"page":"e-014"},{"text":"’s master. Varg remembers thirty winters and summers shackled to his farm."}]},{"refs":["f-b01-c002-011","f-b01-c002-077"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"The farm lies twenty leagues north-east of "},{"page":"e-017"},{"text":" along the river. Failure to obey commands there brought a blow or the lash."}]},{"refs":["f-b01-c002-064"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"A local drengr visited the farm to collect tax due to "},{"page":"e-018"},{"text":"."}]},{"refs":["f-b01-c004-048","f-b01-c004-049","f-b01-c004-050","f-b01-c004-051"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"Kolskegg bought Varg and Frøya when they were children. He told Varg their parents sold them for a loaf of bread and twelve duck eggs. In his account Varg was five winters old and Frøya four."}]},{"refs":["f-b01-c004-021","f-b01-c004-022"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"Kolskegg put Varg into bouts against other landed men’s champions. Varg earned him a chest of silver."}]},{"refs":["f-b01-c020-003"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C020, Varg remembers seeing Kolskegg dead with a ragged wound where his throat had been torn out, after Varg regained awareness. The recollection does not identify who inflicted that wound."}]}],"images":[],"curated":false},{"id":"e-056","file":"e-056.html","source":"characters/Kráka","category":"characters","from":5,"names":[{"from":5,"text":"Kráka"}],"featured":false,"blocks":[{"refs":["f-b01-c005-004","f-b01-c005-007"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Kráka is described as a Tainted thrall. She chants magic to keep sea vaesen away from the drakkar."}]},{"refs":["f-b01-c005-062"],"from":5,"heading":"Appearance","kind":"appearance","tokens":[{"text":"In chapter 5, her black hair is plastered to her head by sweat and seawater as she slumps across the ship's prow."}]},{"refs":["f-b01-c005-014","f-b01-c005-015"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"She wears a thrall-collar and chain. A ship-guard kicks her."}]},{"refs":["f-b01-c009-034","f-b01-c009-035"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Kráka says she was asleep when the serpent struck. The narrator says Seiðr-song takes a toll."}]},{"refs":["f-b01-c009-055","f-b01-c009-056"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"In that chapter 9 aftermath, her face is grey with deep-sunken lines, likened to melted wax; this is a description of her condition in that scene. Her hands are long and bony when she strokes the troll antler."}]},{"refs":["f-b01-c009-036","f-b01-c009-037","f-b01-c009-038","f-b01-c009-039"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar gives her a troll antler, describing it as power for the journey. Her collar glows red as he speaks in the Galdur-tongue."}]},{"refs":["f-b01-c009-040"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"She resumes her serpent-song as the ship turns south."}]},{"refs":["f-b01-c014-004","f-b01-c014-019"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Kráka identifies the surviving oath stone. She says the gods are the parents of the Tainted."}]},{"refs":["f-b01-c027-018"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Kráka tends the wounded Biórr after the raid."}]},{"refs":["f-b01-c029-004","f-b01-c029-017"],"from":29,"heading":"Story and connections","kind":"story","tokens":[{"text":"Kráka describes the Guðfalla as a song in the Tainted's blood and says their ancestors fell at the tree. Kráka describes the blóð svarið as a binding made with blood, runes and words of power, with death for breaking it."}]},{"refs":["f-b01-c052-002"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr removes her thrall-collar along with Ilmur’s after Agnar’s death."}]}],"images":[{"file":"assets/7b23d6f8ef5143.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-042","file":"e-042.html","source":"characters/Leif Kolskeggson","category":"characters","from":4,"names":[{"from":4,"text":"Leif Kolskeggson"}],"featured":false,"blocks":[{"refs":["f-b01-c004-063","f-b01-c004-070"],"from":4,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Varg identifies his pursuer as Leif. Leif names himself Leif Kolskeggson in B01-C004."}]},{"refs":["f-b01-c004-064","f-b01-c004-065"],"from":4,"heading":"Appearance","kind":"appearance","tokens":[{"text":"He has a black beard. A scar runs through his lip."}]},{"refs":["f-b01-c004-066","f-b01-c004-080","f-b01-c004-067"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"He accuses Varg of butchering his father. He also accuses Varg of slaying three other freedmen. Varg recalls blood and carnage after coming to his senses at Snepil’s death."}]},{"refs":["f-b01-c004-071","f-b01-c004-068","f-b01-c004-094"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"Leif claims Varg as his thrall and property. Varg asserts that he earned his freedom. Leif invokes a right of "},{"page":"e-050"},{"text":" to claim him."}]},{"refs":["f-b01-c004-073","f-b01-c004-074","f-b01-c004-075"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"Leif cuts Varg’s ribs with his spear. He threatens to drag Varg behind his horse back to the farm. He threatens to force Varg to work for him for life."}]},{"refs":["f-b01-c004-083","f-b01-c004-087","f-b01-c004-095"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"He promises to have "},{"page":"e-043"},{"text":"carve Varg a wooden hand. The "},{"page":"e-051"},{"text":" intervenes, leaving Leif doubled over and dropping the cleaver. The rescuer declares Varg one of the Bloodsworn."}]}],"images":[],"curated":false},{"id":"e-090","file":"e-090.html","source":"characters/Lif","category":"characters","from":12,"names":[{"from":10,"text":"Lif"}],"featured":false,"blocks":[{"refs":["f-b01-c012-028","f-b01-c012-035"],"from":12,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Lif is Virk’s younger son. He says Guðvarr goaded Virk."}]},{"refs":["f-b01-c015-004","f-b01-c015-007","f-b01-c015-005","f-b01-c015-008","f-b01-c015-026"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"The family helps Virk’s sons raise his barrow. Lif sheds constant tears, and he and Mord welcome Orka’s family to their hearth afterwards. They decline Thorkel’s invitation to his steading. Orka says they have a fishing boat and a trade taught by Virk."}]},{"refs":["f-b01-c022-006","f-b01-c022-008","f-b01-c022-009","f-b01-c022-012","f-b01-c022-044","f-b01-c022-045","f-b01-c022-046"],"from":22,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka finds the brothers bound at Fellur’s hall. Lif says they tried unsuccessfully to kill Guðvarr and face trial, with outlawry or execution threatened. Orka frees them. They wait in their fishing boat, take Orka aboard and row away at her order to head south for the sea."}]},{"refs":["f-b01-c024-002","f-b01-c024-003","f-b01-c024-010","f-b01-c024-016","f-b01-c024-020"],"from":24,"heading":"Story and connections","kind":"story","tokens":[{"text":"Lif has crow-dark hair and is tall, slim and lithe. Lif appears to Orka to be no older than seventeen or eighteen winters; his exact age is not established. Lif cleans and rebinds Mord's head wound. Lif asks Orka to teach the brothers weapons craft. Orka agrees to teach the brothers what she can in exchange for their rowing her to Darl."}]},{"refs":["f-b01-c024-021","f-b01-c024-022","f-b01-c028-026"],"from":28,"heading":"Story and connections","kind":"story","tokens":[{"text":"He has dark, wide eyes and a patchy beard with pale skin showing beneath it. During the chapter 28 summer rowing passage, he wears a linen tunic."}]},{"refs":["f-b01-c028-021"],"from":28,"heading":"Story and connections","kind":"story","tokens":[{"text":"Lif helps Orka reach shore with a spear, and the Näcken retreats underwater; its death is not established."}]},{"refs":["f-b01-c031-003","f-b01-c031-021","f-b01-c031-022"],"from":31,"heading":"Story and connections","kind":"story","tokens":[{"text":"Mord and Lif are bruised by their weapons lessons; Mord persists despite his more serious wounds. Orka gives Lif money, judging that the brothers' rowing has earned more than her lessons repaid. Orka again advises the brothers to settle quietly and delay revenge, then leaves to search for Breca."}]},{"refs":["f-b01-c035-030","f-b01-c035-031"],"from":35,"heading":"Story and connections","kind":"story","tokens":[{"text":"Lif and Mord arrive on horses and break into the ring to rescue Orka. Orka climbs behind Lif and escapes down an alley, leaving Drekr alive on the street."}]},{"refs":["f-b01-c040-006","f-b01-c040-017"],"from":40,"heading":"Story and connections","kind":"story","tokens":[{"text":"Lif questions the escape route in Orka's proposed bait plan. During the subsequent flight he takes a spear thrown by one of Guðvarr's drengrs."}]},{"refs":["f-b01-c046-010","f-b01-c046-013","f-b01-c046-015"],"from":46,"heading":"Story and connections","kind":"story","tokens":[{"text":"He recognises wings on the blood-coated carving. During further training Orka judges him calmer and more receptive than Mord. He has removed the stitches from her back wound."}]},{"refs":["f-b01-c049-016","f-b01-c049-017","f-b01-c049-024","f-b01-c049-026"],"from":49,"heading":"Story and connections","kind":"story","tokens":[{"text":"In the frost-spider fight near Grimholt he is bitten in the shoulder, turns blue and stiff and collapses convulsing. Orka attempts to carry him out but is struck down before they escape."}]},{"refs":["f-b01-c051-001","f-b01-c051-012","f-b01-c051-014"],"from":51,"heading":"Story and connections","kind":"story","tokens":[{"text":"He is alive but still shivering and blue-veined when taken into Grimholt. After Guðvarr stabs Mord, Orka breaks free and cuts Lif’s bonds."}]}],"images":[{"file":"assets/eef75140999ff6.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-023","file":"e-023.html","source":"characters/Logur","category":"characters","from":13,"names":[{"from":2,"text":"Logur"}],"featured":false,"blocks":[{"refs":["f-b01-c013-001","f-b01-c013-031"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Logur hosts the feast with Glornir and Vol at the high table. He embraces Sergei as an old friend."}]},{"refs":["f-b01-c013-047"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"He demands witnesses and evidence for Jaromir’s accusations and refers the claim to an Althing."}]},{"refs":["f-b01-c016-022","f-b01-c016-024","f-b01-c016-018","f-b01-c016-021","f-b01-c016-023"],"from":16,"heading":"Story and connections","kind":"story","tokens":[{"text":"Logur’s wife is "},{"page":"e-131"},{"text":", as established in B01-C016. He welcomes the Bloodsworn at his hearth for a day or a winter and promises provisions for their departure. Sälla says he means that he will ask her to make the arrangements."}]},{"refs":["f-b01-c018-043","f-b01-c018-036","f-b01-c018-038","f-b01-c018-073"],"from":18,"heading":"Story and connections","kind":"story","tokens":[{"text":"Torvik says the Bloodsworn’s former chief Skullsplitter gave Logur the rafter relic, which he identifies as a Vackna Horn fragment and credits with making Logur rich. Logur arrives at the dockside with blue-shielded warriors as the fighting stops."}]},{"refs":["f-b01-c020-002","f-b01-c020-020","f-b01-c020-024"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"Logur’s drengrs keep the Bloodsworn and druzhina separated after the battle. Helka admits Logur without his oathmen and directs him to lead the parties to his hall to hear Jaromir’s grievances."}]}],"images":[],"curated":false},{"id":"e-089","file":"e-089.html","source":"characters/Mord","category":"characters","from":12,"names":[{"from":10,"text":"Mord"}],"featured":false,"blocks":[{"refs":["f-b01-c012-027","f-b01-c012-034","f-b01-c012-018"],"from":12,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Mord is Virk’s older son. He asks Sigrún for justice after the fatal attack on his father."}]},{"refs":["f-b01-c015-003","f-b01-c015-004","f-b01-c015-005","f-b01-c015-006","f-b01-c015-008","f-b01-c015-026"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka recalls that she and Thorkel restrained Mord from attacking Guðvarr and Sigrún’s thrall. The family helps raise Virk’s barrow, and Mord and Lif feed them afterwards. Mord mutters oaths of vengeance and the brothers decline Thorkel’s invitation to the steading. Orka says Virk left his sons a fishing boat and taught them a trade."}]},{"refs":["f-b01-c022-006","f-b01-c022-008","f-b01-c022-009","f-b01-c022-012","f-b01-c022-044","f-b01-c022-045","f-b01-c022-046"],"from":22,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka finds the brothers bound at Fellur’s hall. Lif says they tried unsuccessfully to kill Guðvarr and face trial, with outlawry or execution threatened. Orka frees them. They wait in their fishing boat, take Orka aboard and row away at her order to head south for the sea."}]},{"refs":["f-b01-c024-004","f-b01-c024-005","f-b01-c024-009","f-b01-c024-015"],"from":24,"heading":"Story and connections","kind":"story","tokens":[{"text":"Mord is fair-haired, broad-faced and solid, with a thick beard. Mord's head wound continues to bleed through its bandage. Mord warns that Sigrún may send searchers in every direction; no actual search deployment is observed here. Orka advises waiting until Fellur's alarm and search have subsided before seeking revenge."}]},{"refs":["f-b01-c028-003","f-b01-c028-006","f-b01-c028-009","f-b01-c028-015"],"from":28,"heading":"Story and connections","kind":"story","tokens":[{"text":"Mord weaves willow branches into a fish trap while Orka and Lif row. Orka suggests going ashore to walk around rapids, but Mord argues they can row through. An impact lifts the boat's prow and throws Mord into the water. The Näcken bites Mord's shoulder."}]},{"refs":["f-b01-c031-002","f-b01-c031-003"],"from":31,"heading":"Story and connections","kind":"story","tokens":[{"text":"Mord's Näcken bite is healing well, and his head retains a red scar from Guðvarr's blow. Mord and Lif are bruised by their weapons lessons; Mord persists despite his more serious wounds."}]},{"refs":["f-b01-c035-030"],"from":35,"heading":"Story and connections","kind":"story","tokens":[{"text":"Lif and Mord arrive on horses and break into the ring to rescue Orka."}]},{"refs":["f-b01-c040-002","f-b01-c040-008","f-b01-c040-012"],"from":40,"heading":"Story and connections","kind":"story","tokens":[{"text":"Mord's arm still bleeds from Skefil's wound when Guðvarr's company appears at the lodging farm. He follows Orka's decision to flee north rather than fight."}]},{"refs":["f-b01-c037-012"],"from":37,"heading":"Story and connections","kind":"story","tokens":[{"text":"The later description explicitly identifies his beard as blond. A documented "},{"text":" separates his observed features from the portrait's artistic choices."}]},{"refs":["f-b01-c046-012","f-b01-c046-013","f-b01-c046-022"],"from":46,"heading":"Story and connections","kind":"story","tokens":[{"text":"He continues practising against Orka with a wool-wrapped seax. Orka judges his impatience a weakness compared with Lif’s calmer approach, and warns both brothers about fighting armoured warriors in wool."}]},{"refs":["f-b01-c049-013","f-b01-c049-016","f-b01-c049-020","f-b01-c049-025"],"from":49,"heading":"Story and connections","kind":"story","tokens":[{"text":"He fights frost-spiders beside Orka and Lif, stands over his poisoned brother and keeps attackers back, despite his fear. When warriors surround them he spears one through the throat."}]},{"refs":["f-b01-c051-001","f-b01-c051-005","f-b01-c051-012"],"from":51,"heading":"Story and connections","kind":"story","tokens":[{"text":"Bound in Grimholt’s tower, he is stabbed through the belly by Guðvarr. The chapter leaves the severity evident but does not establish his final fate."}]}],"images":[{"file":"assets/86b64ffdd7ac3e.jpg","from":43,"role":"primary","spoiler":false}],"curated":false},{"id":"e-165","file":"e-165.html","source":"characters/Olvir","category":"characters","from":26,"names":[{"from":26,"text":"Olvir"}],"featured":false,"blocks":[{"refs":["f-b01-c026-017","f-b01-c026-019","f-b01-c026-020"],"from":26,"heading":"Appearance","kind":"introduction","tokens":[{"text":"Olvir is the male royal guard travelling with Skalk. Olvir has a scar over one eyebrow. Both royal guards wear dark cloaks pinned with silver eagle-wing brooches."}]},{"refs":["f-b01-c045-027","f-b01-c045-034"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"He holds Varg at swordpoint during the attack on Torvik. Varg later grapples with and bites him; his movements slow, but his subsequent condition is not established here."}]},{"refs":["f-b01-c047-001"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"Varg sees his corpse with a ragged open throat in chapter 47, establishing his death after Varg’s attack."}]}],"images":[],"curated":false},{"id":"e-001","file":"e-001.html","source":"characters/Orka","category":"characters","from":1,"names":[{"from":1,"text":"Orka"}],"featured":true,"blocks":[{"refs":["f-b01-c001-002","f-b01-c001-003","f-b01-c001-007"],"from":1,"heading":"Home and family","kind":"introduction","tokens":[{"text":"Orka is Thorkel's wife and Breca's mother. She worries that her son is too gentle for the world around him."}]},{"refs":["f-b01-c001-018","f-b01-c001-015","f-b01-c001-017","f-b01-c001-019"],"from":1,"heading":"Appearance","kind":"appearance","tokens":[{"text":"She has blonde hair and grey-green eyes like Breca's. During the family's climb to the steading, her hair is braided."}]},{"refs":["f-b01-c003-027","f-b01-c003-061","f-b01-c003-075"],"from":3,"heading":"Appearance","kind":"appearance","tokens":[{"text":"Her size is described through comparison: she is taller than Virk, and both taller and wider than Guðvarr."}]},{"refs":["f-b01-c001-042","f-b01-c001-043","f-b01-c001-049","f-b01-c001-050"],"from":1,"heading":"The life she tries to hold together","kind":"story","tokens":[{"text":"Violence intrudes on Orka's thoughts even before it reaches her own home. The injured wolf's blood brings images of death, and danger stirs a familiar physical response. At Asgrim's steading she puts an axe in his hand and urges him to travel the soul road armed."}]},{"refs":["f-b01-c006-001","f-b01-c006-002","f-b01-c006-003","f-b01-c006-019","f-b01-c006-028","f-b01-c006-030","f-b01-c006-031"],"from":6,"heading":"The life she tries to hold together","kind":"story","tokens":[{"text":"Battle also follows her into sleep. She wants alcohol to quiet the memories, although Thorkel has asked her to drink less. When fear for Breca turns into anger at the pool, Thorkel restrains her; she has learned to trust his judgement when her blood is high."}]},{"refs":["f-b01-c015-028","f-b01-c015-027","f-b01-c015-029","f-b01-c015-031","f-b01-c015-032","f-b01-c015-033"],"from":15,"heading":"The life she tries to hold together","kind":"story","tokens":[{"text":"Orka tells Breca that her own parents died when she was about ten or eleven, and remembers wanting to forget them. Yet she teaches him that courage means doing what must be done despite fear, and his appeal moves her to free a moth from a spiderweb."}]},{"refs":["f-b01-c015-042","f-b01-c015-044","f-b01-c015-043","f-b01-c015-048","f-b01-c015-050","f-b01-c015-047"],"from":15,"heading":"The life she tries to hold together","kind":"story","tokens":[{"text":"She asks Thorkel to leave the area with her. He agrees, and she tells him that he and Breca are her home wherever they live. Before dawn she leaves Spert guarding the locked steading and sets out with her spear."}]},{"refs":["f-b01-c017-001","f-b01-c017-004","f-b01-c017-005","f-b01-c017-016","f-b01-c017-020","f-b01-c017-019","f-b01-c017-022","f-b01-c017-023","f-b01-c017-024","f-b01-c017-027","f-b01-c017-030","f-b01-c017-031","f-b01-c017-029"],"from":17,"heading":"A home destroyed","kind":"story","tokens":[{"text":"Returning to a burning hall and a destroyed rune-post, Orka drags the wounded Thorkel outside. He tells her that Breca has been taken. She promises to recover their son, but Thorkel dies after saying 'Dragon-born' and apologising. Orka rescues Vesli and places Thorkel's long-axe in his hand before the hall collapses."}]},{"refs":["f-b01-c017-032","f-b01-c017-034","f-b01-c017-038","f-b01-c017-039","f-b01-c017-047","f-b01-c017-044","f-b01-c017-046","f-b01-c017-059","f-b01-c017-060","f-b01-c017-067","f-b01-c017-062","f-b01-c017-068","f-b01-c017-069"],"from":17,"heading":"A home destroyed","kind":"story","tokens":[{"text":"Her pursuit leads to a group beside the river. Fighting leaves her wounded, and a violent interrogation gives her the name Drekr, but not Breca's destination. She kills the young captive after obtaining the name."}]},{"refs":["f-b01-c019-012","f-b01-c019-015","f-b01-c019-029","f-b01-c019-032","f-b01-c019-033","f-b01-c019-035","f-b01-c019-037","f-b01-c019-040","f-b01-c019-041","f-b01-c019-043","f-b01-c019-044","f-b01-c019-047","f-b01-c019-060","f-b01-c019-057","f-b01-c019-061"],"from":19,"heading":"Burial, vengeance and a new road","kind":"story","tokens":[{"text":"Back at the steading, Vesli tends Orka's wounds. Orka releases both vaesen from their oaths, unearths her old equipment and buries Thorkel beneath a timber-and-stone barrow. She takes the blades that killed him, puts on her recovered mail and leaves determined to find their owner."}]},{"refs":["f-b01-c022-001","f-b01-c022-008","f-b01-c022-009","f-b01-c022-016","f-b01-c022-020","f-b01-c022-021","f-b01-c022-023","f-b01-c022-024","f-b01-c022-025","f-b01-c022-026","f-b01-c022-027","f-b01-c022-043","f-b01-c022-044","f-b01-c022-045"],"from":22,"heading":"Burial, vengeance and a new road","kind":"story","tokens":[{"text":"In Fellur she frees Mord and Lif and forces information from Sigrún's warrior-thrall, who names herself Vafri. Vafri identifies Hakon as her master and Drekr as her contact; Darl is only her guess about Breca's destination. Orka escapes by boat with the brothers."}]},{"refs":["f-b01-c024-017","f-b01-c024-020","f-b01-c028-004","f-b01-c028-010","f-b01-c028-011","f-b01-c031-001","f-b01-c031-004","f-b01-c031-020","f-b01-c031-021","f-b01-c031-022"],"from":31,"heading":"Burial, vengeance and a new road","kind":"story","tokens":[{"text":"The brothers row her towards Darl in exchange for weapons training. They keep to smaller waterways to avoid pursuit, and Orka rescues Mord from the river. At Darl she ends their arrangement, pays Lif and urges both men to put off revenge while she searches for Breca."}]},{"refs":["f-b01-c033-001","f-b01-c033-005","f-b01-c033-016","f-b01-c033-018","f-b01-c033-019","f-b01-c035-003","f-b01-c035-005","f-b01-c035-016","f-b01-c035-021","f-b01-c035-025","f-b01-c035-026","f-b01-c035-031"],"from":35,"heading":"The search in Darl","kind":"story","tokens":[{"text":"Orka follows her enquiries through Darl's taverns to the Dead Drengr, freeing captive children on the way. A small wooden sword on a broken cord is recognisable as Breca's pendant, but it does not establish his present location. Fighting Drekr leaves her wounded and nearly strangled; a sudden sharpening of strength and senses helps her escape alive with Lif."}]},{"refs":["f-b01-c040-012","f-b01-c040-013","f-b01-c040-015","f-b01-c040-019","f-b01-c046-006","f-b01-c046-007","f-b01-c046-008","f-b01-c046-009","f-b01-c046-010","f-b01-c046-011","f-b01-c046-016"],"from":46,"heading":"The road to Grimholt","kind":"story","tokens":[{"text":"Guðvarr's arrival forces Orka and the brothers north. She burns a bridge to delay him and makes for Grimholt Pass. Along the way she finds a broken oath stone and signs she associates with Lik-Rifa worship; its connection to Breca's abduction remains her speculation."}]},{"refs":["f-b01-c049-001","f-b01-c049-006","f-b01-c049-007","f-b01-c049-008","f-b01-c049-012","f-b01-c049-017","f-b01-c049-021","f-b01-c049-024","f-b01-c049-026"],"from":49,"heading":"The road to Grimholt","kind":"story","tokens":[{"text":"Near Grimholt, Orka helps two speaking ravens caught among frost-spiders, remembering Breca's rescue of the moth. The intervention ends in capture: her leg is numbed by web, Lif is bitten, and an unnamed staff-bearer strikes her down as she tries to carry him away."}]},{"refs":["f-b01-c051-001","f-b01-c051-004","f-b01-c051-012","f-b01-c051-013","f-b01-c051-016","f-b01-c051-014","f-b01-c051-015","f-b01-c051-017","f-b01-c051-018","f-b01-c051-019","f-b01-c051-020","f-b01-c051-021","f-b01-c051-022","f-b01-c051-023","f-b01-c051-024"],"from":51,"heading":"What emerges at Grimholt","kind":"story","tokens":[{"text":"When Guðvarr stabs the bound Mord, Orka's senses, strength and teeth change. The narration now explicitly names the wolf in her blood. She bites through her bonds, frees Lif and wounds Skalk. The ravens repay her help by bringing Spert and Vesli through the roof, and together they drive the guards out."}]},{"refs":["f-b01-c053-008","f-b01-c053-009","f-b01-c053-010","f-b01-c053-011","f-b01-c053-012","f-b01-c053-013","f-b01-c053-014","f-b01-c053-016"],"from":53,"heading":"What emerges at Grimholt","kind":"story","tokens":[{"text":"The Bloodsworn find her on Grimholt's steps with Spert, Vesli and a group of children. The person she seeks is not among them. Glornir recognises her as Orka Skullsplitter, and they embrace: the old identity becomes established here, rather than being knowledge the reader possessed from the beginning."}]}],"images":[{"file":"assets/e1881d728bcb46.jpg","from":21,"role":"primary","spoiler":false}],"curated":true},{"id":"e-043","file":"e-043.html","source":"characters/Orl","category":"characters","from":4,"names":[{"from":4,"text":"Orl"}],"featured":false,"blocks":[{"refs":["f-b01-c004-076","f-b01-c004-077","f-b01-c004-078"],"from":4,"heading":"Appearance","kind":"introduction","tokens":[{"text":"Leif orders the houndsman Orl to tend the injured pursuers. Orl wears an iron collar. He has thin grey hair."}]},{"refs":["f-b01-c004-079","f-b01-c004-083"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"He cleans the wounded woman’s injury. Leif promises to have him carve Varg a wooden hand for farm work."}]},{"refs":["f-b01-c004-092","f-b01-c004-093"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-021"},{"text":" growls at his hound. The hound withdraws against Orl."}]}],"images":[],"curated":false},{"id":"e-046","file":"e-046.html","source":"characters/Røkia","category":"characters","from":4,"names":[{"from":4,"text":"Unnamed blonde woman at the trial"},{"from":11,"text":"Røkia"}],"featured":false,"blocks":[{"refs":["f-b01-c004-006","f-b01-c004-096","f-b01-c004-097"],"from":4,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The blonde woman offers Varg a wooden shield. She has a black shield and wears a brynja at the trial."}]},{"refs":["f-b01-c004-012","f-b01-c004-013","f-b01-c004-014"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"She says she is no one’s thrall to be ordered. She announces him as Varg No-Sense in B01-C004. She announces the challenge as being for a place on the Bloodsworn’s oar-bench and shield wall."}]},{"refs":["f-b01-c011-001"],"from":11,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"Svik identifies the previously unnamed shield-offering woman as Røkia in B01-C011."}]},{"refs":["f-b01-c011-013","f-b01-c011-014"],"from":11,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"She says Glornir ordered her to train Varg. She says every Bloodsworn must know how to use a shield."}]},{"refs":["f-b01-c011-025","f-b01-c011-026","f-b01-c011-029","f-b01-c011-028","f-b01-c011-030"],"from":11,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"She teaches a gap between shield and torso, weapon use and keeping sight of the opponent. Moving drills cut Varg’s shoulder and finish with her spear at his throat."}]},{"refs":["f-b01-c016-002","f-b01-c016-038"],"from":16,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"Røkia intentionally nicks Varg with her spear during training. Glornir reports that she considers him fast, balanced and possessed of a warrior’s spirit."}]},{"refs":["f-b01-c018-012","f-b01-c018-019","f-b01-c018-058"],"from":18,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"Røkia recommends an axe for Varg and says mail should be won from an enemy in a fight. During the dockside battle she joins Einar and others in shielding Glornir from arrows."}]},{"refs":["f-b01-c018-076"],"from":18,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"In B01-C018, the narrator explicitly identifies Røkia and Svik as the Bloodsworn warriors accompanying Varg."}]},{"refs":["f-b01-c026-008","f-b01-c026-011","f-b01-c026-012"],"from":26,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"Røkia requires Varg to train while wet, explaining that enemies will not wait for comfortable conditions. Røkia's practice strike is followed by a shield shove and trip that put Varg on the ground. Røkia advises changing grip after a failed strike and continuing to fight after a nonfatal wound."}]},{"refs":["f-b01-c004-107","f-b01-c026-029","f-b01-c026-030"],"from":26,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"She is tall and blonde, with a sharp-angled face. Her chapter 26 training equipment includes a spear and a linen-wrapped shield. A documented "},{"text":" separates these observations from artistic choices."}]},{"refs":["f-b01-c047-011","f-b01-c047-012","f-b01-c047-023"],"from":47,"heading":"Affiliation in reading chronology","kind":"story","tokens":[{"text":"She identifies herself and Varg as Úlfhéðnar descended from Ulfrir, connecting his red mist to his suppressed god-touched nature. She gives him the slain swordsman’s mail and helm as earned spoils."}]}],"images":[{"file":"assets/847b845b73bebc.jpg","from":43,"role":"primary","spoiler":false}],"curated":false},{"id":"e-115","file":"e-115.html","source":"characters/Sergei Yanasson","category":"characters","from":13,"names":[{"from":13,"text":"Sergei Yanasson"}],"featured":false,"blocks":[{"refs":["f-b01-c013-029","f-b01-c013-032"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The guard introduces Sergei Yanasson of Ulaz. He calls himself a merchant from the southlands."}]},{"refs":["f-b01-c013-031","f-b01-c013-033"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Logur embraces him as an old friend. Sergei introduces Jaromir as the Khagan’s son."}]},{"refs":["f-b01-c013-046"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"He intervenes between Glornir and the threatening druzhina warrior."}]}],"images":[],"curated":false},{"id":"e-054","file":"e-054.html","source":"characters/Sighvat","category":"characters","from":5,"names":[{"from":5,"text":"Sighvat"}],"featured":false,"blocks":[{"refs":["f-b01-c005-002"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sighvat beats rowing time on a barrel."}]},{"refs":["f-b01-c005-016","f-b01-c005-017"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"He names the warband the Battle-Grim. He calls them hunters of the Tainted."}]},{"refs":["f-b01-c048-022","f-b01-c048-023","f-b01-c048-024","f-b01-c048-025","f-b01-c048-026"],"from":48,"heading":"Chapter 48 — Bound at Oskutreð","kind":"story","tokens":[{"text":"At Oskutreð he attacks Vörn despite her prohibition. She traps his axe in her staff, strikes him down and binds him in vines until the company’s departure, conditional on Agnar keeping his word."}]},{"refs":["f-b01-c048-033"],"from":48,"heading":"Chapter 48 — Bound at Oskutreð","kind":"story","tokens":[{"text":"He is tall, broad-shouldered and fat-bellied."}]}],"images":[{"file":"assets/eb790d69f84ecc.jpg","from":53,"role":"scene","spoiler":true}],"curated":false},{"id":"e-032","file":"e-032.html","source":"characters/Sigrún","category":"characters","from":3,"names":[{"from":3,"text":"Sigrún"}],"featured":false,"blocks":[{"refs":["f-b01-c003-023","f-b01-c003-028","f-b01-c003-029"],"from":3,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sigrún is Jarl of "},{"page":"e-007"},{"text":". "},{"page":"e-033"},{"text":" is her nephew. He is also one of her drengrs."}]},{"refs":["f-b01-c010-049","f-b01-c010-050"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"At the Althing she is tall, though shorter and less wide than Orka, and walks with a warrior's strength and grace. She wears riveted mail, a silver neck torc and silver arm rings."}]},{"refs":["f-b01-c003-038","f-b01-c003-039","f-b01-c003-040"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-034"},{"text":"says she went to "},{"page":"e-018"},{"text":"’s court in Darl. He says she has been away more than two months. He changes his description of the visit from summoned to invited."}]},{"refs":["f-b01-c003-041","f-b01-c003-042","f-b01-c003-043"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"Guðvarr announces that she will return within a nine-day. He reports her calling Helka just, good and wise. He presents swearing oaths to Helka as beneficial to the village."}]},{"refs":["f-b01-c003-049","f-b01-c003-050"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"Guðvarr announces an "},{"page":"e-040"},{"text":"after her return. It is to be held on the "},{"page":"e-037"},{"text":"."}]},{"refs":["f-b01-c008-026","f-b01-c008-027"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"Guðvarr says Sigrún has returned and called an Althing in six days."}]},{"refs":["f-b01-c010-019","f-b01-c010-021","f-b01-c010-022"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sigrún has ruled for eight years. At the Althing she announces she has sworn her blood oath to Helka and shows a cut."}]},{"refs":["f-b01-c010-033","f-b01-c010-032","f-b01-c010-024","f-b01-c010-025"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"She says Helka would seize Fellur if refused and will demand coin and oaths. She claims Störr is expanding and Orlyg has raided her lands."}]},{"refs":["f-b01-c010-036","f-b01-c010-037"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"She defends Guðvarr’s search as doing all that could be done; Virk calls it a lie."}]},{"refs":["f-b01-c012-023","f-b01-c012-024","f-b01-c012-025","f-b01-c012-037"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sigrún says she ordered her thrall to stop Virk, not kill him. Her commands coincide with red collar fire and the fading of the thrall’s changes."}]},{"refs":["f-b01-c012-029","f-b01-c012-030"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"She rules justice done because Virk broke holmganga, and suspends the Althing."}]},{"refs":["f-b01-c022-009","f-b01-c022-016","f-b01-c022-017","f-b01-c022-018","f-b01-c022-019","f-b01-c022-030","f-b01-c022-037"],"from":22,"heading":"Orka’s raid","kind":"story","tokens":[{"text":"Lif reports that Sigrún has threatened outlawry or execution at the brothers’ coming trial. Orka enters her sleeping chamber and cuts her lover’s throat. She strikes Sigrún’s jaw and later slashes her face from forehead to chin. Sigrún attacks again but trips over the bed after Orka parries."}]}],"images":[{"file":"assets/b1584eddb3300e.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-095","file":"e-095.html","source":"characters/Sigrún’s warrior-thrall","category":"characters","from":10,"names":[{"from":10,"text":"Sigrún’s warrior-thrall"},{"from":22,"text":"Vafri"}],"featured":false,"blocks":[{"refs":["f-b01-c010-020","f-b01-c010-045"],"from":10,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The woman beside Sigrún has a tattooed head and wears a thrall collar."}]},{"refs":["f-b01-c012-014","f-b01-c012-016","f-b01-c012-015","f-b01-c012-036"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"The warrior-thrall stabs Virk and tears his face with her teeth. Her eyes turn amber and teeth sharp."}]},{"refs":["f-b01-c012-019","f-b01-c012-017","f-b01-c012-020"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"Thorkel calls her Ulfrir-kin and kicks her off Virk. She cuts him during the next exchange."}]},{"refs":["f-b01-c012-021","f-b01-c012-024","f-b01-c012-025","f-b01-c012-037"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"A collar flash coincides with her collapse; further commands from Sigrún precede the fading of her changes."}]},{"refs":["f-b01-c015-035","f-b01-c015-036","f-b01-c015-038","f-b01-c015-039"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C015, Thorkel identifies her as "},{"page":"e-130"},{"text":". Orka says she tasted Thorkel’s blood from her seax, while Thorkel says it might have been Virk’s. He argues that she is not Hundur and the blood would mean nothing to her."}]},{"refs":["f-b01-c022-020","f-b01-c022-021","f-b01-c022-022","f-b01-c022-023","f-b01-c022-024","f-b01-c022-025"],"from":22,"heading":"Name and testimony revealed in B01-C022","kind":"story","tokens":[{"text":"The warrior-thrall identifies herself as Vafri when Orka holds her at blade-point. She claims descent from both Ulfrir and Hundur, adding her own account to the earlier disagreement between Thorkel and Orka. She identifies "},{"page":"e-146"},{"text":"as her master and says she was ordered to report signs of the Tainted to "},{"page":"e-138"},{"text":"."}]},{"refs":["f-b01-c022-026","f-b01-c022-027","f-b01-c022-028","f-b01-c022-032","f-b01-c022-033","f-b01-c022-035","f-b01-c022-036","f-b01-c022-040","f-b01-c022-041"],"from":22,"heading":"Name and testimony revealed in B01-C022","kind":"story","tokens":[{"text":"She says she does not know Breca’s destination. Forced to guess, she offers Darl; this remains a suggestion under threat. She attacks Orka, raking with nails like claws; Orka breaks her arm, damages her face and stabs her belly. Orka takes her seax and leaves her described as dying."}]},{"refs":["f-b01-c024-014"],"from":24,"heading":"Name and testimony revealed in B01-C022","kind":"story","tokens":[{"text":"Orka says Vafri may already be dead but may yet survive her gut wound; her death remains unconfirmed here."}]}],"images":[],"curated":false},{"id":"e-158","file":"e-158.html","source":"characters/Silrið","category":"characters","from":21,"names":[{"from":21,"text":"Silrið"}],"featured":false,"blocks":[{"refs":["f-b01-c021-052","f-b01-c021-046"],"from":21,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Störr addresses the blonde woman at his shoulder as Silrið. She is tall, with a bone necklace, rune tattoos on her hands and a yellow wool tunic."}]},{"refs":["f-b01-c021-053","f-b01-c021-055","f-b01-c021-056","f-b01-c021-057","f-b01-c021-059","f-b01-c021-064","f-b01-c021-065"],"from":21,"heading":"Story and connections","kind":"story","tokens":[{"text":"Silrið obtains Berak’s blood by cutting his arm, wakes Hrung and wipes the blood onto his tongue for testing. She takes Berak’s chain and leads him away after the price is agreed; Störr says she will bring Agnar his payment. Her exact office is not stated."}]},{"refs":["f-b01-c023-024"],"from":23,"heading":"Story and connections","kind":"story","tokens":[{"text":"Silrið suggests searching for another path to fulfil their ambitions; its specific nature is unstated."}]}],"images":[],"curated":false},{"id":"e-147","file":"e-147.html","source":"characters/Skalk","category":"characters","from":20,"names":[{"from":20,"text":"Skalk"}],"featured":false,"blocks":[{"refs":["f-b01-c020-032","f-b01-c020-017","f-b01-c020-018","f-b01-c020-019"],"from":20,"heading":"Appearance","kind":"introduction","tokens":[{"text":"Svik identifies Skalk as Helka’s skáld and Galdurman. He is tall, with braided blond hair and beard, a thick torc and a gnarled staff. Varg sees pewter rings and what resemble small animal skulls in his braids; knotwork tattoos cover his hands and extend up his sleeves."}]},{"refs":["f-b01-c020-048","f-b01-c020-057"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"Skalk accompanies Glornir back from the hall and travels aboard the Sea-Wolf with two of Helka’s warriors. Glornir orders them to row."}]},{"refs":["f-b01-c026-021","f-b01-c026-022","f-b01-c026-023","f-b01-c026-024","f-b01-c026-026","f-b01-c026-028"],"from":26,"heading":"Story and connections","kind":"story","tokens":[{"text":"Skalk says the mission goes to the River Slågen's source at the Bonebacks, on Helka's northwestern border. Skalk reports disappearances initially blamed on Störr's raids, followed by discoveries of partly eaten remains. Skalk admits the vaesen's identity is unknown and that there are no witnesses. Skalk estimates that the remains may represent as many as thirty dead. Skalk orders Vol not to speak without permission because she is a thrall. Skalk yields to Glornir's demand and promises a chest of Helka's silver for the hunt."}]},{"refs":["f-b01-c036-002","f-b01-c036-007"],"from":36,"heading":"Story and connections","kind":"story","tokens":[{"text":"Skalk offers to perform Varg?s ak?ll in return for a future debt secured by Varg?s blood oath, warning that Varg may lose his place among the Bloodsworn. During the northern expedition, Skalk acknowledges that Helka sent the drengrs found dead in the forest, after Glornir confronts him over the incomplete account."}]},{"refs":["f-b01-c039-008","f-b01-c039-011","f-b01-c039-012"],"from":39,"heading":"Story and connections","kind":"story","tokens":[{"text":"Skalk demonstrates a flame in his palm with the word Eldur, extinguishing it when Glornir orders him to. He describes Galdur-magic as learned and Seiðr-magic as inherited, condemning the latter in explicitly hostile terms."}]},{"refs":["f-b01-c045-026","f-b01-c045-027","f-b01-c045-029","f-b01-c045-033","f-b01-c045-034","f-b01-c045-035"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"He betrays the Bloodsworn, knocking Vol unconscious while Yrsa and Olvir control the sickroom. He offers Varg an akáll in exchange for an oath, plans to enslave Vol, and kicks Varg unconscious after Varg attacks Olvir."}]},{"refs":["f-b01-c051-008","f-b01-c051-010","f-b01-c051-015","f-b01-c051-024"],"from":51,"heading":"Story and connections","kind":"story","tokens":[{"text":"Chapter 51 names him as the blond Galdurman from the frost-spider encounter. He compels Skapti to disclose Hakon’s orders regarding Drekr. During Orka’s escape she throws an axe into his shoulder; he later appears among those retreating to the boats."}]}],"images":[{"file":"assets/a15e5d86e3c013.jpg","from":43,"role":"primary","spoiler":false}],"curated":false},{"id":"e-199","file":"e-199.html","source":"characters/Skapti","category":"characters","from":51,"names":[{"from":51,"text":"Skapti"}],"featured":false,"blocks":[{"refs":["f-b01-c051-006","f-b01-c051-008","f-b01-c051-009","f-b01-c051-010"],"from":51,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"He is the white-haired chief at Grimholt, who threatens Lif with heated tongs during interrogation. Under Skalk’s questioning he admits that Hakon ordered Drekr’s access and storage of goods at the fortress."}]}],"images":[],"curated":false},{"id":"e-197","file":"e-197.html","source":"characters/Skrið","category":"characters","from":50,"names":[{"from":50,"text":"Skrið"}],"featured":false,"blocks":[{"refs":["f-b01-c050-028","f-b01-c050-029"],"from":50,"heading":"Appearance","kind":"introduction","tokens":[{"text":"His hair is dark with shaved sides, and he wears a dark coat of mail before the duel."}]},{"refs":["f-b01-c050-009","f-b01-c050-012","f-b01-c050-014","f-b01-c050-015","f-b01-c050-016","f-b01-c050-017","f-b01-c050-018"],"from":50,"heading":"Story and connections","kind":"story","tokens":[{"text":"Ilska names him as her brother and champion against Agnar. A huge, long-axe-bearing warrior, he manifests red eyes and sudden speed during the duel. Vörn identifies him as dragon-born. He mortally threatens Agnar but dies when Agnar drives shattered shield splinters through his throat."}]}],"images":[{"file":"assets/7861233d5d67d7.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-140","file":"e-140.html","source":"characters/Skullsplitter","category":"characters","from":18,"names":[{"from":18,"text":"Skullsplitter"}],"featured":false,"blocks":[{"refs":["f-b01-c018-043","f-b01-c018-045","f-b01-c018-044"],"from":18,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Torvik calls Skullsplitter the Bloodsworn’s old chief and says Skullsplitter gave Logur his rafter relic. Svik says Skullsplitter is dead. Varg remembers campfire tales among the farm thralls of a terrible, merciless warrior; that description remains an attributed account."}]},{"refs":["f-b01-c026-015"],"from":26,"heading":"Story and connections","kind":"story","tokens":[{"text":"Svik confirms Torvik's account of Skullsplitter drowning after falling from the Sea-Wolf during battle."}]},{"refs":["f-b01-c053-012","f-b01-c053-013","f-b01-c053-016"],"from":53,"heading":"Story and connections","kind":"story","tokens":[{"text":"Chapter 53 reveals the name at Glornir’s recognition of Orka: he calls her Orka Skullsplitter. Identity reconciliation on 2026-10-18: former E-140 is resolved to E-001 ("},{"page":"e-001"},{"text":"), effective B01-C053. This page preserves the earlier attributed accounts. Those reports of death and drowning are not rewritten as confirmed events, and the final chapter does not explain how the accounts arose."}]}],"images":[],"curated":false},{"id":"e-035","file":"e-035.html","source":"characters/Störr","category":"characters","from":9,"names":[{"from":3,"text":"Störr"}],"featured":false,"blocks":[{"refs":["f-b01-c009-043","f-b01-c009-042"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Agnar says Störr is famed for his Berserkir thrall-guard. He plans to take the captives to Snakavik for sale."}]},{"refs":["f-b01-c021-042","f-b01-c021-043","f-b01-c021-040","f-b01-c021-044","f-b01-c021-045","f-b01-c021-050"],"from":21,"heading":"Snakavik and Berak’s purchase","kind":"story","tokens":[{"text":"Störr is tall and slim, with dark greying hair, a neat braided beard, a sharp nose and dark-blue wool clothing. He wears silver and a serpent-fang pendant. His oathsworn hird is housed in garrison longhouses, and collared Berserkirs with axes and iron bear-claw pendants surround him."}]},{"refs":["f-b01-c021-051","f-b01-c021-052","f-b01-c021-053","f-b01-c021-059","f-b01-c021-060","f-b01-c021-062","f-b01-c021-061","f-b01-c021-064","f-b01-c021-065"],"from":21,"heading":"Snakavik and Berak’s purchase","kind":"story","tokens":[{"text":"He says he values Berserkirs and has Silrið obtain Berak’s blood for Hrung to taste. After Hrung identifies Berser’s blood, he offers twice what Agnar would receive elsewhere and orders Berak taken; the handover follows. He promises payment through Silrið."}]},{"refs":["f-b01-c021-066","f-b01-c021-069"],"from":21,"heading":"Snakavik and Berak’s purchase","kind":"story","tokens":[{"text":"At the end of B01-C021, Hrung identifies Elvar, and she addresses Störr as her father. The relationship becomes explicit at this reading point."}]},{"refs":["f-b01-c023-017","f-b01-c023-023"],"from":23,"heading":"Snakavik and Berak’s purchase","kind":"story","tokens":[{"text":"Störr claims he spilled much blood to restore control after Elvar's departure undermined his authority. Störr offers reconciliation and suggests giving Elvar her own drengrs and warband."}]}],"images":[{"file":"assets/2de8661fb6ad4f.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-102","file":"e-102.html","source":"characters/Sulich","category":"characters","from":11,"names":[{"from":11,"text":"The tattooed warrior"},{"from":13,"text":"Sulich"}],"featured":false,"blocks":[{"refs":["f-b01-c013-037"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Glornir names the shaven-haired Bloodsworn warrior Sulich in B01-C013."}]},{"refs":["f-b01-c011-019","f-b01-c011-020"],"from":11,"heading":"Appearance","kind":"introduction","tokens":[{"text":"In his chapter 11 appearance he is slim, of average height and dark-skinned, his head shaved except for a long, thick black braid. He wears a grey wool kaftan buckled down the centre, baggy breeches and tight ankle-to-knee leg wraps, and carries a black, red-spattered shield and curved single-edged sword."}]},{"refs":["f-b01-c013-041","f-b01-c013-042","f-b01-c013-038"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Glornir says Sulich has sworn the blood-sealed oath. Jaromir accuses Sulich of great crimes. Glornir refuses to surrender him."}]},{"refs":["f-b01-c018-053","f-b01-c018-055","f-b01-c018-057","f-b01-c018-060"],"from":18,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C018, Jaromir again demands Sulich at the docks, threatens the crew and ship, and attacks after Glornir refuses. His accusations remain unsubstantiated in this chapter."}]},{"refs":["f-b01-c020-035","f-b01-c020-036","f-b01-c020-038","f-b01-c020-039","f-b01-c020-041","f-b01-c020-042"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sulich calls the dead rider “my brother” and bids him travel well; this address does not establish a biological relationship. He offers Varg the rider’s helmet and describes it as battle spoils that tell the story of his victory. He says battle-fame is what lives on after death. Svik says Varg insults Sulich by suggesting he take another warrior’s spoils."}]},{"refs":["f-b01-c039-020","f-b01-c039-021","f-b01-c039-022"],"from":39,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sulich argues for judging people by deeds rather than ancestry. Skalk responds by calling him an escaped murderer and invoking Jaromir's accusation; Sulich denies it. Glornir ends the confrontation, while Skalk postpones the matter until Darl."}]}],"images":[{"file":"assets/18f38cd8d063f7.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-021","file":"e-021.html","source":"characters/Svik Hrulfsson","category":"characters","from":2,"names":[{"from":2,"text":"Svik Hrulfsson"}],"featured":false,"blocks":[{"refs":["f-b01-c002-074","f-b01-c002-075"],"from":2,"heading":"At the trial gate","kind":"introduction","tokens":[{"text":"Svik Hrulfsson is the attendant at the trial gate, where he also introduces himself as Tangle-Hair."}]},{"refs":["f-b01-c002-097","f-b01-c002-072","f-b01-c002-073","f-b01-c002-099","f-b01-c002-100","f-b01-c002-101"],"from":2,"heading":"Appearance","kind":"appearance","tokens":[{"text":"Svik is slim, with red hair neatly braided at the gate. His beard is trimmed and oiled, his riveted mail well kept; fine knotted scrollwork decorates his seax scabbard."}]},{"refs":["f-b01-c002-078","f-b01-c002-081","f-b01-c002-083","f-b01-c002-084","f-b01-c002-095"],"from":2,"heading":"A place among the Bloodsworn","kind":"story","tokens":[{"text":"When Varg asks for an invocation, Svik explains the word akáll but refuses him Vol's services: she works for the Bloodsworn and is not for hire. He points out the tattooed woman as Vol and names the trial fighter Einar Half-Troll."}]},{"refs":["f-b01-c004-090","f-b01-c004-091","f-b01-c004-092"],"from":4,"heading":"A place among the Bloodsworn","kind":"story","tokens":[{"text":"His intervention at Varg's camp is more direct. He cuts fingers from a spear-bearing attacker's hand, headbutts the man and growls at Orl's hound."}]},{"refs":["f-b01-c016-008","f-b01-c016-009","f-b01-c016-043","f-b01-c016-046"],"from":16,"heading":"A place among the Bloodsworn","kind":"story","tokens":[{"text":"During Varg's training, Svik helps him stand and tells him that accepting help is not weakness. When Glornir gives the apprentice money for equipment, Svik offers to help him spend it."}]},{"refs":["f-b01-c018-001","f-b01-c018-015","f-b01-c018-020","f-b01-c018-046","f-b01-c018-045","f-b01-c018-062","f-b01-c018-063"],"from":18,"heading":"A place among the Bloodsworn","kind":"story","tokens":[{"text":"Shopping becomes a lesson in practical priorities: spear, seax and axe are starting weapons, and a helmet matters more than mail. At the docks, the danger is immediate; Svik's warning about cavalry approaching from behind gives the rear row time to reform."}]},{"refs":["f-b01-c020-042","f-b01-c020-043","f-b01-c020-047","f-b01-c020-052","f-b01-c020-061","f-b01-c020-059"],"from":20,"heading":"Life aboard the Sea-Wolf","kind":"story","tokens":[{"text":"Svik explains why a warrior must not take the spoils of another person's kill, then helps Varg strip his own opponent's equipment. A sea-chest becomes both storage and rowing seat, and Varg follows Svik's rhythm as the ship leaves Liga."}]},{"refs":["f-b01-c026-013","f-b01-c026-015","f-b01-c026-016"],"from":26,"heading":"Life aboard the Sea-Wolf","kind":"story","tokens":[{"text":"He wins the oar-dance, but the company also carries stories of loss. Svik confirms Torvik's account of Skullsplitter drowning after a fall from the Sea-Wolf. He calls the old chief Glornir's brother and says Glornir still mourns him; these remain reports of the earlier fate."}]},{"refs":["f-b01-c030-005","f-b01-c030-008","f-b01-c030-012"],"from":30,"heading":"Life aboard the Sea-Wolf","kind":"story","tokens":[{"text":"On land, his advice returns to survival: Varg should wear his war gear rather than carry it in a sack, and may regret leaving armour behind if they meet a troll. At the farm he sets an outward-facing shield line while Glornir and the others search."}]},{"refs":["f-b01-c034-002","f-b01-c034-005","f-b01-c034-006","f-b01-c034-007","f-b01-c034-008","f-b01-c034-009"],"from":34,"heading":"The story behind the cheese","kind":"story","tokens":[{"text":"Sharing cheese with Varg, Svik claims it once saved his life. His tale places him at fourteen or fifteen, facing a troll that threatens his older brothers. Squeezing cheese convinces the creature he can crush stone; a later eating contest is another trick, with porridge hidden in a sack beneath his tunic. When he cuts the sack as if opening his own belly, the troll imitates him fatally. The adventure is Svik's narrated account, not independently established history."}]},{"refs":["f-b01-c043-011","f-b01-c043-020","f-b01-c043-023"],"from":43,"heading":"At the excavation","kind":"story","tokens":[{"text":"Svik leads his group through the enemy shield wall and attacks the troll blocking their way to Glornir. While Einar and Jökul fight below, he climbs onto its back and drives his blade between neck and shoulder."}]},{"refs":["f-b01-c047-005","f-b01-c047-006","f-b01-c047-007","f-b01-c047-008","f-b01-c047-009","f-b01-c047-019","f-b01-c047-020"],"from":47,"heading":"Blood and the oath","kind":"story","tokens":[{"text":"Svik reveals his descent from Refur the fox by briefly changing his face, eyes and teeth before restoring them. He tells Varg that control of the beast in his blood can be learned. The wider disclosure is that all the Bloodsworn are god-touched, but Svik insists that ancestry alone does not make a person one of them: trust and a kept oath matter."}]}],"images":[{"file":"assets/c9a6ca677ffb24.jpg","from":35,"role":"scene","spoiler":true},{"file":"assets/dbbf116b5d66f3.jpg","from":43,"role":"primary","spoiler":false},{"file":"assets/61b10687138050.jpg","from":47,"role":"scene","spoiler":true}],"curated":true},{"id":"e-131","file":"e-131.html","source":"characters/Sälla","category":"characters","from":16,"names":[{"from":16,"text":"Sälla"}],"featured":false,"blocks":[{"refs":["f-b01-c016-022","f-b01-c016-024","f-b01-c016-021","f-b01-c016-023"],"from":16,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sälla is "},{"page":"e-023"},{"text":"’s wife; Glornir addresses her by name in B01-C016. After Logur promises to arrange provisions for the departing Bloodsworn, she says he means he will ask her to make the arrangements."}]}],"images":[],"curated":false},{"id":"e-155","file":"e-155.html","source":"characters/Sólín","category":"characters","from":21,"names":[{"from":21,"text":"Sólín"}],"featured":false,"blocks":[{"refs":["f-b01-c032-012"],"from":32,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sólín is a lean, grey-haired Battle-Grim warrior."}]},{"refs":["f-b01-c021-027","f-b01-c021-033"],"from":21,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sólín is named among Agnar’s companions at Snakavik. Their red shields bear the Battle-Grim’s spear-and-axe sigil."}]},{"refs":["f-b01-c042-017","f-b01-c042-018","f-b01-c042-019"],"from":42,"heading":"Story and connections","kind":"story","tokens":[{"text":"The tennúr tear out three of Sólín's front teeth, leaving her with a lisp. She says she owes Elvar a blood-debt for saving her, and Elvar calls them shield-sisters. Sólín has swirling tattoos across one cheek and brow."}]}],"images":[],"curated":false},{"id":"e-002","file":"e-002.html","source":"characters/Thorkel","category":"characters","from":1,"names":[{"from":1,"text":"Thorkel"}],"featured":false,"blocks":[{"refs":["f-b01-c001-002","f-b01-c001-003","f-b01-c001-009","f-b01-c001-005","f-b01-c001-006"],"from":1,"heading":"A father on the hunt","kind":"introduction","tokens":[{"text":"Thorkel is Orka's husband and Breca's father. On the hunt he reassures their son about his missed throw by admitting that he missed his own first attempt, when he was eleven summers old."}]},{"refs":["f-b01-c001-020","f-b01-c001-023","f-b01-c001-021","f-b01-c001-022"],"from":1,"heading":"Appearance","kind":"appearance","tokens":[{"text":"Black hair streaked with grey and a scar from cheek to jaw mark his appearance. On the hunt his beard is braided, and he wears a woollen nålbinding cap."}]},{"refs":["f-b01-c008-005","f-b01-c008-036","f-b01-c008-009"],"from":8,"heading":"Appearance","kind":"appearance","tokens":[{"text":"He has dark eyes and a nose that has been broken repeatedly."}]},{"refs":["f-b01-c001-014","f-b01-c001-010","f-b01-c001-034"],"from":1,"heading":"What he teaches Breca","kind":"story","tokens":[{"text":"Thorkel identifies the wounded beast as a fell-wolf and tastes its blood. His stories also give Breca a way of understanding the land: he presents Snaka as the father of the gods."}]},{"refs":["f-b01-c003-009","f-b01-c003-008","f-b01-c003-067","f-b01-c003-068","f-b01-c003-069","f-b01-c003-070"],"from":3,"heading":"What he teaches Breca","kind":"story","tokens":[{"text":"He is the better tracker of the spouses, so he follows the trail while Orka and Breca take the bodies to Fellur. He returns without finding the killers, reporting that the tracks reached a river feeding the Skarpain and that three boats had left signs on its bank."}]},{"refs":["f-b01-c006-018","f-b01-c006-020","f-b01-c006-030"],"from":6,"heading":"What he teaches Breca","kind":"story","tokens":[{"text":"At the pool he finds Breca and thinks he smells Näcken. When Orka raises her hand again, he catches her wrist."}]},{"refs":["f-b01-c008-005","f-b01-c008-036","f-b01-c008-009","f-b01-c008-002","f-b01-c008-003","f-b01-c008-008","f-b01-c008-032","f-b01-c008-033"],"from":8,"heading":"What he teaches Breca","kind":"story","tokens":[{"text":"Orka calls him Thorkel Ulfsson. He speaks of having worn a thrall's collar and suffered lashings at Breca's age, but says he chooses each day to concentrate on Orka and their son rather than the past. His plan for the Althing is to attend quietly and avoid attention."}]},{"refs":["f-b01-c012-017","f-b01-c012-020","f-b01-c012-022","f-b01-c012-031"],"from":12,"heading":"What he teaches Breca","kind":"story","tokens":[{"text":"The Althing draws him into violence despite that intention. He kicks the warrior-thrall off Virk, takes a seax cut and restrains Orka, then lays his cloak over Virk's body."}]},{"refs":["f-b01-c015-008","f-b01-c015-010","f-b01-c015-016","f-b01-c015-017","f-b01-c015-015","f-b01-c015-020","f-b01-c015-021","f-b01-c015-037","f-b01-c015-035","f-b01-c015-038","f-b01-c015-039","f-b01-c015-044"],"from":15,"heading":"What he teaches Breca","kind":"story","tokens":[{"text":"Thorkel urges Breca to act fairly and avoid unnecessary fights; even necessary killing should be kept free of hatred. To him a weapon is a tool whose worth depends on its wielder. He offers Mord and Lif hospitality and advises them against returning to the Althing. With his own wound shallow and scabbed, he agrees to leave the area with Orka, while disputing her interpretation of the warrior-thrall's blood tasting."}]},{"refs":["f-b01-c017-017","f-b01-c017-016","f-b01-c017-019","f-b01-c017-021","f-b01-c017-020","f-b01-c017-023","f-b01-c017-024","f-b01-c017-031"],"from":17,"heading":"The last defence of the hall","kind":"story","tokens":[{"text":"Orka finds him still breathing among the bodies, with blades in his chest and belly. He tells her Breca has been taken and that he failed to stop the attackers. Outside the hall he says 'Dragon-born', without identifying whom he means, apologises and dies. Orka places his long-axe in his hand."}]},{"refs":["f-b01-c019-017","f-b01-c019-018","f-b01-c019-019","f-b01-c019-024","f-b01-c019-026","f-b01-c019-041","f-b01-c019-038","f-b01-c019-043","f-b01-c019-044","f-b01-c019-056","f-b01-c019-042"],"from":19,"heading":"The last defence of the hall","kind":"story","tokens":[{"text":"Vesli later describes how he barred the gates, then opened them to fight as smoke and fire choked those inside. She says he changed, but does not finish the description; the red-eyed man with two long claws belongs to her account of the fighting. With Vesli's help, Orka buries Thorkel with his axe, an ivory-hilted seax and gold rings, then builds and seals a barrow."}]}],"images":[{"file":"assets/3a08fab11d7e78.jpg","from":21,"role":"primary","spoiler":false}],"curated":true},{"id":"e-161","file":"e-161.html","source":"characters/Thorun","category":"characters","from":23,"names":[{"from":23,"text":"Thorun"}],"featured":false,"blocks":[{"refs":["f-b01-c023-004","f-b01-c023-019","f-b01-c023-021"],"from":23,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Thorun is Elvar's elder brother. Thorun claims that combining Störr's and Helka's realms would cover over half of Vigrið. Thorun alleges that Grend's protection is responsible for Elvar's reputation."}]}],"images":[],"curated":false},{"id":"e-076","file":"e-076.html","source":"characters/Thrud","category":"characters","from":21,"names":[{"from":7,"text":"Thrud"}],"featured":false,"blocks":[{"refs":["f-b01-c007-003","f-b01-c021-020","f-b01-c021-021","f-b01-c021-026"],"from":21,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Thrud suffered an arrow wound to the calf on Iskalt. In B01-C021 he still limps and guards the prisoners with Biórr. He is lean, with a scarred, pitted angular face. Agnar gives him coin and orders him to find a tavern large enough for the Battle-Grim."}]},{"refs":["f-b01-c025-008"],"from":25,"heading":"Story and connections","kind":"story","tokens":[{"text":"Thrud wears a wrist cord with a fragment from a wight skull he took when first joining the Battle-Grim."}]},{"refs":["f-b01-c027-007"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Thrud is dead with wounds in his throat and back."}]},{"refs":["f-b01-c052-006"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr acknowledges killing her when Elvar accuses him in chapter 52. This reveals responsibility after his earlier expression of guilt, which alone had not established it."}]}],"images":[],"curated":false},{"id":"e-106","file":"e-106.html","source":"characters/Torvik","category":"characters","from":13,"names":[{"from":13,"text":"Torvik"}],"featured":false,"blocks":[{"refs":["f-b01-c013-005","f-b01-c013-006","f-b01-c013-008"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Torvik introduces himself to Varg. He says he scouts under Edel and is apprenticed to Jökul Hammer-Hand."}]},{"refs":["f-b01-c013-010","f-b01-c013-011"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"He says he has not yet taken the oath and must first prove courage or loyalty."}]},{"refs":["f-b01-c018-036","f-b01-c018-038","f-b01-c018-043"],"from":18,"heading":"Story and connections","kind":"story","tokens":[{"text":"Torvik identifies Logur’s rafter relic as a "},{"page":"e-108"},{"text":" fragment and says it helped make Logur rich. He says the gift was made by Skullsplitter, their old chief, rather than Glornir."}]},{"refs":["f-b01-c034-004","f-b01-c034-012"],"from":34,"heading":"Story and connections","kind":"story","tokens":[{"text":"Torvik praises Svik as a tale-teller. Torvik calls Varg brother, giving Varg both guilt about Frøya and a sense of companionship; biological kinship is not established."}]},{"refs":["f-b01-c039-002","f-b01-c039-004","f-b01-c039-005"],"from":39,"heading":"Story and connections","kind":"story","tokens":[{"text":"After Varg shows him his sister's hair, Torvik offers to help hunt and kill her murderers once Glornir grants the akáll. He also reports Edel's encouragement of his tracking ability."}]},{"refs":["f-b01-c041-011","f-b01-c041-019","f-b01-c041-020"],"from":41,"heading":"Story and connections","kind":"story","tokens":[{"text":"Torvik guides Svik's group to the guarded tunnel glade. Like Varg, he has no mail and is still outside the sworn oath."}]},{"refs":["f-b01-c043-006","f-b01-c043-008","f-b01-c043-009","f-b01-c043-010","f-b01-c043-020"],"from":43,"heading":"Story and connections","kind":"story","tokens":[{"text":"After a skraeling scatters him and Varg, Torvik fights it and spears it through the body; Einar finishes it. Torvik then pulls Varg up before they rejoin the battle. He also throws his spear into the troll's shoulder."}]},{"refs":["f-b01-c045-014","f-b01-c045-027","f-b01-c045-028"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"He tends the wounded Varg and promises to save his life again. Yrsa then spears him in the throat during Skalk’s betrayal. He dies holding Varg’s hand, after Skalk refuses to let Varg give him a weapon."}]}],"images":[],"curated":false},{"id":"e-188","file":"e-188.html","source":"characters/Unnamed bone-sword wielder","category":"characters","from":43,"names":[{"from":43,"text":"Unnamed bone-sword wielder"}],"featured":false,"blocks":[{"refs":["f-b01-c043-013","f-b01-c043-014","f-b01-c043-031"],"from":43,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"An unnamed old, grey-bearded, red-eyed man emerges from the guarded tunnel with a dozen mailed warriors. He wears dark mail, a helmet with mail neck-guard, a cloak and many silver and gold arm rings, and carries a long curved bone sword. His helmet later exposes a shaved head. His identity is unestablished."}]},{"refs":["f-b01-c043-017","f-b01-c043-018","f-b01-c043-028","f-b01-c043-032","f-b01-c043-033"],"from":43,"heading":"Story and connections","kind":"story","tokens":[{"text":"He hurls Glornir back, cuts Røkia's spear from the air and defeats Vol's protective rune. Varg drives a cleaver into his head as the man's sword strikes Varg at the waist; the chapter does not provide a later confirmation of either man's condition."}]},{"refs":["f-b01-c045-004"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"In chapter 45 Torvik identifies the slain swordsman as dragon-born. His personal name and any connection to earlier attackers remain unknown."}]}],"images":[],"curated":false},{"id":"e-062","file":"e-062.html","source":"characters/Unnamed Hundur-thrall","category":"characters","from":5,"names":[{"from":5,"text":"Agnar’s Hundur-thrall"},{"from":44,"text":"Ilmur"}],"featured":false,"blocks":[{"refs":["f-b01-c005-020","f-b01-c005-021"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Agnar calls the chained man his Hundur-thrall. He says the man has Berak’s scent."}]},{"refs":["f-b01-c005-022","f-b01-c005-023","f-b01-c005-024"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"Red veins ripple through the collar after Agnar says Hlýða. The thrall sniffs a blood-crusted rag."}]},{"refs":["f-b01-c005-040"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"He sniffs a cot and nods when Sighvat asks if it is him."}]},{"refs":["f-b01-c044-012"],"from":44,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr identifies him as Ilmur in chapter 44. The previously unnamed Hundur-thrall retains entity ID E-062; this is a name revelation, not a separate person."}]},{"refs":["f-b01-c052-002"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr removes his collar after killing Agnar. Ilmur throws it away."}]}],"images":[],"curated":false},{"id":"e-143","file":"e-143.html","source":"characters/Unnamed red-eyed attacker","category":"characters","from":19,"names":[{"from":19,"text":"Unnamed red-eyed attacker"}],"featured":false,"blocks":[{"refs":["f-b01-c019-022","f-b01-c019-024","f-b01-c019-026","f-b01-c019-023"],"from":19,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Vesli reports a man, human-like but different, who fought Thorkel with two long sharp claws and eyes glowing red like embers. Prompted by Orka, she agrees he was one of the Tainted."}]},{"refs":["f-b01-c019-025"],"from":19,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka wonders whether the claws were the two seaxes embedded in Thorkel’s body. The account does not establish this man’s personal identity or ownership of the blades; see "},{"text":"the unresolved identity"},{"text":"."}]}],"images":[],"curated":false},{"id":"e-134","file":"e-134.html","source":"characters/Unnamed young riverbank captive","category":"characters","from":17,"names":[{"from":17,"text":"Unnamed young riverbank captive"}],"featured":false,"blocks":[{"refs":["f-b01-c017-039","f-b01-c017-047","f-b01-c017-053","f-b01-c017-059"],"from":17,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"This young man is among the group butchering Snort when Orka attacks. She wounds his thigh, disarms him and pins his shoulder with her spear."}]},{"refs":["f-b01-c017-063","f-b01-c017-064","f-b01-c017-061","f-b01-c017-062","f-b01-c017-067"],"from":17,"heading":"Story and connections","kind":"story","tokens":[{"text":"Under violent questioning, he says he came with his uncle, indicating the dead man over the pony, and was offered gold for climbing a wall and opening a gate. He says Breca was taken onto the river but that he does not know the destination or river fork. He names Drekr in response to Orka’s demand for the chief’s name. These claims retain their coercive circumstances and are not independently verified."}]},{"refs":["f-b01-c017-068","f-b01-c017-069"],"from":17,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka kills him with a spear thrust through his chest after he gives the name."}]}],"images":[],"curated":false},{"id":"e-072","file":"e-072.html","source":"characters/Uspa","category":"characters","from":9,"names":[{"from":7,"text":"Berak’s wife"},{"from":14,"text":"Uspa"}],"featured":false,"blocks":[{"refs":["f-b01-c009-002","f-b01-c009-028"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The captured woman is Berak’s wife and the boy’s mother."}]},{"refs":["f-b01-c009-030","f-b01-c009-045","f-b01-c009-046"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Her eyes are grey-blue, her hair fair, and blue tattoos show below her neck."}]},{"refs":["f-b01-c009-051","f-b01-c009-052"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"The chapter 9 description also notes her pale face and a tunic and cloak drawn close around her neck. A documented "},{"text":" separates those observations from artistic choices."}]},{"refs":["f-b01-c009-026","f-b01-c009-027","f-b01-c009-028"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"She sings and the attacking serpent slows and dives away."}]},{"refs":["f-b01-c009-031","f-b01-c009-032"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar calls her a Seiðr-witch with Snaka’s blood. He threatens her son if she uses powers against his crew."}]},{"refs":["f-b01-c014-007","f-b01-c014-008"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Berak names his wife Uspa in B01-C014. She calls their boy Bjarn."}]},{"refs":["f-b01-c014-009","f-b01-c014-010"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"She presses her bloodied palm to the granite slab, and glowing lines burn away the moss."}]},{"refs":["f-b01-c014-020","f-b01-c014-022"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"She tells a story of jealousy, murder and blood feud causing the gods’ war. She says Lik-Rifa created the vaesen in secret."}]},{"refs":["f-b01-c023-010"],"from":23,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa insists that she and Bjarn need to leave Snakavik."}]},{"refs":["f-b01-c025-013"],"from":25,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa refuses to explain her need to leave Snakavik until Elvar is sober."}]},{"refs":["f-b01-c027-009","f-b01-c027-023","f-b01-c027-025","f-b01-c027-027"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Burned bodies lie around Uspa, who is unconscious but breathing. Uspa blames the disaster on their failure to leave when she warned Elvar. Uspa says the attackers wanted her rather than Bjarn. Uspa claims to know the way to Oskutreð; Elvar overhears the whispered disclosure."}]},{"refs":["f-b01-c029-003","f-b01-c029-008","f-b01-c029-010","f-b01-c029-012","f-b01-c029-013","f-b01-c029-014","f-b01-c029-015","f-b01-c029-016"],"from":29,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa insists that Oskutreð is real. Uspa says she destroyed the Graskinna in the fire pool on Iskalt while Berak fought the troll. Uspa says she and Berak stole the Graskinna from the Raven-Feeders, who have hunted them for a long time. Uspa says she burned the book to prevent treasure-seekers finding god-remains and provoking new powers and war. Uspa offers the route for love of her son. Uspa threatens to kill herself rather than submit to Agnar's proposed coercion by a thrall-collar. Uspa attributes the attack on Ilska's warriors to herself. Uspa agrees to guide the group to Oskutreð first if all present swear the blóð svarið."}]},{"refs":["f-b01-c038-011","f-b01-c038-013"],"from":38,"heading":"Chapter 38 — Isbrún Bridge","kind":"story","tokens":[{"text":"At the vaesen pit, Uspa applies blood to a black boulder and chants. A huge pawprint appears, and the Isbrún Bridge becomes visible beneath her feet as she steps over the edge."}]},{"refs":["f-b01-c044-013","f-b01-c044-014","f-b01-c044-015","f-b01-c044-017","f-b01-c044-018"],"from":44,"heading":"Later journey","kind":"story","tokens":[{"text":"In the Dark-of-Moon Hills she predicts they may see Oskutreð the next day, explicitly admitting that the feeling may be wrong. She fears that bringing the gods’ treasures south will cause violence. She says recovering Bjarn matters more to her than her principles, while arguing for love and friendship over battle-fame."}]},{"refs":["f-b01-c045-018"],"from":45,"heading":"Later journey","kind":"story","tokens":[{"text":"In chapter 45 Vol names her missing sister as Uspa, revealing the reported family connection at this point in reading chronology."}]},{"refs":["f-b01-c048-006"],"from":48,"heading":"Later journey","kind":"story","tokens":[{"text":"She brings the Battle-Grim to Oskutreð’s ruined stump, fulfilling the destination part of her bargain; Bjarn has not yet been recovered."}]},{"refs":["f-b01-c052-015","f-b01-c052-018"],"from":52,"heading":"Later journey","kind":"story","tokens":[{"text":"She joins Vörn in barring the tree with magic. Ilska’s earth-strike hurls her away and leaves her unmoving; her subsequent condition is not established in this chapter."}]}],"images":[{"file":"assets/66374bb136ce78.jpg","from":43,"role":"primary","spoiler":false},{"file":"assets/339c3a71267c75.jpg","from":43,"role":"scene","spoiler":true}],"curated":false},{"id":"e-187","file":"e-187.html","source":"characters/Vali","category":"characters","from":45,"names":[{"from":43,"text":"Vali"}],"featured":false,"blocks":[{"refs":["f-b01-c045-013"],"from":45,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Vali is one of the two shrouded dead Bloodsworn in the catacomb after the troll battle."}]}],"images":[],"curated":false},{"id":"e-014","file":"e-014.html","source":"characters/Varg","category":"characters","from":2,"names":[{"from":2,"text":"Varg"}],"featured":true,"blocks":[{"refs":["f-b01-c002-001","f-b01-c002-004","f-b01-c002-009","f-b01-c002-010","f-b01-c002-076"],"from":2,"heading":"A stranger in Liga","kind":"introduction","tokens":[{"text":"Varg reaches Liga believing he is being pursued. He does not know his age, but remembers thirty winters and summers shackled to Kolskegg's farm and says he never knew his parents."}]},{"refs":["f-b01-c002-009","f-b01-c002-016","f-b01-c002-017","f-b01-c002-018","f-b01-c002-091"],"from":2,"heading":"Appearance","kind":"appearance","tokens":[{"text":"At his arrival, his hair is short and stubbled and his beard newly grown. He wears a woollen cloak and carries a leather pouch at his belt; precise hair colour, eye colour and age are not established by these descriptions."}]},{"refs":["f-b01-c002-082","f-b01-c002-095","f-b01-c002-094","f-b01-c002-090","f-b01-c004-010","f-b01-c004-009","f-b01-c004-028","f-b01-c004-029","f-b01-c004-033","f-b01-c004-035","f-b01-c004-036"],"from":4,"heading":"A trial and a reason to keep going","kind":"story","tokens":[{"text":"Varg comes looking for a Seiðr-witch to perform an akáll. Although he initially says he does not want to fight, he agrees to face Einar Half-Troll. The trial is unfamiliar enough that he refuses a shield he has never learned to use, and his last memories of the fight give way to an injured awakening outside Liga."}]},{"refs":["f-b01-c004-017","f-b01-c004-018","f-b01-c004-046","f-b01-c004-052","f-b01-c004-053","f-b01-c004-054"],"from":4,"heading":"A trial and a reason to keep going","kind":"story","tokens":[{"text":"His earlier fighting on the farm began when he tried to get broth for his sister Frøya. Now he thinks of her as dead and wants vengeance, although he does not know how to pursue it. He resolves to find a Galdurman or Seiðr-witch who will help him for coin."}]},{"refs":["f-b01-c004-062","f-b01-c004-063","f-b01-c004-071","f-b01-c004-095","f-b01-c011-006","f-b01-c011-013","f-b01-c016-001","f-b01-c016-003","f-b01-c016-004","f-b01-c016-008","f-b01-c016-009","f-b01-c016-010","f-b01-c016-011"],"from":16,"heading":"Learning to accept help","kind":"story","tokens":[{"text":"When Leif's men corner him, a grey-bearded rescuer declares Varg one of the Bloodsworn. The days afterwards bring treatment for his wound and shield training under Røkia. Training is painful, but Svik helps him stand and tells him that accepting help is not weakness, a thought at odds with Varg's long isolation."}]},{"refs":["f-b01-c016-028","f-b01-c016-031","f-b01-c016-032","f-b01-c016-033","f-b01-c016-039","f-b01-c016-040","f-b01-c016-041","f-b01-c016-043","f-b01-c016-044","f-b01-c016-045","f-b01-c016-046"],"from":16,"heading":"Learning to accept help","kind":"story","tokens":[{"text":"Glornir refuses the akáll and makes Varg's position clear: he is an apprentice, not yet Bloodsworn. In return for learning, obedience and fighting, he will receive food, teaching and protection. Varg accepts coin for equipment, and Svik offers to help him spend it."}]},{"refs":["f-b01-c018-001","f-b01-c018-002","f-b01-c018-003","f-b01-c018-004","f-b01-c018-005","f-b01-c018-007","f-b01-c018-006","f-b01-c018-017","f-b01-c018-014","f-b01-c018-021","f-b01-c018-022","f-b01-c018-025","f-b01-c018-026","f-b01-c018-028","f-b01-c018-030","f-b01-c018-031","f-b01-c018-032","f-b01-c018-033","f-b01-c018-060","f-b01-c018-064","f-b01-c018-065","f-b01-c018-066"],"from":18,"heading":"Equipped for a different life","kind":"story","tokens":[{"text":"Buying clothes and weapons with Svik and Røkia gives Varg a new outward appearance. He burns his old clothing and washes, receives Glornir's shield and an ash-hafted spear, then finds himself in real fighting at the docks. Forgetting his helmet and leaving the spear's cover on show how much he still has to learn."}]},{"refs":["f-b01-c020-001","f-b01-c020-005","f-b01-c020-004","f-b01-c020-037","f-b01-c020-038","f-b01-c020-041","f-b01-c020-042","f-b01-c020-043","f-b01-c020-044","f-b01-c020-045","f-b01-c020-050","f-b01-c020-052","f-b01-c020-054","f-b01-c020-061","f-b01-c020-063","f-b01-c020-064"],"from":20,"heading":"Equipped for a different life","kind":"story","tokens":[{"text":"Seeing the dead rider he wounded makes Varg vomit. His companions explain the rules governing battle spoils, and he helps strip the body before taking his place aboard the Sea-Wolf. Rowing to Svik's rhythm, he joins the song and feels excitement alongside his guilt about Frøya."}]},{"refs":["f-b01-c030-017","f-b01-c034-012","f-b01-c039-002","f-b01-c039-003","f-b01-c039-004","f-b01-c039-006"],"from":39,"heading":"Vengeance and belonging","kind":"story","tokens":[{"text":"Survival matters to Varg more than battle-fame: it will let him discover how Frøya died and avenge her. Torvik calls him brother and later promises to help hunt her murderers. Varg reveals that his guarded pouch contains a lock of her black hair for the akáll, while recognising that his growing attachment to the Bloodsworn will make leaving difficult."}]},{"refs":["f-b01-c043-006","f-b01-c043-008","f-b01-c043-009","f-b01-c043-021","f-b01-c043-022","f-b01-c043-029","f-b01-c043-030","f-b01-c043-032","f-b01-c043-033","f-b01-c045-001","f-b01-c045-015","f-b01-c045-016","f-b01-c045-019","f-b01-c045-020","f-b01-c045-021","f-b01-c045-022","f-b01-c045-023"],"from":45,"heading":"Vengeance and belonging","kind":"story","tokens":[{"text":"At the excavation Varg fights beside Torvik and later attacks the bone-sword wielder to protect Glornir and Vol. A sword blow ends his awareness, but he survives with a bruised, blistered side. His account to Vol still leaves a gap between the denial of his promised freedom and the bloody aftermath on the farm."}]},{"refs":["f-b01-c045-028","f-b01-c045-029","f-b01-c045-034","f-b01-c045-035"],"from":45,"heading":"Vengeance and belonging","kind":"story","tokens":[{"text":"After Torvik is killed, Varg attacks Olvir rather than accepting Skalk's offered oath. Skalk kicks him unconscious."}]},{"refs":["f-b01-c047-010","f-b01-c047-011","f-b01-c047-012","f-b01-c047-014","f-b01-c047-025","f-b01-c047-026","f-b01-c047-027","f-b01-c047-028"],"from":47,"heading":"Blood, trust and a place among them","kind":"story","tokens":[{"text":"Edel says she smelled the wolf in Varg's blood after the Liga trial. Røkia identifies him as Úlfhéðnar like herself and connects his red mist to that ancestry. Distressed at first, he accepts the disclosure. He also accepts Glornir's invitation to join the Bloodsworn and wears the chief's silver arm ring, although the formal oath-words must wait until after the effort to recover Vol."}]},{"refs":["f-b01-c053-001","f-b01-c053-002","f-b01-c053-004","f-b01-c053-005","f-b01-c053-006","f-b01-c053-008","f-b01-c053-012","f-b01-c053-013","f-b01-c053-016"],"from":53,"heading":"Blood, trust and a place among them","kind":"story","tokens":[{"text":"Two days into the pursuit of Skalk, Varg runs with Edel's scouts in his newly won mail and helm. His pain is manageable, and he increasingly accepts kinship with the company. At the burning fortress he witnesses Glornir's recognition and embrace of Orka Skullsplitter."}]}],"images":[{"file":"assets/bdb984c3b9e127.jpg","from":53,"role":"secondary","spoiler":true},{"file":"assets/11a042a1bdf288.jpg","from":21,"role":"primary","spoiler":false}],"curated":true},{"id":"e-034","file":"e-034.html","source":"characters/Virk","category":"characters","from":3,"names":[{"from":3,"text":"Virk"}],"featured":false,"blocks":[{"refs":["f-b01-c003-024","f-b01-c003-076"],"from":3,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Virk is a fisherman. "},{"page":"e-001"},{"text":"and "},{"page":"e-002"},{"text":" have traded with him many times."}]},{"refs":["f-b01-c003-025","f-b01-c003-026"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"He injured his arm when his boat was caught in a storm. His two sons fish while he heals."}]},{"refs":["f-b01-c003-038","f-b01-c003-045","f-b01-c003-044"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"He says "},{"page":"e-032"},{"text":"went to "},{"page":"e-018"},{"text":"’s court in Darl. He objects that Helka’s care would be rule. He says Fellur’s people were all freedmen and women not long ago."}]},{"refs":["f-b01-c003-060"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"He says he has heard of children being taken before."}]},{"refs":["f-b01-c010-006","f-b01-c010-007","f-b01-c010-005"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Mord and Lif are Virk’s sons. He rows the family to the Althing."}]},{"refs":["f-b01-c010-011","f-b01-c010-012"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"He reports missing Haraldurson children and a murdered family with missing sons at Kergarth."}]},{"refs":["f-b01-c010-023","f-b01-c010-039","f-b01-c010-041"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"He objects to Helka’s rule and accepts Guðvarr’s duel challenge. He asks Orka to act as his second."}]},{"refs":["f-b01-c012-010","f-b01-c012-011","f-b01-c012-012","f-b01-c012-013"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"Virk wounds Guðvarr’s shoulder and declares him outside the duel boundary. After further insult, Virk swings at his head."}]},{"refs":["f-b01-c012-014","f-b01-c012-016","f-b01-c012-018","f-b01-c012-032"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sigrún’s thrall repeatedly stabs Virk and mauls his face. Thorkel declares him dead. His sons and the family carry his body away."}]},{"refs":["f-b01-c015-004","f-b01-c015-026"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"After his death, Orka’s family helps his sons raise a barrow over him. Orka says he taught his sons a trade and that they have a fishing boat."}]}],"images":[],"curated":false},{"id":"e-020","file":"e-020.html","source":"characters/Vol","category":"characters","from":2,"names":[{"from":2,"text":"Vol"}],"featured":false,"blocks":[{"refs":["f-b01-c002-081","f-b01-c002-093"],"from":2,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-021"},{"text":"identifies the tattooed woman at the trial as Vol in B01-C002. "},{"page":"e-014"},{"text":" identifies her as the Seiðr-witch."}]},{"refs":["f-b01-c002-067","f-b01-c002-068","f-b01-c002-069"],"from":2,"heading":"Appearance","kind":"appearance","tokens":[{"text":"She has raven-black hair. Blue tattoos run across her lower jaw and throat. When Varg sees her, she wears an iron collar."}]},{"refs":["f-b01-c002-041","f-b01-c002-084","f-b01-c002-095","f-b01-c002-085"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"The stew trader says the "},{"page":"e-019"},{"text":"have a Seiðr-witch thrall. Svik says Vol uses her talents only for the Bloodsworn. He refuses to hire her out. He says even a request from "},{"page":"e-018"},{"text":" would be refused."}]},{"refs":["f-b01-c004-102","f-b01-c004-103"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C004 the narrator refers to Vol as a Seiðr-witch. She has dark eyes."}]},{"refs":["f-b01-c013-003"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vol is present at the feast at the high table, wearing her thrall collar."}]},{"refs":["f-b01-c016-026","f-b01-c016-027","f-b01-c016-030","f-b01-c016-029","f-b01-c016-031"],"from":16,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vol speaks softly, and Varg sees confidence and dignity in her manner. She describes the akáll as reliving the last moments of a life and says it is no simple task. Glornir interrupts while she begins explaining what is needed; no invocation is performed in B01-C016."}]},{"refs":["f-b01-c020-058"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"On the Sea-Wolf’s departure in B01-C020, Vol takes position at the prow with a hand against it, while Glornir goes to the stern steering oar. No magical action is established by this placement."}]},{"refs":["f-b01-c026-025"],"from":26,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vol questions how vaesen could have crossed the Bonebacks past the Grimholt and its guard tower."}]},{"refs":["f-b01-c034-015","f-b01-c034-016"],"from":34,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vol worries that an unnamed woman should already have reached them. Vol wants to search for that woman rather than continue with Skalk."}]},{"refs":["f-b01-c043-026","f-b01-c043-027","f-b01-c043-028"],"from":43,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vol cuts her hand and traces a rune in blood and flame above the wounded Glornir, stopping the bone sword partway through it. She sustains it with a raised palm and continuing speech despite pain. The swordsman's answering words break the rune and throw her into Glornir."}]},{"refs":["f-b01-c045-017","f-b01-c045-018","f-b01-c045-024","f-b01-c045-025","f-b01-c045-026","f-b01-c045-032","f-b01-c045-033"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"She heals Varg’s pain and names her missing sister as Uspa. She tells Varg that an akáll needs a link to Frøya, but reserves the decision to Glornir. Skalk knocks her unconscious and has Yrsa carry her away, declaring that he intends to enslave her."}]},{"refs":["f-b01-c047-003","f-b01-c047-029"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"Chapter 47 corrects the earlier public account of her status: Svik says she is not a thrall, and Glornir explicitly names her as his wife. Her earlier collar and the trader’s statement remain historical observations and testimony, rather than proof of actual enslavement."}]}],"images":[{"file":"assets/5f5fdee52a4237.jpg","from":21,"role":"primary","spoiler":false}],"curated":false},{"id":"e-193","file":"e-193.html","source":"characters/Vörn Askasdottir","category":"characters","from":48,"names":[{"from":48,"text":"Vörn Askasdottir"}],"featured":false,"blocks":[{"refs":["f-b01-c048-014","f-b01-c048-017","f-b01-c048-018","f-b01-c048-019","f-b01-c048-020"],"from":48,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"She emerges from a living ash beside Oskutreð’s stump and names herself its newborn Froa guardian, daughter of Aska. Her body is tall, ash-grey and wood-grained, with bark and lichen."}]},{"refs":["f-b01-c048-022","f-b01-c048-023","f-b01-c048-024","f-b01-c048-025","f-b01-c048-027","f-b01-c048-028"],"from":48,"heading":"Chapter 48 — Binding Sighvat","kind":"story","tokens":[{"text":"She forbids contact with the dead tree, disarms Sighvat and binds him with growing vines. She confirms Lik-Rifa’s imprisonment and names the three sisters as gaolers."}]},{"refs":["f-b01-c048-034"],"from":48,"heading":"Appearance","kind":"appearance","tokens":[{"text":"Her hair swirls around her shoulders like roots."}]},{"refs":["f-b01-c052-015","f-b01-c052-016","f-b01-c052-017"],"from":52,"heading":"Chapter 52 — Defending the tree","kind":"story","tokens":[{"text":"She and Uspa resist Ilska’s approach, but the combined fire-runes overwhelm her vine defence. She burns and falls, her subsequent condition unshown here."}]}],"images":[{"file":"assets/eb790d69f84ecc.jpg","from":53,"role":"scene","spoiler":true},{"file":"assets/a9e1e84388e8dc.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-166","file":"e-166.html","source":"characters/Yrsa","category":"characters","from":26,"names":[{"from":26,"text":"Yrsa"}],"featured":false,"blocks":[{"refs":["f-b01-c026-018","f-b01-c026-020"],"from":26,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Yrsa is the female royal guard travelling with Skalk. Both royal guards wear dark cloaks pinned with silver eagle-wing brooches."}]},{"refs":["f-b01-c045-027","f-b01-c045-030","f-b01-c045-032"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"During Skalk’s betrayal she spears Torvik through the throat, retrieves a chest containing the bone sword and carries unconscious Vol away."}]}],"images":[],"curated":false},{"id":"e-013","file":"e-013.html","source":"places/Asgrim’s steading","category":"places","from":1,"names":[{"from":1,"text":"Asgrim’s steading"}],"featured":false,"blocks":[{"refs":["f-b01-c001-044","f-b01-c001-045","f-b01-c001-046"],"from":1,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The steading has a large grass-roofed cabin. A stockade surrounds the cabin and outbuildings. An eastern track leads towards "},{"page":"e-007"},{"text":"."}]},{"refs":["f-b01-c001-025","f-b01-c001-061"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"Asgrim is Harek’s father. Idrun is Asgrim’s wife."}]},{"refs":["f-b01-c001-047","f-b01-c001-074","f-b01-c001-075"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"Asgrim is dead when the family arrives. There is a hole in his chest. A bloodied hand-axe lies nearby."}]},{"refs":["f-b01-c001-062","f-b01-c001-073","f-b01-c001-064"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"Idrun’s body is nailed to the gate. Her abdomen has been opened. She was the person screaming."}]},{"refs":["f-b01-c001-065","f-b01-c001-069"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-002"},{"text":" identifies a warding rune on the gate. He raises the possibility that people committed the attack."}]},{"refs":["f-b01-c003-005","f-b01-c003-058"],"from":3,"heading":"Search and disputed accounts","kind":"story","tokens":[{"text":"The family searches the steading and finds no sign of "},{"page":"e-006"},{"text":". Breca says he has been taken."}]},{"refs":["f-b01-c003-053","f-b01-c003-054","f-b01-c003-056"],"from":3,"heading":"Search and disputed accounts","kind":"story","tokens":[{"text":"Guðvarr blames the killings on vaesen. Orka denies that accusation. She describes the wound as a sword wound to the heart."}]},{"refs":["f-b01-c003-069","f-b01-c003-070"],"from":3,"heading":"Search and disputed accounts","kind":"story","tokens":[{"text":"Thorkel says the tracks led to a river feeding into the River Skarpain. He reports signs of three boats on the bank."}]}],"images":[],"curated":false},{"id":"e-153","file":"e-153.html","source":"places/Boneback Mountains","category":"places","from":21,"names":[{"from":21,"text":"Boneback Mountains"}],"featured":false,"blocks":[{"refs":["f-b01-c021-003","f-b01-c021-006","f-b01-c021-007"],"from":21,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The Boneback Mountains begin at their western extremity at Snakavik. The narration describes earth settling around Snaka’s fallen body to form a range across Vigrið; his skull, spine and ribs remain beneath earth and rock."}]},{"refs":["f-b01-c034-024","f-b01-c034-025"],"from":34,"heading":"Story and connections","kind":"story","tokens":[{"text":"In the chapter 34 approach they fill Varg's horizon, with snow-capped peaks above dark-green slopes thickly forested with pine. The foothills contain wooded hills, shadowed valleys, sunlit meadows and winding rivers in newly risen sunlight."}]}],"images":[{"file":"assets/fe08d0e1f533e4.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-113","file":"e-113.html","source":"places/Dark-of-Moon Hills","category":"places","from":44,"names":[{"from":13,"text":"Dark-of-Moon Hills"}],"featured":false,"blocks":[{"refs":["f-b01-c044-001"],"from":44,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Elvar’s journey here passes through misty vales and wooded rolling hills."}]}],"images":[],"curated":false},{"id":"e-164","file":"e-164.html","source":"places/Darl","category":"places","from":24,"names":[{"from":24,"text":"Darl"}],"featured":false,"blocks":[{"refs":["f-b01-c024-018"],"from":24,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Darl is a fortress and town towards the Boneback Mountains."}]},{"refs":["f-b01-c031-006","f-b01-c031-007","f-b01-c031-010","f-b01-c031-012"],"from":31,"heading":"Story and connections","kind":"story","tokens":[{"text":"Darl is Queen Helka's fortress and seat of power. Darl's mead hall is surrounded by a giant eagle skeleton with wide wings and a skull above its roof. Darl has a Galdur tower where Galdurmen learn rune arts. Three large drakkars arrive at Darl as horns sound from the fortress."}]},{"refs":["f-b01-c033-006"],"from":33,"heading":"Story and connections","kind":"story","tokens":[{"text":"Darl has canals branching from the river among ships, boathouses and barns."}]},{"refs":["f-b01-c035-027"],"from":35,"heading":"Story and connections","kind":"story","tokens":[{"text":"A company of roughly thirty or forty drengrs approaches with shields, spears and a mounted horn-blower."}]},{"refs":["f-b01-c031-023","f-b01-c031-024","f-b01-c031-026","f-b01-c031-027"],"from":31,"heading":"Story and connections","kind":"story","tokens":[{"text":"The wide, deep brown river is crowded with boats and wooden piers. Tavern buildings climb a gentle hill towards the timber wall and fortress. The eagle’s outspread skeletal wings are each described as the size of a small hill."}]},{"refs":["f-b01-c040-004"],"from":40,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka's scouting finds Helka's fortress gates and timber walls heavily guarded; Sigrún's drakkar also has the protection of harbour officials and guards."}]}],"images":[{"file":"assets/5cc0a1dc18bba4.jpg","from":35,"role":"scene","spoiler":true}],"curated":false},{"id":"e-170","file":"e-170.html","source":"places/Deserted Slågen farm","category":"places","from":30,"names":[{"from":30,"text":"Deserted Slågen farm"}],"featured":false,"blocks":[{"refs":["f-b01-c030-001","f-b01-c030-003","f-b01-c030-011","f-b01-c030-014"],"from":30,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The Sea-Wolf moors at a farm on the River Slågen's east bank. The farm has a stockade, turf-roofed longhouse and surrounding barley and rye fields. The farm gives no response to Einar's call and shows no smoke or workers. Glornir reports that the farm is empty with neither bodies nor blood."}]}],"images":[],"curated":false},{"id":"e-007","file":"e-007.html","source":"places/Fellur","category":"places","from":1,"names":[{"from":1,"text":"Fellur"}],"featured":false,"blocks":[{"refs":["f-b01-c001-028","f-b01-c001-029","f-b01-c001-030"],"from":1,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Fellur is a fishing village. It lies on the eastern edge of a fjord. The fjord opens into the sea to the south."}]},{"refs":["f-b01-c001-027","f-b01-c001-026"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-001"},{"text":"and "},{"page":"e-002"},{"text":"have visited to trade for provisions. "},{"page":"e-003"},{"text":" has played with Harek on its beach."}]},{"refs":["f-b01-c001-046"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"A track from the eastern side of "},{"page":"e-013"},{"text":" leads towards the village."}]},{"refs":["f-b01-c003-012","f-b01-c003-013","f-b01-c003-014","f-b01-c003-015"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"Fellur has a few dozen reed-thatched wattle-and-daub buildings. A larger longhouse stands at its centre. Parts of its stockade are rotten. The wall ends well short of its dark-sanded beach."}]},{"refs":["f-b01-c003-078","f-b01-c003-079"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"Fishing nets hang on the beach to dry and await repair. Its handful of timber piers are mostly empty, with a few fishing boats and byrding coasters moored."}]},{"refs":["f-b01-c003-017","f-b01-c003-018","f-b01-c003-020"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-001"},{"text":"and "},{"page":"e-002"},{"text":"have brought pelts here to trade. A "},{"page":"e-039"},{"text":" in the gate helps keep vaesen out."}]},{"refs":["f-b01-c003-023","f-b01-c003-049","f-b01-c003-050"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-032"},{"text":"is Jarl of Fellur. "},{"page":"e-033"},{"text":"announces an "},{"page":"e-040"},{"text":"after her return. It is to be held on the "},{"page":"e-037"},{"text":"."}]},{"refs":["f-b01-c022-004","f-b01-c022-005","f-b01-c022-006","f-b01-c022-012","f-b01-c022-016","f-b01-c022-044","f-b01-c022-047"],"from":22,"heading":"Night raid in B01-C022","kind":"story","tokens":[{"text":"Althing visitors camp between the woodland and the gates. Orka scales the wall, frees Mord and Lif, and enters Sigrún’s chamber through a window. She escapes to the brothers’ fishing boat as Guðvarr calls vengeance from the pier."}]}],"images":[{"file":"assets/25dfeb36d23fac.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-168","file":"e-168.html","source":"places/Grimholt","category":"places","from":26,"names":[{"from":26,"text":"Grimholt"}],"featured":false,"blocks":[{"refs":["f-b01-c026-025"],"from":26,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Vol questions how vaesen could have crossed the Bonebacks past the Grimholt and its guard tower."}]},{"refs":["f-b01-c040-013","f-b01-c040-019"],"from":40,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka sees the Grimholt Pass as a gap in the Boneback Mountains north of Darl and chooses to ride towards it in search of Drekr and Breca."}]},{"refs":["f-b01-c046-005","f-b01-c046-018","f-b01-c046-019"],"from":46,"heading":"Story and connections","kind":"story","tokens":[{"text":"The fortress guards one of the few passes through the Bonebacks against northern vaesen. Orka describes a hall with walls north and south, and says she saw it long ago."}]},{"refs":["f-b01-c049-002","f-b01-c049-003","f-b01-c049-004","f-b01-c049-005","f-b01-c049-006","f-b01-c049-007"],"from":49,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka’s reconnaissance shows north and south timber walls spanning the valley, with a turf-roofed hall, rear watchtower and service buildings between. A diverted river loop serves its pier. She counts sixteen visible warriors and estimates a larger population, without confirming Drekr is there."}]},{"refs":["f-b01-c051-001","f-b01-c051-005","f-b01-c051-010","f-b01-c051-017"],"from":51,"heading":"Story and connections","kind":"story","tokens":[{"text":"Skapti admits the fortress has allowed Drekr to bring and store goods under Hakon’s orders, with routes north and west. Orka and the brothers are imprisoned and interrogated in its tower before the raven-assisted escape sets the roof ablaze."}]},{"refs":["f-b01-c053-008","f-b01-c053-009","f-b01-c053-010","f-b01-c053-011","f-b01-c053-013"],"from":53,"heading":"Story and connections","kind":"story","tokens":[{"text":"The Bloodsworn arrive after the violence and find the tower burning, many dead and Orka with two vaesen and about twelve to fifteen children on the hall steps."}]}],"images":[{"file":"assets/af713ccde5411c.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-185","file":"e-185.html","source":"places/Guarded Boneback excavation","category":"places","from":41,"names":[{"from":41,"text":"Guarded Boneback excavation"}],"featured":false,"blocks":[{"refs":["f-b01-c041-004","f-b01-c041-011","f-b01-c041-012","f-b01-c041-013","f-b01-c041-014"],"from":41,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The site lies near a waterfall valley in the Bonebacks. A path leads to a muddy clearing and a wide, torchlit arched tunnel in a cliff. Ragged, skeletal captives in iron collars haul rubble out in pony-drawn carts, guarded by spear-bearing warriors and skraelings. Its purpose is not yet known."}]},{"refs":["f-b01-c043-001","f-b01-c043-003","f-b01-c043-012","f-b01-c043-013","f-b01-c043-033"],"from":43,"heading":"Story and connections","kind":"story","tokens":[{"text":"The Bloodsworn attack the glade, where captives flee and guards force others into the tunnel. A troll and the unnamed bone-sword wielder emerge from the tunnel and counterattack; the battle remains unresolved when Varg loses awareness."}]},{"refs":["f-b01-c045-006","f-b01-c045-011","f-b01-c045-012"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"The survivors occupy an excavated underground catacomb. Torvik reports Vol’s belief that it is Rotta’s chamber, and describes extensive tunnels, barracks, kitchens, horse stabling and hundreds of child-sized mattresses. These descriptions and the chamber identification are his report."}]},{"refs":["f-b01-c047-013","f-b01-c047-015","f-b01-c047-016"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"Varg passes a large chamber with a scarred stone slab, chains and four wrist-and-ankle collars. Outside, the troll is dead and Jökul is freeing surviving captives from their iron collars."}]}],"images":[],"curated":false},{"id":"e-092","file":"e-092.html","source":"places/Howbyr","category":"places","from":10,"names":[{"from":10,"text":"Howbyr"}],"featured":false,"blocks":[{"refs":["f-b01-c010-013"],"from":10,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Howbyr lies ten or twelve leagues north of Fellur."}]},{"refs":["f-b01-c010-011"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Virk reports two daughters and a son of the Haraldursons taken from there."}]}],"images":[],"curated":false},{"id":"e-178","file":"e-178.html","source":"places/Isbrún Bridge","category":"places","from":38,"names":[{"from":29,"text":"Isbrún Bridge"}],"featured":false,"blocks":[{"refs":["f-b01-c038-011","f-b01-c038-013","f-b01-c038-024","f-b01-c038-014"],"from":38,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Uspa reveals the bridge after cutting her palm, applying blood to a black boulder and chanting. It spans the vaesen pit and is solid ice wide enough for fifty warriors abreast, with molten fire visible below. Agnar's assertion that the gods were its last users remains his claim."}]}],"images":[{"file":"assets/339c3a71267c75.jpg","from":43,"role":"scene","spoiler":true}],"curated":false},{"id":"e-060","file":"e-060.html","source":"places/Iskalt Island","category":"places","from":5,"names":[{"from":5,"text":"Iskalt Island"}],"featured":false,"blocks":[{"refs":["f-b01-c005-006"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Iskalt Island is dominated by a mountain with glowing red veins of fire."}]},{"refs":["f-b01-c005-025","f-b01-c005-026"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"Hrut identifies himself as its jarl. He denies knowing a Berak living on the island."}]}],"images":[],"curated":false},{"id":"e-024","file":"e-024.html","source":"places/Iskidan","category":"places","from":2,"names":[{"from":2,"text":"Iskidan"}],"featured":false,"blocks":[{"refs":["f-b01-c002-053","f-b01-c002-052"],"from":2,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Iskidan is described as a land far south across the sea. A dock worker identifies the strangers arriving in "},{"page":"e-017"},{"text":" as coming from there."}]},{"refs":["f-b01-c002-056","f-b01-c002-057","f-b01-c002-058","f-b01-c002-059"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"The arriving strangers wear silver-buckled kaftans and striped blue and orange breeches. Their warrior escorts wear long coats of lamellar plate. The escorts carry curved swords."}]},{"refs":["f-b01-c002-054","f-b01-c002-055"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-014"},{"text":" has heard tales of wide rivers and grass plains there. In those tales he has heard of Gravka, the Great City."}]},{"refs":["f-b01-c010-027"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sigrún says emperor Kirill rules Iskidan from Gravka."}]},{"refs":["f-b01-c010-028","f-b01-c010-029","f-b01-c010-030","f-b01-c010-031"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Virk claims Iskidan has more thralls than freedmen and sacrifices children. Sigrún dismisses this as a saga-tale, while Virk claims eyewitness experience."}]}],"images":[],"curated":false},{"id":"e-093","file":"e-093.html","source":"places/Kergarth","category":"places","from":10,"names":[{"from":10,"text":"Kergarth"}],"featured":false,"blocks":[{"refs":["f-b01-c010-014"],"from":10,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Kergarth lies six leagues east along the coast."}]},{"refs":["f-b01-c010-012"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Virk reports a family found dead and their sons missing."}]}],"images":[],"curated":false},{"id":"e-171","file":"e-171.html","source":"places/Lake Horndal","category":"places","from":32,"names":[{"from":32,"text":"Lake Horndal"}],"featured":false,"blocks":[{"refs":["f-b01-c032-004","f-b01-c032-009"],"from":32,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The Wave-Jarl crosses Lake Horndal. Lake Horndal provides one of only two passes through the Bonebacks to the northern Battle-Plain."}]}],"images":[],"curated":false},{"id":"e-017","file":"e-017.html","source":"places/Liga","category":"places","from":2,"names":[{"from":2,"text":"Liga"}],"featured":false,"blocks":[{"refs":["f-b01-c002-005","f-b01-c002-006","f-b01-c002-007"],"from":2,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Liga is a market town. It is a port on the south-eastern banks of a fjord. A stockade surrounds it."}]},{"refs":["f-b01-c002-008","f-b01-c002-060"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"A grass-turfed long-hall stands on high ground. Jarl Logur’s mead hall lies at the foot of the cliffs above the town."}]},{"refs":["f-b01-c002-103","f-b01-c002-104","f-b01-c002-105"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"The town spreads along a wide black-sanded beach, with crowded piers and hearth smoke above it. Timber-sided buildings line wide muddy market streets, and pier-cranes serve the busy quay."}]},{"refs":["f-b01-c002-025","f-b01-c002-031"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"A trader offers wares presented as vaesen body parts. The stew trader asks a half-bronze for a bowl."}]},{"refs":["f-b01-c002-052"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"A dock worker identifies arriving strangers as coming from "},{"page":"e-024"},{"text":"."}]},{"refs":["f-b01-c002-049","f-b01-c002-062"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"The stew trader says the "},{"page":"e-019"},{"text":" are guests of Jarl Logur at the longhouse. A woman in the queue says they are holding a weapons trial to fill a vacancy."}]},{"refs":["f-b01-c018-046","f-b01-c018-049","f-b01-c018-048","f-b01-c018-055","f-b01-c018-057","f-b01-c018-060","f-b01-c018-073","f-b01-c018-074","f-b01-c018-075"],"from":18,"heading":"Story and connections","kind":"story","tokens":[{"text":"Svik says the Bloodsworn protect Liga’s port from pirates and raiders. In B01-C018, Jaromir’s mounted warriors block the crew’s route to the "},{"page":"e-141"},{"text":" and attack after Glornir refuses to surrender Sulich. Logur arrives with blue-shielded guards as fighting stops and three eagle-bannered drakkar approach; Helka has come to Liga."}]}],"images":[{"file":"assets/8aed35503982f4.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-128","file":"e-128.html","source":"places/Local Ash Tree","category":"places","from":15,"names":[{"from":15,"text":"Local Ash Tree"}],"featured":false,"blocks":[{"refs":["f-b01-c015-051","f-b01-c015-052","f-b01-c015-054"],"from":15,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Orka travels south-east from the steading to reach the tree, which stands on a hillock beside a river meadow. Its "},{"page":"e-127"},{"text":" lives and dies with it."}]},{"refs":["f-b01-c015-053","f-b01-c015-066","f-b01-c015-067","f-b01-c015-068"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C015, Orka finds a hacked, blackened stump and the splintered trunk on the ground. The tree has been attacked with many axes and burned; upturned earth exposes roots where it lashed its attackers. She finds multiple patches of congealed blood."}]}],"images":[],"curated":false},{"id":"e-114","file":"e-114.html","source":"places/Mount Eldrafell","category":"places","from":38,"names":[{"from":13,"text":"Mount Eldrafell"}],"featured":false,"blocks":[{"refs":["f-b01-c038-003","f-b01-c038-004"],"from":38,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Elvar sees the fire mountain beyond the vaesen pit, with a nearly level summit and streams of fire on its slopes. Tales attribute its breaking and the fire's release to Snaka's fall; this account remains traditional history."}]}],"images":[],"curated":false},{"id":"e-200","file":"e-200.html","source":"places/Nastrandir","category":"places","from":52,"names":[{"from":52,"text":"Nastrandir"}],"featured":false,"blocks":[{"refs":["f-b01-c052-038"],"from":52,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Lik-Rifa names Nastrandir as her hall and says she wants to see it after escaping Oskutreð. The hall itself is not visited in this chapter."}]}],"images":[],"curated":false},{"id":"e-037","file":"e-037.html","source":"places/Oath Rock","category":"places","from":3,"names":[{"from":3,"text":"Oath Rock"}],"featured":false,"blocks":[{"refs":["f-b01-c003-052"],"from":3,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The Oath Rock is identified with a rocky island in the fjord."}]},{"refs":["f-b01-c003-049","f-b01-c003-050","f-b01-c003-051"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-033"},{"text":"announces an "},{"page":"e-040"},{"text":"there after "},{"page":"e-032"},{"text":" returns. He says everyone can have their say."}]},{"refs":["f-b01-c010-001","f-b01-c010-002","f-b01-c010-003"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"The stone now stands as shattered, rune-carved fragments. Thorkel says it was a place of blood oaths to the gods. He says worship of the dead gods is now punishable by death."}]}],"images":[],"curated":false},{"id":"e-069","file":"e-069.html","source":"places/Orka and Thorkel’s steading","category":"places","from":6,"names":[{"from":6,"text":"Orka and Thorkel’s steading"}],"featured":false,"blocks":[{"refs":["f-b01-c006-005","f-b01-c006-006","f-b01-c006-017"],"from":6,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The steading includes a forge and charcoal kiln. A stream flows through it. The stream is fed by a pool above it."}]},{"refs":["f-b01-c006-004","f-b01-c006-018"],"from":6,"heading":"Story and connections","kind":"story","tokens":[{"text":"Breca’s cot is empty at dawn in B01-C006. His parents find him by the pool."}]},{"refs":["f-b01-c015-024","f-b01-c015-050","f-b01-c015-048","f-b01-c015-042","f-b01-c015-044"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"Thorkel checks its gate bolts and locks and habitually patrols the stockade. When Orka leaves before dawn, she climbs over the wall so the gate stays locked and asks Spert to watch the steading. The family plans to leave; the move has not yet taken place in B01-C015."}]},{"refs":["f-b01-c017-003","f-b01-c017-005","f-b01-c017-004","f-b01-c017-007","f-b01-c017-010","f-b01-c017-016","f-b01-c017-019","f-b01-c017-020","f-b01-c017-024","f-b01-c017-027","f-b01-c017-029"],"from":17,"heading":"Destruction","kind":"story","tokens":[{"text":"In B01-C017, the gates stand open, one hanging from a single hinge; the protective rune-post is obliterated and the hall burns. Chickens and goats lie dead in the courtyard, and the hall doors are smashed. Thorkel is mortally wounded, says Breca has been taken and dies after Orka carries him outside. Orka rescues Vesli before the hall collapses."}]},{"refs":["f-b01-c019-035","f-b01-c019-044","f-b01-c019-056","f-b01-c019-007","f-b01-c019-033","f-b01-c019-034","f-b01-c019-057"],"from":19,"heading":"Destruction","kind":"story","tokens":[{"text":"After the fire, Orka digs up an old chest near the hall’s western tip and builds a timber-and-stone barrow for Thorkel. She asks Vesli to take the surviving Spert away before villagers might come, then leaves to continue her pursuit."}]}],"images":[],"curated":false},{"id":"e-167","file":"e-167.html","source":"places/River Slågen","category":"places","from":26,"names":[{"from":26,"text":"River Slågen"}],"featured":false,"blocks":[{"refs":["f-b01-c026-021"],"from":26,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Skalk says the mission goes to the River Slågen's source at the Bonebacks, on Helka's northwestern border."}]}],"images":[],"curated":false},{"id":"e-087","file":"e-087.html","source":"places/Snakavik","category":"places","from":9,"names":[{"from":9,"text":"Snakavik"}],"featured":false,"blocks":[{"refs":["f-b01-c009-042","f-b01-c009-044"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Agnar plans to take the captives to Snakavik. Elvar calls the coming journey going home."}]},{"refs":["f-b01-c021-002","f-b01-c021-003","f-b01-c021-014","f-b01-c021-013","f-b01-c021-015","f-b01-c021-012"],"from":21,"heading":"Town within the skull","kind":"story","tokens":[{"text":"Snakavik occupies the immense skull identified as Snaka’s at the western end of the "},{"page":"e-153"},{"text":". Its harbour entrance passes between the lower fangs, wide enough for twenty drakkar abreast. Town, piers and jetties spread inside and around the skull; a fortress crowns the granite plateau above."}]},{"refs":["f-b01-c021-024","f-b01-c021-025","f-b01-c021-016","f-b01-c021-023"],"from":21,"heading":"Town within the skull","kind":"story","tokens":[{"text":"Little daylight enters the enclosed town except through the jaws, eye sockets and fissures. Whale- and seal-oil torches burn throughout it. Dockside cages contain remains of criminals, with one sign reading “Worshipper of a dead god”."}]},{"refs":["f-b01-c021-036","f-b01-c021-037","f-b01-c021-038","f-b01-c021-039"],"from":21,"heading":"Town within the skull","kind":"story","tokens":[{"text":"A winding timber stair passes into a fissure and leads to the crown; Elvar counts 212 steps. A Galdur tower behind Störr’s mead hall houses the learning of Galdurmen. The fortress guards carry yellow serpent shields."}]}],"images":[{"file":"assets/ffac39a08037e6.jpg","from":21,"role":"scene","spoiler":true}],"curated":false},{"id":"e-172","file":"e-172.html","source":"places/Starl","category":"places","from":32,"names":[{"from":32,"text":"Starl"}],"featured":false,"blocks":[{"refs":["f-b01-c032-002","f-b01-c032-008"],"from":32,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The Battle-Grim spend two days in Starl restocking provisions and maintaining the Wave-Jarl. Starl lies under an exposed rib of Snaka that arches over Lake Horndal."}]}],"images":[],"curated":false},{"id":"e-175","file":"e-175.html","source":"places/The Dead Drengr","category":"places","from":33,"names":[{"from":33,"text":"The Dead Drengr"}],"featured":false,"blocks":[{"refs":["f-b01-c033-005","f-b01-c033-007","f-b01-c033-008","f-b01-c033-009","f-b01-c033-015","f-b01-c033-017"],"from":33,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Orka follows a burn-scarred man from the tavern to the Dead Drengr. A woman outside the Dead Drengr carries a black shield with gold eagle wings; Orka identifies her as one of Helka's drengrs. At dawn Orka sees bound children being taken from the Dead Drengr's rear courtyard to a canal boat. A guard strikes a sobbing child, lifts her by the hair and throws her into the boat. The girl reports that other captive children had been held at the tavern but are now gone. The older boy says Drekr is inside the Dead Drengr."}]},{"refs":["f-b01-c035-001","f-b01-c035-002","f-b01-c035-006","f-b01-c035-009","f-b01-c035-014","f-b01-c035-017"],"from":35,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka hears the freed children rowing away as she enters the Dead Drengr courtyard. The Dead Drengr's loft contains about twenty small reed mattresses and smells of urine and faeces. The burned man joins six or seven people playing knucklebone inside the tavern. The hooded young man at Drekr's table is Hakon, whom Orka recognises from the docks. The tavern's players, bartender and doorway guards join the attack against Orka. Orka and Drekr crash through the broken window into the street."}]}],"images":[],"curated":false},{"id":"e-179","file":"e-179.html","source":"places/Vaesen pit","category":"places","from":38,"names":[{"from":1,"text":"Vaesen pit"}],"featured":false,"blocks":[{"refs":["f-b01-c038-001","f-b01-c038-002","f-b01-c038-013"],"from":38,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"At the Battle-Grim's arrival, the pit is a deep chasm containing a river of fire; the approaching ground melts falling snow. The "},{"page":"e-178"},{"text":" crosses it."}]}],"images":[],"curated":false},{"id":"e-011","file":"e-011.html","source":"places/Vigrið","category":"places","from":1,"names":[{"from":1,"text":"Vigrið"}],"featured":false,"blocks":[{"refs":["f-b01-c001-031"],"from":1,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-002"},{"text":" calls the land visible from the ridge Vigrið, the Battle-Plain."}]},{"refs":["f-b01-c001-032","f-b01-c001-039"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"In his account, this is where the gods fought and died. He identifies the distant mountains as "},{"page":"e-008"},{"text":"’s earth-covered bones."}]},{"refs":["f-b01-c002-042"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"The "},{"page":"e-019"},{"text":" are famed throughout Vigrið."}]}],"images":[],"curated":false},{"id":"e-058","file":"e-058.html","source":"factions/Battle-Grim","category":"factions","from":5,"names":[{"from":5,"text":"Battle-Grim"}],"featured":false,"blocks":[{"refs":["f-b01-c005-016","f-b01-c005-017"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sighvat names the warband the Battle-Grim. He calls them hunters of the Tainted."}]},{"refs":["f-b01-c005-003","f-b01-c005-012"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar is Elvar’s chief. Elvar is the youngest of his warband."}]},{"refs":["f-b01-c005-031","f-b01-c005-032"],"from":5,"heading":"Story and connections","kind":"story","tokens":[{"text":"They face villagers who attack after Agnar wounds Hrut."}]},{"refs":["f-b01-c007-002","f-b01-c007-003","f-b01-c007-004"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"A dozen villagers fell at the Iskalt village and Thrud was wounded in the calf. Twenty-six warriors followed Agnar into the hills."}]},{"refs":["f-b01-c007-016","f-b01-c007-022","f-b01-c007-023","f-b01-c007-033"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"They encounter a troll and lose warriors to its attacks. They capture the woman and child."}]},{"refs":["f-b01-c009-016","f-b01-c009-019"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar gives warriors kill-trophies when he thinks they have earned them. They store butchered troll parts for sale."}]},{"refs":["f-b01-c021-033","f-b01-c021-047","f-b01-c021-026","f-b01-c021-048","f-b01-c021-063","f-b01-c021-064"],"from":21,"heading":"Story and connections","kind":"story","tokens":[{"text":"Huld and Sólín carry red shields with a painted spear and axe, identified in B01-C021 as the Battle-Grim sigil. Störr addresses their chief as Agnar Broksson. At Snakavik, Thrud is sent to find lodgings while the chief’s party presents Berak for sale; Agnar accepts the offer and Berak is handed over."}]},{"refs":["f-b01-c027-007","f-b01-c027-010","f-b01-c027-011","f-b01-c027-013"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Thrud is dead with wounds in his throat and back. The tavern's loft hatch has been wedged shut with its ladder, trapping the Battle-Grim above. Sighvat breaks through the roof and Grend releases the hatch. Agnar and the Battle-Grim pursue the attackers to the docks but arrive after their ship has departed."}]},{"refs":["f-b01-c032-001","f-b01-c032-010","f-b01-c032-018"],"from":32,"heading":"Story and connections","kind":"story","tokens":[{"text":"Twelve days have passed since the blood oath, and the Battle-Grim have rowed almost a hundred leagues. The Battle-Grim land after midday on their second day on the lake and assemble their wagons in a secluded inlet. The crew answers Agnar's request to follow with cheers and oaths."}]},{"refs":["f-b01-c042-001","f-b01-c042-002","f-b01-c042-003","f-b01-c042-007","f-b01-c042-015"],"from":42,"heading":"Story and connections","kind":"story","tokens":[{"text":"The tally after the Isbrún crossing records three warriors killed, a wagon and two ponies lost, and almost everyone injured. The survivors treat their wounds and camp again after roughly half a day's march; Agnar orders rest according to fatigue rather than darkness during the perpetual day."}]},{"refs":["f-b01-c048-004","f-b01-c048-006","f-b01-c048-029","f-b01-c048-030","f-b01-c048-032"],"from":48,"heading":"Story and connections","kind":"story","tokens":[{"text":"Forty mailed warriors and four pony-drawn carts reach Oskutreð. Agnar promises to avoid the dead tree and the company collects relics from the plain. Ilska’s company arrives while they work."}]},{"refs":["f-b01-c052-001","f-b01-c052-009","f-b01-c052-010","f-b01-c052-024","f-b01-c052-033"],"from":52,"heading":"Chapter 52 — Facing the Raven-Feeders","kind":"story","tokens":[{"text":"After Agnar’s death Grend rallies the company. Their shield wall holds and drives the Raven-Feeders back until the rupture beneath Oskutreð scatters the battle. Elvar and Grend are among the survivors."}]},{"refs":["f-b01-c052-043","f-b01-c052-044"],"from":52,"heading":"Chapter 52 — Facing the Raven-Feeders","kind":"story","tokens":[{"text":"Before the charge the Battle-Grim overlap their shields at Grend's command; the Raven-Feeders halt ten paces away."}]}],"images":[{"file":"assets/bc7d096c1db406.jpg","from":53,"role":"scene","spoiler":true}],"curated":false},{"id":"e-019","file":"e-019.html","source":"factions/Bloodsworn","category":"factions","from":2,"names":[{"from":2,"text":"Bloodsworn"}],"featured":false,"blocks":[{"refs":["f-b01-c002-043","f-b01-c002-042","f-b01-c002-048"],"from":2,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The Bloodsworn are mercenary warriors who hire themselves to the highest bidder. They are famed throughout "},{"page":"e-011"},{"text":". Skálds sing tales of them around hearth fires."}]},{"refs":["f-b01-c002-044","f-b01-c002-045","f-b01-c002-046","f-b01-c002-047"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"They hunt "},{"page":"e-012"},{"text":"-monsters. They seek god-relics for wealthy jarls. They fight in border disputes. They guard wealthy and powerful people."}]},{"refs":["f-b01-c002-040","f-b01-c002-049","f-b01-c002-041"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"The stew trader says they docked in "},{"page":"e-017"},{"text":" the previous day. He says they are guests of Jarl Logur at the longhouse. He says they have a Seiðr-witch thrall."}]},{"refs":["f-b01-c002-061","f-b01-c002-062","f-b01-c002-078"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"A woman in the queue says one of their warriors has been slain. She says a weapons trial is being held to fill the vacancy. "},{"page":"e-021"},{"text":"names the trial fighter "},{"page":"e-022"},{"text":"."}]},{"refs":["f-b01-c002-084","f-b01-c002-095"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"Svik says "},{"page":"e-020"},{"text":" uses her talents only for the Bloodsworn. He refuses to hire her out."}]},{"refs":["f-b01-c004-014"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"At the trial, the blonde woman announces Varg’s challenge as being for a place on their oar-bench and shield wall."}]},{"refs":["f-b01-c004-089","f-b01-c004-090","f-b01-c004-095"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"Einar and Svik intervene against Varg’s pursuers. At the chapter’s close, the grey-bearded rescuer declares Varg one of the Bloodsworn."}]},{"refs":["f-b01-c011-003","f-b01-c011-015"],"from":11,"heading":"Story and connections","kind":"story","tokens":[{"text":"Røkia names their chief Glornir Shield-Breaker. Their shields are black with red splatters."}]},{"refs":["f-b01-c011-032","f-b01-c011-010"],"from":11,"heading":"Story and connections","kind":"story","tokens":[{"text":"Svik says the trial concerned how contestants lost, since all lost to Einar."}]},{"refs":["f-b01-c013-011"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Torvik reports courage or loyalty must be proven before the oath."}]},{"refs":["f-b01-c013-041","f-b01-c013-045"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Glornir says Sulich has sworn to stand, fight, live and die with the crew. The Bloodsworn rise when Glornir is threatened."}]},{"refs":["f-b01-c016-039","f-b01-c004-095","f-b01-c016-036","f-b01-c016-037","f-b01-c016-040","f-b01-c016-041"],"from":16,"heading":"Apprenticeship","kind":"story","tokens":[{"text":"Glornir clarifies in B01-C016 that Varg is an apprentice, despite his earlier declaration to Leif that Varg was Bloodsworn. He says membership requires battle skill, courage, strength, loyalty and devotion unto death. The crew will teach, feed and protect Varg; in exchange he must learn, obey and fight."}]},{"refs":["f-b01-c016-019","f-b01-c016-021"],"from":16,"heading":"Apprenticeship","kind":"story","tokens":[{"text":"Glornir announces a departure with the tide that day; Logur promises provisions."}]},{"refs":["f-b01-c018-048","f-b01-c018-043","f-b01-c018-045","f-b01-c018-046"],"from":18,"heading":"Ships, former leadership and Liga","kind":"story","tokens":[{"text":"Their ship is the "},{"page":"e-141"},{"text":". Torvik says Skullsplitter was their old chief and gave Logur the rafter relic; Svik says Skullsplitter is dead. Svik says they protect Liga from pirates and raiders."}]},{"refs":["f-b01-c018-058","f-b01-c018-061","f-b01-c018-062","f-b01-c018-063","f-b01-c018-073","f-b01-c018-074","f-b01-c018-075"],"from":18,"heading":"Ships, former leadership and Liga","kind":"story","tokens":[{"text":"At the docks they shield Glornir against Jaromir’s arrows and form a wall against the cavalry; their rear row reforms when more mounted warriors attack from behind. The confrontation is interrupted by the arrival of three eagle-bannered drakkar and Helka."}]},{"refs":["f-b01-c020-040","f-b01-c020-038","f-b01-c020-042"],"from":20,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"After the dockside battle, Bloodsworn strip fallen druzhina of gear and allow a druzhina to take the fallen Bloodsworn’s gear. Sulich calls such gear battle spoils that preserve the victor’s tale; Svik says taking another warrior’s kill is dishonourable."}]},{"refs":["f-b01-c020-056","f-b01-c020-057","f-b01-c020-059","f-b01-c020-062"],"from":20,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"Glornir announces work against something eating Helka’s people in the north. Skalk and two of her warriors travel with them and are ordered to row. They leave Liga in the Sea-Wolf, initially steering south and west."}]},{"refs":["f-b01-c026-001","f-b01-c026-002","f-b01-c026-021","f-b01-c026-027"],"from":26,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"The Sea-Wolf has survived a summer storm and enters a steep-sided fjord. Two days have passed since the Bloodsworn left Liga. Skalk says the mission goes to the River Slågen's source at the Bonebacks, on Helka's northwestern border. Glornir demands equal respect for Vol and every crew member who risks their life on his ship."}]},{"refs":["f-b01-c030-002","f-b01-c030-009","f-b01-c030-010","f-b01-c030-016"],"from":30,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"The Bloodsworn have rowed upstream for five days before continuing on foot. Fifty Bloodsworn leave the ship and ten remain to guard it. The ship guards were selected by drawing lots. Edel leads Torvik and the other scouts north through the fields, with the rest following."}]},{"refs":["f-b01-c034-010","f-b01-c034-013","f-b01-c034-014"],"from":34,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"Bloodsworn and the royal guards laugh together at Svik's story. Eight days have passed since the Bloodsworn left the ship and deserted farm. The company now loads its kit on three ponies said to have come from the farm, whereas Chapter 30 described two; the added pony is unexplained."}]},{"refs":["f-b01-c041-001","f-b01-c041-009","f-b01-c041-012","f-b01-c041-014","f-b01-c041-021"],"from":41,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"Three days after the hanging corpses are found, Glornir splits the company into captain-led groups accompanied by scouts to approach a guarded excavation. Svik's group prepares to fight, then advances as Glornir steps into the glade."}]},{"refs":["f-b01-c047-009","f-b01-c047-018","f-b01-c047-019"],"from":47,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"Chapter 47 reveals the company’s concealed god-touched nature. Svik says all the Bloodsworn are Tainted, while Edel explains their secrecy as protection against being hunted. Svik distinguishes membership from ancestry: other Tainted warbands exist and trustworthiness must be proven."}]},{"refs":["f-b01-c047-024","f-b01-c047-025","f-b01-c047-026","f-b01-c047-027","f-b01-c047-028","f-b01-c047-029"],"from":47,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"Glornir invites Varg to join and Varg accepts, receiving a silver bear-headed arm ring. The spoken oath is postponed while the company goes to recover Vol, whom Glornir names as his wife."}]},{"refs":["f-b01-c053-006","f-b01-c053-008","f-b01-c053-009","f-b01-c053-011","f-b01-c053-013","f-b01-c053-016"],"from":53,"heading":"Battle spoils and the new assignment","kind":"story","tokens":[{"text":"After two days pursuing Skalk they reach the devastated Grimholt, where Glornir recognises Orka Skullsplitter among the surviving children and vaesen. The scene does not show Vol’s recovery or Varg speaking the postponed oath."}]}],"images":[],"curated":false},{"id":"e-118","file":"e-118.html","source":"factions/Druzhina","category":"factions","from":13,"names":[{"from":13,"text":"Druzhina"}],"featured":false,"blocks":[{"refs":["f-b01-c013-034"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sergei says Jaromir has the right to be escorted by two druzhina."}]},{"refs":["f-b01-c018-049","f-b01-c018-050","f-b01-c018-057","f-b01-c018-060","f-b01-c018-062","f-b01-c018-069","f-b01-c018-070"],"from":18,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C018, Jaromir leads mounted warriors in plumed iron helmets and long lamellar coats, with Ilia beside him. They loose arrows and charge with lances; more riders attack the Bloodsworn from the rear. Varg penetrates one rider’s lamellar coat through a gap near its fastenings and unhorses the wounded rider."}]}],"images":[],"curated":false},{"id":"e-148","file":"e-148.html","source":"factions/Helka’s wolf-pack","category":"factions","from":20,"names":[{"from":20,"text":"Helka’s wolf-pack"}],"featured":false,"blocks":[{"refs":["f-b01-c020-010","f-b01-c020-011","f-b01-c020-012","f-b01-c020-026"],"from":20,"heading":"Appearance","kind":"introduction","tokens":[{"text":"Twelve mail-clad warriors with thrall collars form Helka’s forward guard. They have shaved sides to their heads, tattoos and fur-edged grey wool cloaks. Varg sees fluid coordination in their movement and misery in one guard’s eyes; both descriptions are his impressions."}]},{"refs":["f-b01-c020-028","f-b01-c020-029","f-b01-c020-030","f-b01-c020-020"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"Svik calls them Helka’s wolf-pack and says they are Úlfhéðnar descended from Ulfrir, well-treated but still enslaved. These descriptions of ancestry and treatment retain his attribution. The guards control access to Helka."}]}],"images":[],"curated":false},{"id":"e-156","file":"e-156.html","source":"factions/Raven-Feeders","category":"factions","from":21,"names":[{"from":21,"text":"Raven-Feeders"}],"featured":false,"blocks":[{"refs":["f-b01-c021-030","f-b01-c021-032","f-b01-c021-031","f-b01-c021-029"],"from":21,"heading":"Appearance","kind":"introduction","tokens":[{"text":"Elvar recognises the Raven-Feeders outside a Snakavik tavern and knows their ruthless reputation. Their leader is "},{"page":"e-157"},{"text":", also called Ilska the Cruel. Their warriors wear raven feathers in their hair and carry grey shields with black wings."}]},{"refs":["f-b01-c027-012","f-b01-c027-014","f-b01-c027-024"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Elvar identifies the attackers as Ilska's Raven-Feeders and the dead blond man as the warrior she saw earlier. Ilska's drakkar carries grey shields painted with black wings. Agnar confirms Ilska's Raven-Feeders took Bjarn and initially declines a costly pursuit."}]},{"refs":["f-b01-c029-010","f-b01-c029-011"],"from":29,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa says she and Berak stole the Graskinna from the Raven-Feeders, who have hunted them for a long time. Uspa says Berak killed Raven-Feeders and others during their escape."}]},{"refs":["f-b01-c050-003","f-b01-c050-018","f-b01-c050-019","f-b01-c050-021","f-b01-c050-022"],"from":50,"heading":"Story and connections","kind":"story","tokens":[{"text":"Their Oskutreð force includes fifteen riders, perhaps sixty marching warriors and twelve covered carts. The carts prove to contain scores of collared children, including the boy Uspa recognises as Bjarn. Skrið is Vörn’s identified dragon-born; Elvar’s wider conclusion about the mounted group remains attributed."}]},{"refs":["f-b01-c052-042","f-b01-c052-044","f-b01-c052-045","f-b01-c052-046"],"from":52,"heading":"Chapter 52 — Shield walls at Oskutreð","kind":"story","tokens":[{"text":"Over sixty Raven-Feeder infantry approach in lines with raised shields, halting ten paces from the Battle-Grim before charging. At impact their wall is at least three lines deep. Ilska leads her inner group towards the carts and Vörn instead."}]},{"refs":["f-b01-c052-003","f-b01-c052-019","f-b01-c052-020","f-b01-c052-021","f-b01-c052-022","f-b01-c052-023","f-b01-c052-026","f-b01-c052-037","f-b01-c052-040","f-b01-c052-041"],"from":52,"heading":"Chapter 52 — Shield walls at Oskutreð","kind":"story","tokens":[{"text":"Biórr explicitly declares Ilska a protector of the Tainted. Ilska’s inner group frees Lik-Rifa using the collared children; after the release the warband recovers its carts and child captives and follows the dragon south."}]}],"images":[{"file":"assets/bc7d096c1db406.jpg","from":53,"role":"scene","spoiler":true}],"curated":false},{"id":"e-160","file":"e-160.html","source":"factions/Störr’s Berserkir thrall-guard","category":"factions","from":21,"names":[{"from":21,"text":"Störr’s Berserkir thrall-guard"}],"featured":false,"blocks":[{"refs":["f-b01-c021-050","f-b01-c021-045","f-b01-c021-044","f-b01-c021-064"],"from":21,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The narrator identifies the collared guards around Störr as Berserkirs. They are broad and muscular, wearing iron bear-claw pendants and carrying axes. Two accompany Silrið when she takes Berak away."}]}],"images":[],"curated":false},{"id":"e-009","file":"e-009.html","source":"creatures/Fell-wolf","category":"creatures","from":1,"names":[{"from":1,"text":"Fell-wolf"}],"featured":false,"blocks":[{"refs":["f-b01-c001-010"],"from":1,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-002"},{"text":" identifies the beast encountered during the hunt as a fell-wolf."}]},{"refs":["f-b01-c001-011","f-b01-c001-012","f-b01-c001-013"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"This individual has slate fur and long claws. It bleeds from many wounds."}]},{"refs":["f-b01-c001-009","f-b01-c001-078"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"Thorkel says it startled the reindeer. "},{"page":"e-003"},{"text":"asks what wounded it. See "},{"text":"the cause of its wounds"},{"text":"."}]}],"images":[],"curated":false},{"id":"e-127","file":"e-127.html","source":"creatures/Froa of the local Ash Tree","category":"creatures","from":15,"names":[{"from":15,"text":"Froa of the local Ash Tree"}],"featured":false,"blocks":[{"refs":["f-b01-c015-054","f-b01-c015-059","f-b01-c015-060"],"from":15,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"This Froa is the spirit of the "},{"page":"e-128"},{"text":", her life bound to the tree she was born from and guarded. The narrator calls her the guardian of the forest and describes her as born from a seed of "},{"page":"e-084"},{"text":"."}]},{"refs":["f-b01-c015-055","f-b01-c015-056","f-b01-c015-058","f-b01-c015-062"],"from":15,"heading":"Appearance","kind":"appearance","tokens":[{"text":"She resembles a wooden statue taller than Orka, with waist-length hair thick with leaves and twigs. On Orka’s previous visit she offered friendship; Orka credits her with protecting the family in her forest."}]},{"refs":["f-b01-c015-057","f-b01-c015-053","f-b01-c015-071"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C015, Orka finds her dead beside the destroyed tree, her body hacked, splintered and partly burned. The attackers are unknown; Orka’s proposed link to Asgrim and Idrun’s killers is a question."}]}],"images":[{"file":"assets/de77677eec9ea3.jpg","from":21,"role":"primary","spoiler":false}],"curated":false},{"id":"e-129","file":"e-129.html","source":"creatures/Froa","category":"creatures","from":2,"names":[{"from":2,"text":"Froa"}],"featured":false,"blocks":[{"refs":["f-b01-c002-028"],"from":2,"heading":"Appearance","kind":"introduction","tokens":[{"text":"At Liga, a trader’s wares presented as vaesen parts include a necklace made from Froa-spirit hair."}]},{"refs":["f-b01-c015-064","f-b01-c015-065","f-b01-c015-059","f-b01-c015-057","f-b01-c015-053"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"Froa are powerful vaesen whose spirits are bound to ash trees, living and dying with them. Orka’s local "},{"page":"e-127"},{"text":" is found dead with her tree destroyed in B01-C015."}]}],"images":[],"curated":false},{"id":"e-077","file":"e-077.html","source":"creatures/Frost-spider","category":"creatures","from":7,"names":[{"from":7,"text":"Frost-spider"}],"featured":false,"blocks":[{"refs":["f-b01-c007-013"],"from":7,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Elvar has seen frost-spider venom freeze blood and stop the heart."}]},{"refs":["f-b01-c007-012"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"During the Iskalt pursuit she sees finger-thick cobwebs."}]},{"refs":["f-b01-c049-009","f-b01-c049-010","f-b01-c049-014","f-b01-c049-015","f-b01-c049-017","f-b01-c049-021"],"from":49,"heading":"Chapter 49 — The giant ravens near Grimholt","kind":"story","tokens":[{"text":"Near Grimholt many boar-sized spiders entangle giant ravens. Their bite visibly turns Lif’s limbs blue and stiff; thrown web burns and numbs Orka through wool. Orka describes the venom as chilling blood and immobilising victims, with severe freezing possible, but the full claimed mechanism remains her account."}]},{"refs":["f-b01-c049-027","f-b01-c049-028"],"from":49,"heading":"Chapter 49 — The giant ravens near Grimholt","kind":"story","tokens":[{"text":"The approaching spider is fat-bodied and hoar-crusted, with long spindle-legs and bright glittering eyes. Dense frost-webs in the boughs are as thick as Orka's wrist."}]}],"images":[{"file":"assets/5ad3e346ea1bb7.jpg","from":53,"role":"scene","spoiler":true}],"curated":false},{"id":"e-196","file":"e-196.html","source":"creatures/Giant speaking ravens","category":"creatures","from":49,"names":[{"from":49,"text":"Giant speaking ravens"}],"featured":false,"blocks":[{"refs":["f-b01-c049-009","f-b01-c049-011","f-b01-c049-012","f-b01-c049-018","f-b01-c049-019"],"from":49,"heading":"Chapter 49 — The frost-spider encounter","kind":"introduction","tokens":[{"text":"Orka encounters two horse-sized black ravens near Grimholt. One is trapped in frost-web while the other tries to free it; both speak. Orka and the brothers intervene, and the birds repay the aid by saving her from a spider before thanking her and flying away. Neither bird’s name or ancestry is given here."}]},{"refs":["f-b01-c051-017","f-b01-c051-018"],"from":51,"heading":"Chapter 51 — Returning the aid","kind":"story","tokens":[{"text":"They repay Orka’s aid by tearing the roof from Grimholt’s tower and attacking a guard. They bring Spert and Vesli, saying they found her friends looking for her."}]}],"images":[{"file":"assets/5ad3e346ea1bb7.jpg","from":53,"role":"scene","spoiler":true}],"curated":false},{"id":"e-159","file":"e-159.html","source":"creatures/Hrung","category":"creatures","from":21,"names":[{"from":21,"text":"Hrung"}],"featured":false,"blocks":[{"refs":["f-b01-c021-041","f-b01-c021-057","f-b01-c021-058"],"from":21,"heading":"Appearance","kind":"introduction","tokens":[{"text":"Hrung is the giant marble-like head behind Störr’s chair, dark veins seeming to glow in the torchlight. Silrið wakes him with a kick and command; he opens cloudy eyes and says he was dreaming."}]},{"refs":["f-b01-c021-059","f-b01-c021-060","f-b01-c021-066","f-b01-c021-068","f-b01-c021-069"],"from":21,"heading":"Story and connections","kind":"story","tokens":[{"text":"He tastes blood taken from Berak and pronounces it Berser’s blood. Later he announces Elvar’s presence before she pulls back her hood and addresses Störr as her father. His origin and recognition mechanism are not explained in this chapter."}]},{"refs":["f-b01-c025-015","f-b01-c025-016","f-b01-c025-018","f-b01-c025-020","f-b01-c025-021","f-b01-c025-022"],"from":25,"heading":"Story and connections","kind":"story","tokens":[{"text":"Gytha says Hrung sleeps longer and more heavily than he used to. Elvar wakes Hrung by flicking mead onto his lips. Hrung says he wishes Störr and Silrið had left him dead in Snaka's throat. Hrung attributes his continuing life after decapitation to a fragment of Snaka's dying power. Hrung says he spent three hundred years in the deep fjord. Hrung answers Elvar's request for guidance with a riddle about whether the sun can be cold, the sea dry or a wolf a lamb."}]},{"refs":["f-b01-c025-025"],"from":25,"heading":"Story and connections","kind":"story","tokens":[{"text":"Hrung’s long moustache droops while he sleeps during Elvar’s visit."}]}],"images":[{"file":"assets/2cb8aa9c827365.jpg","from":35,"role":"primary","spoiler":false}],"curated":false},{"id":"e-125","file":"e-125.html","source":"creatures/Night-wyrm","category":"creatures","from":14,"names":[{"from":14,"text":"Night-wyrm"}],"featured":false,"blocks":[{"refs":["f-b01-c014-029"],"from":14,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Many pale night-wyrms emerge from the ground and pin the sleepers at the Frost-Isles camp."}]},{"refs":["f-b01-c014-030","f-b01-c014-031"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"They have slimy segmented bodies and bristles. They force into Grend’s mouth and nose."}]},{"refs":["f-b01-c014-036","f-b01-c014-037"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Biórr and others burn them with flaming branches, and survivors retreat underground."}]}],"images":[],"curated":false},{"id":"e-068","file":"e-068.html","source":"creatures/Näcken","category":"creatures","from":6,"names":[{"from":6,"text":"Näcken"}],"featured":false,"blocks":[{"refs":["f-b01-c006-020"],"from":6,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Thorkel thinks he smells Näcken at the pool above the family steading."}]},{"refs":["f-b01-c006-022"],"from":6,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka thinks a Näcken should not be so far from its mountain river."}]},{"refs":["f-b01-c028-007","f-b01-c028-012","f-b01-c028-013","f-b01-c028-014","f-b01-c028-017","f-b01-c028-020","f-b01-c028-021","f-b01-c028-022"],"from":28,"heading":"Story and connections","kind":"story","tokens":[{"text":"A melody near the rapids draws Orka into memories and leaves Lif frozen at his oar. The Näcken has reed-like hair, jade-dark eyes and a distended mouth with needle-long teeth. The lulling music ceases for Orka underwater and returns when she breaks the surface. A large lyre with rotted-gut strings rests on mixed human and animal bones beneath the Näcken. The Näcken releases Mord after Orka's first wound, then grabs her ankle as she pushes Mord towards shore. The Näcken's shriek exerts pressure through the water and hurls Orka away. Lif helps Orka reach shore with a spear, and the Näcken retreats underwater; its death is not established. Orka plants iron blades in the bank and says Näcken dislike iron and sense it through the earth."}]},{"refs":["f-b01-c028-023","f-b01-c028-024","f-b01-c028-025"],"from":28,"heading":"Story and connections","kind":"story","tokens":[{"text":"The encountered river Näcken has a man-shaped outline with thick, slime-covered green arms and green-scaled wrists. Sunken branches frame its bone lair."}]}],"images":[{"file":"assets/9e09b77b25c69b.jpg","from":35,"role":"primary","spoiler":false}],"curated":false},{"id":"e-086","file":"e-086.html","source":"creatures/Sjávarorm","category":"creatures","from":9,"names":[{"from":9,"text":"Sjávarorm"}],"featured":false,"blocks":[{"refs":["f-b01-c009-020"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Agnar names the attacking sea serpent Sjávarorm."}]},{"refs":["f-b01-c009-021","f-b01-c009-022","f-b01-c009-026","f-b01-c009-027","f-b01-c009-028"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"It tears a goat and knocks Berak’s boy into the sea. It turns, slows and dives away during the mother’s song."}]}],"images":[],"curated":false},{"id":"e-142","file":"e-142.html","source":"creatures/Skraeling","category":"creatures","from":19,"names":[{"from":19,"text":"Skraeling"}],"featured":false,"blocks":[{"refs":["f-b01-c019-021","f-b01-c019-016"],"from":19,"heading":"Appearance","kind":"introduction","tokens":[{"text":"Vesli identifies skraeling among the attackers who came to Orka’s steading. No appearance or capabilities are described for them in this account."}]},{"refs":["f-b01-c041-007","f-b01-c041-022","f-b01-c043-002","f-b01-c043-034"],"from":43,"heading":"Observed at the Boneback excavation","kind":"story","tokens":[{"text":"The guards observed in Chapters 41 and 43 have long, heavily muscled arms, thick necks and a stooped, knuckle-supported posture. Varg sees uneven humanlike faces, small dark eyes and small lower-jaw tusks. One facing Varg and Torvik draws a broad, thick blade between a seax and a sword in length."}]}],"images":[{"file":"assets/f4bec90b61a79a.jpg","from":43,"role":"primary","spoiler":false}],"curated":false},{"id":"e-133","file":"e-133.html","source":"creatures/Snort","category":"creatures","from":17,"names":[{"from":17,"text":"Snort"}],"featured":false,"blocks":[{"refs":["f-b01-c017-038","f-b01-c017-039"],"from":17,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Snort is the pony Orka finds dead on the riverbank in B01-C017, with a wound in his neck. Three men and a woman are butchering him when she arrives."}]}],"images":[],"curated":false},{"id":"e-065","file":"e-065.html","source":"creatures/Spert","category":"creatures","from":6,"names":[{"from":6,"text":"Spert"}],"featured":false,"blocks":[{"refs":["f-b01-c006-007","f-b01-c006-008"],"from":6,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Orka calls the Spertus Spert."}]},{"refs":["f-b01-c006-009","f-b01-c006-010","f-b01-c006-011"],"from":6,"heading":"Story and connections","kind":"story","tokens":[{"text":"He has a segmented chitinous body and a curved sting over his back. He has a humanlike face."}]},{"refs":["f-b01-c006-012","f-b01-c006-013","f-b01-c006-014"],"from":6,"heading":"Story and connections","kind":"story","tokens":[{"text":"Breca usually feeds him porridge mixed with blood and spit. Spert claims to protect the family from vaesen. He admits he cannot watch everything all the time."}]},{"refs":["f-b01-c008-010","f-b01-c008-017"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"Spert emits black vapour at Vesli’s approach and later sucks it back."}]},{"refs":["f-b01-c008-018","f-b01-c008-019"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka caught and bound him years earlier; his food contains her blood and spit."}]},{"refs":["f-b01-c008-014"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"He demands Vesli swear with blood."}]},{"refs":["f-b01-c015-011","f-b01-c015-046","f-b01-c015-048","f-b01-c015-049"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"After the family’s return from Fellur, Breca placates Spert with twice his usual portion of porridge. Before leaving to visit the Ash Tree, Orka prepares a bowl of her blood and spit and asks him to watch the steading; he agrees."}]},{"refs":["f-b01-c017-008","f-b01-c017-009"],"from":17,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C017, Orka finds Spert unnaturally still on his rock, black ichor oozing from a hole in his body. Around him lie about a dozen tennúr that appear dead. His condition is not independently confirmed beyond this observation."}]},{"refs":["f-b01-c019-007","f-b01-c019-008","f-b01-c019-010","f-b01-c019-009","f-b01-c019-014"],"from":19,"heading":"Survival and treatment","kind":"story","tokens":[{"text":"In B01-C019, Spert is confirmed alive and breathing shallowly. His wound has pale stitches and a thick opaque coating; Vesli confirms she stitched it and gives him water from a bandage. He says he killed many vaesen but was speared by a human."}]},{"refs":["f-b01-c051-018","f-b01-c051-019"],"from":51,"heading":"Chapter 51 — Flight at Grimholt","kind":"story","tokens":[{"text":"He reaches Grimholt with Vesli and the giant ravens. His sting is directly observed blackening a warrior’s veins and tongue before she collapses, strengthening the evidence beyond Orka’s earlier inference about a dead intruder."}]},{"refs":["f-b01-c051-025"],"from":51,"heading":"Chapter 51 — Flight at Grimholt","kind":"story","tokens":[{"text":"His wings buzz as he hovers and darts, directly demonstrating flight."}]},{"refs":["f-b01-c053-009","f-b01-c053-011"],"from":53,"heading":"Chapter 53 — After the battle","kind":"story","tokens":[{"text":"At the Bloodsworn’s arrival he is perched on Orka’s shoulder beside the children on Grimholt’s steps."}]}],"images":[{"file":"assets/73b12afd8cb46a.jpg","from":53,"role":"secondary","spoiler":true},{"file":"assets/2211e8b8c01a11.jpg","from":21,"role":"primary","spoiler":false}],"curated":false},{"id":"e-010","file":"e-010.html","source":"creatures/Tennúr","category":"creatures","from":1,"names":[{"from":1,"text":"Tennúr"}],"featured":false,"blocks":[{"refs":["f-b01-c001-057","f-b01-c001-058","f-b01-c001-059","f-b01-c001-060"],"from":1,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Tennúr are small, two-legged creatures. They have sharp-boned fingers and razor teeth. A pack can be deadly."}]},{"refs":["f-b01-c001-056","f-b01-c001-055","f-b01-c001-054"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-001"},{"text":" says they covet human teeth. She attributes Asgrim’s missing teeth to them. His mouth has empty, bloodied sockets."}]},{"refs":["f-b01-c006-027","f-b01-c006-035","f-b01-c006-033"],"from":6,"heading":"Story and connections","kind":"story","tokens":[{"text":"Thorkel identifies the creature Breca finds as a tennúr. Breca reports her name as Vesli. Breca says he gives her one of his teeth."}]},{"refs":["f-b01-c017-009","f-b01-c017-008","f-b01-c017-026","f-b01-c017-027","f-b01-c017-030"],"from":17,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka finds about a dozen tennúr around the wounded Spert at the attacked steading; they appear dead. Vesli, separately found inside the hall, survives and is carried outside."}]},{"refs":["f-b01-c019-031","f-b01-c019-012","f-b01-c019-029"],"from":19,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vesli demonstrates that her spit can congeal into tendon-like strings; she treats Orka’s wounds, after which Orka feels less pain. The source establishes this for Vesli, rather than every tennúr."}]},{"refs":["f-b01-c019-020","f-b01-c019-027","f-b01-c019-002"],"from":19,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vesli says oathless tennúr broke into the hall and tried to take Breca; she fought them. In B01-C019 the dozen tennúr lying around the stream are described as dead."}]},{"refs":["f-b01-c038-015","f-b01-c038-016","f-b01-c038-023"],"from":38,"heading":"Story and connections","kind":"story","tokens":[{"text":"At the vaesen pit, dozens emerge from underground and attack the Battle-Grim. One observed creature is knee-high, hairless and pink-skinned with dark veins, wings and two rows of teeth. The attack kills a pony and several warriors."}]}],"images":[],"curated":false},{"id":"e-074","file":"e-074.html","source":"creatures/Troll","category":"creatures","from":7,"names":[{"from":7,"text":"Troll"}],"featured":false,"blocks":[{"refs":["f-b01-c007-009","f-b01-c007-010","f-b01-c007-011"],"from":7,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Trolls are fiercely territorial. Males are usually solitary except around mating. Newborn trolls are strong and nimble."}]},{"refs":["f-b01-c007-017"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"A troll encountered on Iskalt has stubby antlers."}]}],"images":[{"file":"assets/2ee4ca3b77e7f3.jpg","from":21,"role":"primary","spoiler":false}],"curated":false},{"id":"e-012","file":"e-012.html","source":"creatures/Vaesen","category":"creatures","from":1,"names":[{"from":1,"text":"Vaesen"}],"featured":false,"blocks":[{"refs":["f-b01-c001-040","f-b01-c001-041"],"from":1,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-001"},{"text":"says "},{"page":"e-008"},{"text":"’s fall opened the vaesen pit. She says creatures from below were released into their land."}]},{"refs":["f-b01-c001-066","f-b01-c001-067"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"In her assessment, runes hold back all but the most powerful vaesen. She considers it rare for vaesen to use weapons."}]},{"refs":["f-b01-c002-044","f-b01-c002-025"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"text":"The "},{"page":"e-019"},{"text":"hunt vaesen-monsters. In "},{"page":"e-017"},{"text":", a trader offers wares presented as vaesen body parts."}]},{"refs":["f-b01-c003-016","f-b01-c003-020"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka thinks vaesen prefer quiet, dark places where they can remain hidden. The god-bone in "},{"page":"e-007"},{"text":"’s gate helps keep them out of the village."}]},{"refs":["f-b01-c003-053","f-b01-c003-054","f-b01-c003-057"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-033"},{"text":" blames the killings at Asgrim’s steading on vaesen. Orka denies his accusation. In her argument with Guðvarr in B01-C003, she says vaesen hunt with tooth and claw rather than iron swords."}]},{"refs":["f-b01-c015-064","f-b01-c015-065","f-b01-c015-059","f-b01-c015-053","f-b01-c015-057"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-129"},{"text":"are powerful vaesen bound to ash trees; they live and die with their trees. Orka finds the "},{"page":"e-127"},{"text":" dead beside its destroyed tree."}]}],"images":[],"curated":false},{"id":"e-067","file":"e-067.html","source":"creatures/Vesli","category":"creatures","from":6,"names":[{"from":6,"text":"Vesli"}],"featured":false,"blocks":[{"refs":["f-b01-c006-035","f-b01-c006-027"],"from":6,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Breca reports the creature’s name as Vesli. Thorkel identifies her as a tennúr."}]},{"refs":["f-b01-c006-024","f-b01-c006-025","f-b01-c006-026","f-b01-c006-023"],"from":6,"heading":"Story and connections","kind":"story","tokens":[{"text":"She has thin wings, large black eyes and two rows of teeth. She is bleeding beneath one wing when found."}]},{"refs":["f-b01-c006-033","f-b01-c006-029"],"from":6,"heading":"Story and connections","kind":"story","tokens":[{"text":"Breca says he gives her a tooth. She shields Breca from Orka."}]},{"refs":["f-b01-c008-011"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"Breca says Vesli was outcast by her pack."}]},{"refs":["f-b01-c008-015","f-b01-c008-016","f-b01-c008-020"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vesli cuts her palm and swears faithfulness to Breca and Spert on her life-blood. Thorkel says she owes a blood-debt if she survives."}]},{"refs":["f-b01-c015-073","f-b01-c015-002","f-b01-c015-013","f-b01-c015-018"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vesli follows Breca throughout the steading, and her wounds seem to be healing well. Orka feeds her ham and onions. At the family meal, Vesli argues that the dead do not need their teeth."}]},{"refs":["f-b01-c017-018","f-b01-c017-026","f-b01-c017-027","f-b01-c017-029","f-b01-c017-030"],"from":17,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C017, Orka finds Vesli motionless beneath a woman’s body, her head and face bloody. On returning to retrieve her spear, she discovers Vesli moving and picks her up. Outside the collapsing hall, she lays Vesli beside Thorkel; Vesli is breathing and twitching."}]},{"refs":["f-b01-c019-005","f-b01-c019-006","f-b01-c019-010","f-b01-c019-009","f-b01-c019-012","f-b01-c019-015","f-b01-c019-013","f-b01-c019-029","f-b01-c019-031","f-b01-c019-030"],"from":19,"heading":"Healing and the attack account","kind":"story","tokens":[{"text":"Vesli’s cleaned head wound is a ragged gash from forehead along the crown, with a chewed appearance. She confirms she stitched Spert’s wound and gives him water. She cleans Orka’s wounds and applies a substance after spitting; Orka feels less pain. Vesli’s spit congeals into tendon-like strings when kneaded. She claims Orka will heal faster."}]},{"refs":["f-b01-c019-016","f-b01-c019-021","f-b01-c019-020","f-b01-c019-022","f-b01-c019-026","f-b01-c019-024","f-b01-c019-023","f-b01-c019-027","f-b01-c019-028"],"from":19,"heading":"Healing and the attack account","kind":"story","tokens":[{"text":"Vesli reports humans and vaesen entering over the wall, including skraeling and oathless tennúr. She says a human-like, red-eyed attacker with two long claws fought Thorkel, agreeing with Orka’s suggested Tainted classification. She says she fought tennúr trying to take Breca and next remembers Orka carrying her outside."}]},{"refs":["f-b01-c019-032","f-b01-c019-042","f-b01-c019-058","f-b01-c019-059"],"from":19,"heading":"Healing and the attack account","kind":"story","tokens":[{"text":"Orka releases Vesli and Spert from their oaths. Vesli helps with Thorkel’s burial and offers to accompany Orka, who instead tells her to stay and help Spert."}]},{"refs":["f-b01-c051-018","f-b01-c051-020"],"from":51,"heading":"Healing and the attack account","kind":"story","tokens":[{"text":"She reaches Orka in Grimholt’s tower with Spert and the giant ravens, flying among the guards and attacking with Breca’s spear."}]},{"refs":["f-b01-c053-009","f-b01-c053-010"],"from":53,"heading":"Healing and the attack account","kind":"story","tokens":[{"text":"At the Bloodsworn’s arrival she sits near Orka on the steps with a half-spear and eats human teeth."}]}],"images":[{"file":"assets/cf278bd7678aa1.jpg","from":21,"role":"primary","spoiler":false}],"curated":false},{"id":"e-029","file":"e-029.html","source":"lore/Akáll","category":"lore","from":2,"names":[{"from":2,"text":"Akáll"}],"featured":false,"blocks":[{"refs":["f-b01-c002-083"],"from":2,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-021"},{"text":" glosses akáll as an invocation."}]},{"refs":["f-b01-c002-082","f-b01-c002-095"],"from":2,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-014"},{"text":"asks for the Seiðr-witch to perform one. Svik says "},{"page":"e-020"},{"text":" is not for hire."}]},{"refs":["f-b01-c016-030","f-b01-c016-029","f-b01-c016-028","f-b01-c016-031"],"from":16,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C016, Vol describes the akáll as reliving the last moments of a life, and calls it no simple task. Varg directly asks her to perform one, but Glornir refuses before she finishes explaining the requirements."}]},{"refs":["f-b01-c034-018","f-b01-c034-019"],"from":34,"heading":"Story and connections","kind":"story","tokens":[{"text":"Glornir again refuses Varg's akáll request and orders him not to ask again. Frustrated by Glornir's refusal, Varg considers Skalk as someone who could perform the akáll."}]},{"refs":["f-b01-c045-024","f-b01-c045-025","f-b01-c045-029"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vol says she needs a link to Frøya to attempt Varg’s akáll, but leaves permission to Glornir. Skalk later offers to perform it in exchange for Varg’s oath; the invocation remains unperformed here."}]}],"images":[],"curated":false},{"id":"e-040","file":"e-040.html","source":"lore/Althing","category":"lore","from":3,"names":[{"from":3,"text":"Althing"}],"featured":false,"blocks":[{"refs":["f-b01-c003-049","f-b01-c003-050","f-b01-c003-051"],"from":3,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-033"},{"text":"announces an Althing after "},{"page":"e-032"},{"text":"returns. It is to be held on the "},{"page":"e-037"},{"text":". He says everyone can speak about the matters under discussion."}]},{"refs":["f-b01-c003-043"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"He has promoted swearing oaths to "},{"page":"e-018"},{"text":". See "},{"text":"the unresolved political decision"},{"text":"."}]},{"refs":["f-b01-c008-027","f-b01-c008-028","f-b01-c008-029"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"Guðvarr announces an Althing at the Oath Rock six days hence. He says Sigrún wants all her subjects present. Arild says they must attend or live elsewhere."}]}],"images":[],"curated":false},{"id":"e-152","file":"e-152.html","source":"lore/Battle spoils","category":"lore","from":20,"names":[{"from":20,"text":"Battle spoils"}],"featured":false,"blocks":[{"refs":["f-b01-c020-038","f-b01-c020-039","f-b01-c020-042"],"from":20,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Sulich describes a defeated opponent’s gear as the victor’s battle spoils, telling the tale of victory and battle-fame. Svik says taking another warrior’s kill is stealing and dishonourable."}]},{"refs":["f-b01-c020-040","f-b01-c020-037","f-b01-c020-043"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"After the dockside battle, Bloodsworn loot fallen druzhina and allow a druzhina to take a fallen Bloodsworn’s equipment. Varg initially refuses, then helps Svik strip his own opponent’s gear. These observations establish the practice in this scene, not a universal rule for all cultures."}]},{"refs":["f-b01-c047-023"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"Røkia gives Varg the slain red-eyed swordsman’s mail and helm as spoils earned by his blood and courage."}]}],"images":[],"curated":false},{"id":"e-079","file":"e-079.html","source":"lore/Berserkir","category":"lore","from":7,"names":[{"from":7,"text":"Berserkir"}],"featured":false,"blocks":[{"refs":["f-b01-c007-043","f-b01-c007-042"],"from":7,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Agnar calls the captive Tainted and Berserkir. He claims the dead god Berser’s blood flows in the man’s veins."}]},{"refs":["f-b01-c007-034","f-b01-c007-035","f-b01-c007-036","f-b01-c007-040"],"from":7,"heading":"Story and connections","kind":"story","tokens":[{"text":"The captive’s eyes, teeth and nails change under threat to the boy."}]},{"refs":["f-b01-c021-050","f-b01-c021-045","f-b01-c021-044","f-b01-c021-059","f-b01-c021-060"],"from":21,"heading":"Story and connections","kind":"story","tokens":[{"text":"Störr’s collared guards are identified as Berserkirs; they wear iron bear-claw pendants and carry axes. After tasting Berak’s blood, Hrung declares it Berser’s blood. The test is observed, while the lineage result remains Hrung’s pronouncement."}]},{"refs":["f-b01-c047-002","f-b01-c047-004"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"Svik identifies Glornir as Berserkir in chapter 47, during the chief’s violent grief over Vol’s abduction."}]}],"images":[],"curated":false},{"id":"e-081","file":"e-081.html","source":"lore/Blood oaths","category":"lore","from":8,"names":[{"from":8,"text":"Blood oaths"}],"featured":false,"blocks":[{"refs":["f-b01-c008-014"],"from":8,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Spert demands a blood oath, saying blood is binding."}]},{"refs":["f-b01-c008-015","f-b01-c008-016"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"Vesli cuts her palm and swears on her life-blood to be faithful to Breca and his guardian."}]},{"refs":["f-b01-c008-020"],"from":8,"heading":"Story and connections","kind":"story","tokens":[{"text":"Thorkel says she owes Breca a blood-debt if she survives."}]},{"refs":["f-b01-c019-032"],"from":19,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C019, Orka tells Vesli and Spert they are free of their oaths, saying both have earned their freedom. This records her release declaration without establishing a universal mechanism for ending blood oaths."}]},{"refs":["f-b01-c029-017","f-b01-c029-018","f-b01-c029-021","f-b01-c029-022","f-b01-c029-023"],"from":29,"heading":"Story and connections","kind":"story","tokens":[{"text":"Kráka describes the blóð svarið as a binding made with blood, runes and words of power, with death for breaking it. Uspa claims breaking the oath before death makes the oathbreaker's blood boil. Uspa carves four runes into a chopping board and identifies them as life, death, blood oath and torment. Uspa, Elvar, Grend, Agnar, Sighvat and Kráka mingle blood over the carved runes. The ritual blood rises, forms runes in the air and merges into a hot cord binding the participants' hands and wrists."}]},{"refs":["f-b01-c032-016","f-b01-c032-017"],"from":32,"heading":"Story and connections","kind":"story","tokens":[{"text":"Agnar publicly promises to recover Uspa's son or die trying. Agnar tells even the unmarked crew they are bound by the oath if they follow him; no new magical binding is demonstrated."}]}],"images":[],"curated":false},{"id":"e-126","file":"e-126.html","source":"lore/Dragon-born","category":"lore","from":14,"names":[{"from":14,"text":"Dragon-born"}],"featured":false,"blocks":[{"refs":["f-b01-c014-025","f-b01-c014-027","f-b01-c014-028"],"from":14,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Elvar says she has never seen a dragon-born or heard a trusted report. Agnar argues that lack of sightings does not prove absence and hopes they exist."}]},{"refs":["f-b01-c017-023","f-b01-c017-019"],"from":17,"heading":"Early uncertainty","kind":"story","tokens":[{"text":"In B01-C017, the dying Thorkel utters “Dragon-born” after reporting Breca’s abduction. The utterance does not identify a person, explain what he witnessed or independently establish any individual’s ancestry. See "},{"text":"the meaning of Thorkel’s utterance"},{"text":"."}]},{"refs":["f-b01-c050-014","f-b01-c050-018","f-b01-c050-019"],"from":50,"heading":"Early uncertainty","kind":"story","tokens":[{"text":"The early doubts are overtaken in chapter 50 by Skrið’s red eyes and sudden speed in the duel, followed by Vörn’s explicit identification of dragon-born blood. Elvar extends that identification to Ilska, Drekr and the mounted companions; this broader statement is her conclusion."}]}],"images":[],"curated":false},{"id":"e-088","file":"e-088.html","source":"lore/Galdur-tongue","category":"lore","from":9,"names":[{"from":9,"text":"Galdur-tongue"}],"featured":false,"blocks":[{"refs":["f-b01-c009-038"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The narrator identifies Agnar’s command Hlýða og fá verðlaun as Galdur-tongue."}]},{"refs":["f-b01-c009-039"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Red veins trace Kráka’s collar as he speaks."}]},{"refs":["f-b01-c028-016","f-b01-c028-018","f-b01-c028-019"],"from":28,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka wounds the Näcken with her seax while speaking 'Járn og stál, skorið og brennt'. Orka's next blade strike bounces off the Näcken's wrist when she does not accompany it with spoken words. Orka wounds the Näcken's mouth and shoulder while speaking 'Skörp járn brenna og bíta'."}]},{"refs":["f-b01-c039-018"],"from":39,"heading":"Story and connections","kind":"story","tokens":[{"text":"Skalk explains that Galdur-tongue commands control collars containing remnants of Ulfrir's chain, and Glornir agrees with his account."}]}],"images":[],"curated":false},{"id":"e-123","file":"e-123.html","source":"lore/Gallows Wood","category":"lore","from":14,"names":[{"from":14,"text":"Gallows Wood"}],"featured":false,"blocks":[{"refs":["f-b01-c014-014"],"from":14,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Elvar identifies a scene on the oath stone as the Gallows Wood."}]},{"refs":["f-b01-c014-015","f-b01-c014-016","f-b01-c014-017"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"In her recalled tale, Lik-Rifa murdered Orna and Ulfrir’s daughter; they slaughtered Lik-Rifa’s offspring in vengeance. The mutilation is called the blood-eagle."}]},{"refs":["f-b01-c048-001","f-b01-c048-002","f-b01-c048-003"],"from":48,"heading":"Story and connections","kind":"story","tokens":[{"text":"The Battle-Grim encounter hundreds of desiccated hanging bodies with blood-eagled backs. Uspa identifies the forest as the Gallows Wood; the identification of the dead as dragon-born remains part of Elvar’s recalled saga."}]}],"images":[],"curated":false},{"id":"e-192","file":"e-192.html","source":"lore/Gröfu","category":"lore","from":47,"names":[{"from":47,"text":"Gröfu"}],"featured":false,"blocks":[{"refs":["f-b01-c047-017"],"from":47,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Jökul identifies Gröfu as the badger from whom he is descended."}]}],"images":[],"curated":false},{"id":"e-101","file":"e-101.html","source":"lore/Holmganga","category":"lore","from":10,"names":[{"from":10,"text":"Holmganga"}],"featured":false,"blocks":[{"refs":["f-b01-c010-038","f-b01-c010-039"],"from":10,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Guðvarr challenges Virk and Virk accepts."}]},{"refs":["f-b01-c010-040","f-b01-c010-047"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Sigrún orders seconds chosen and hazel rods laid. Guðvarr says his public challenge cannot be withdrawn."}]},{"refs":["f-b01-c010-041","f-b01-c010-042","f-b01-c010-044"],"from":10,"heading":"Story and connections","kind":"story","tokens":[{"text":"Virk asks Orka to be his second and keep his sons from fighting if he loses. She accepts."}]},{"refs":["f-b01-c012-002","f-b01-c012-003"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka calls it a ritual dispute-settling duel barring weregild or blood feud by the loser’s kin."}]},{"refs":["f-b01-c012-004","f-b01-c012-005"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"She says one foot beyond the hazel rods yields and two feet count as flight. A broken shield can be replaced in a pause."}]},{"refs":["f-b01-c012-007","f-b01-c012-008","f-b01-c012-029"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"Virk and Guðvarr agree to submission. Sigrún later rules Virk broke the duel by attempting a death-wound after submission."}]}],"images":[],"curated":false},{"id":"e-122","file":"e-122.html","source":"lore/Hundur","category":"lore","from":14,"names":[{"from":14,"text":"Hundur"}],"featured":false,"blocks":[{"refs":["f-b01-c014-041"],"from":14,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The oath stone images depict Hundur as a hound."}]},{"refs":["f-b01-c014-043"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Elvar claims the Hundur-thrall has Hundur’s blood."}]},{"refs":["f-b01-c047-010"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"Edel declares Hundur ancestry and says she detected wolf ancestry by smelling Varg’s spilled blood at his Liga trial."}]}],"images":[],"curated":false},{"id":"e-048","file":"e-048.html","source":"lore/Lik-Rifa","category":"lore","from":9,"names":[{"from":4,"text":"Lik-Rifa"}],"featured":false,"blocks":[{"refs":["f-b01-c009-048","f-b01-c009-011"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Elvar calls Lik-Rifa a dragon-god. Grend calls Snaka her father."}]},{"refs":["f-b01-c009-009","f-b01-c009-010","f-b01-c009-012"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Grend says she survived Guðfalla and was trapped beneath Oskutreð. He says souls must fight her in Vergelmir."}]},{"refs":["f-b01-c009-008","f-b01-c009-014"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"Elvar doubts she lives and rejects the tremor as proof of a dragon-god."}]},{"refs":["f-b01-c013-026"],"from":13,"heading":"Story and connections","kind":"story","tokens":[{"text":"Galinn’s saga describes Lik-Rifa chained in a deep chamber beneath Oskutreð."}]},{"refs":["f-b01-c014-021","f-b01-c014-022","f-b01-c014-023"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa says Lik-Rifa’s paranoia was fuelled by Rotta and that she secretly created the vaesen. She says Orna and her siblings trapped the dragon beneath Oskutreð."}]},{"refs":["f-b01-c046-006","f-b01-c046-007","f-b01-c046-008","f-b01-c046-009","f-b01-c046-010","f-b01-c046-011","f-b01-c046-016"],"from":46,"heading":"Story and connections","kind":"story","tokens":[{"text":"In the highlands Orka finds a fresh blood-coated, fanged and winged carving on a shattered oath stone beneath a slain eagle. She identifies it as worship of Lik-Rifa. Its makers and any connection to Breca’s abduction remain unknown."}]},{"refs":["f-b01-c048-027","f-b01-c048-028"],"from":48,"heading":"Story and connections","kind":"story","tokens":[{"text":"At Oskutreð Vörn confirms Kráka’s assertion that the dragon is still imprisoned beneath the roots and names the three sisters as her gaolers."}]},{"refs":["f-b01-c052-021","f-b01-c052-022","f-b01-c052-023","f-b01-c052-024","f-b01-c052-026","f-b01-c052-027","f-b01-c052-028"],"from":52,"heading":"Chapter 52 — The revealed dragon","kind":"story","tokens":[{"text":"Chapter 52 directly establishes her survival and release: Ilska’s blood rite opens the door and the dragon emerges. She is emaciated and partly rotten, with pallid scales, feverish red eyes, tattered wings and corpses snagged on her body."}]},{"refs":["f-b01-c052-047","f-b01-c052-048","f-b01-c052-049"],"from":52,"heading":"Chapter 52 — The revealed dragon","kind":"story","tokens":[{"text":"Her jaws have teeth longer than spears and rows of pale curling horns crown her head. She has a razored tail, and her immense size is compared to twice Snakavik's mead hall."}]},{"refs":["f-b01-c052-029","f-b01-c052-030","f-b01-c052-032","f-b01-c052-034","f-b01-c052-035","f-b01-c052-036","f-b01-c052-039","f-b01-c052-041"],"from":52,"heading":"Humanoid form and departure","kind":"story","tokens":[{"text":"She battles the winged gaolers and kills the white-winged woman. After her followers kneel, she calls them her children and assumes a towering human shape with injured pale skin, black silver-streaked hair and red eyes. She then returns to dragon form and flies south."}]},{"refs":["f-b01-c052-050","f-b01-c052-051","f-b01-c052-036"],"from":52,"heading":"Humanoid form and departure","kind":"story","tokens":[{"text":"Her humanoid frame is lean and striated, taller than any man and compared in size to the bull troll. Her face is described as sharply beautiful. She wears a grey tunic with red-woven neck and hem, a gold-studded belt and a dark cloak."}]},{"refs":["f-b01-c052-038"],"from":52,"heading":"Humanoid form and departure","kind":"story","tokens":[{"text":"She says she wants to return to her hall Nastrandir and hunt after centuries eating corpses in captivity. These durations and her intentions remain her testimony."}]}],"images":[{"file":"assets/bdf06a4d4f38b1.jpg","from":53,"role":"secondary","spoiler":true},{"file":"assets/f69526aa99599c.jpg","from":53,"role":"secondary","spoiler":true}],"curated":false},{"id":"e-100","file":"e-100.html","source":"lore/Orna","category":"lore","from":13,"names":[{"from":10,"text":"Orna"}],"featured":false,"blocks":[{"refs":["f-b01-c013-019","f-b01-c013-050"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Galinn’s song describes Orna as eagle-winged. It says Orna was torn."}]},{"refs":["f-b01-c031-008"],"from":31,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka identifies the skeleton as Orna's remains and believes it keeps vaesen away for many leagues."}]}],"images":[],"curated":false},{"id":"e-084","file":"e-084.html","source":"lore/Oskutreð","category":"lore","from":9,"names":[{"from":9,"text":"Oskutreð"}],"featured":false,"blocks":[{"refs":["f-b01-c009-010"],"from":9,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Grend says Lik-Rifa was trapped beneath Oskutreð, the Ash Tree."}]},{"refs":["f-b01-c015-061","f-b01-c015-060","f-b01-c015-052","f-b01-c015-053"],"from":15,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C015, the narrator describes it as the great tree that stood at the heart of Vigrið during the gods-fall. The "},{"page":"e-127"},{"text":"is described as born from one of its seeds. Her "},{"page":"e-128"},{"text":" has its own location and destruction account."}]},{"refs":["f-b01-c027-027"],"from":27,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa claims to know the way to Oskutreð; Elvar overhears the whispered disclosure."}]},{"refs":["f-b01-c029-005","f-b01-c029-012","f-b01-c029-016"],"from":29,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa confirms Elvar's account that Oskutreð lies beyond the vaesen pit, Isbrún Bridge and Dark-of-Moon Hills. Uspa says she burned the book to prevent treasure-seekers finding god-remains and provoking new powers and war. Uspa agrees to guide the group to Oskutreð first if all present swear the blóð svarið."}]},{"refs":["f-b01-c048-006","f-b01-c048-007","f-b01-c048-008","f-b01-c048-010","f-b01-c048-014","f-b01-c048-015","f-b01-c048-018","f-b01-c048-022"],"from":48,"heading":"Chapter 48 — The stump and guardian","kind":"story","tokens":[{"text":"In chapter 48 Uspa leads the Battle-Grim to its immense blackened stump on an ash-covered battlefield. A living ash grows beside a huge bolted trapdoor that trembles rhythmically. Vörn emerges from the living tree and prohibits touching the old stump."}]},{"refs":["f-b01-c048-036"],"from":48,"heading":"Chapter 48 — The stump and guardian","kind":"story","tokens":[{"text":"The stump is wide as a lake, but its jagged remains stand only perhaps two men high."}]},{"refs":["f-b01-c048-023","f-b01-c048-024","f-b01-c048-025"],"from":48,"heading":"Chapter 48 — The stump and guardian","kind":"story","tokens":[{"text":"When Sighvat attacks her, she disarms him, strikes him down and binds him with vines rising from the ash-covered ground."}]},{"refs":["f-b01-c052-015","f-b01-c052-016","f-b01-c052-017","f-b01-c052-018","f-b01-c052-019","f-b01-c052-021","f-b01-c052-022","f-b01-c052-023","f-b01-c052-024","f-b01-c052-026"],"from":52,"heading":"Chapter 52 — The ritual at the sealed door","kind":"story","tokens":[{"text":"Ilska’s followers use a red-hide book, collared children and spilled blood in a rite at the sealed door. It bursts open, freeing Lik-Rifa and scattering combatants. The living guardian’s defence is overcome before the release."}]}],"images":[{"file":"assets/9556c706ab833e.jpg","from":53,"role":"scene","spoiler":true},{"file":"assets/7d9135d98b7946.jpg","from":53,"role":"primary","spoiler":true},{"file":"assets/eb790d69f84ecc.jpg","from":53,"role":"scene","spoiler":true}],"curated":false},{"id":"e-191","file":"e-191.html","source":"lore/Refur","category":"lore","from":47,"names":[{"from":47,"text":"Refur"}],"featured":false,"blocks":[{"refs":["f-b01-c047-005","f-b01-c047-006","f-b01-c047-007"],"from":47,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Svik identifies Refur as the fox whose blood lives on in him. His associated demonstration changes his eyes, teeth and facial angles before he reverses it."}]}],"images":[],"curated":false},{"id":"e-112","file":"e-112.html","source":"lore/Rotta","category":"lore","from":45,"names":[{"from":13,"text":"Rotta"}],"featured":false,"blocks":[{"refs":["f-b01-c045-006","f-b01-c045-007","f-b01-c045-008"],"from":45,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Varg recalls saga-tales describing Rotta inflaming Orna and Lik-Rifa’s feud and Orna imprisoning him beneath Frang’s Falls with enchanted venomous serpents. Torvik reports Vol’s belief that the excavated catacomb is Rotta’s chamber; that identification is not independent proof of the saga."}]}],"images":[],"curated":false},{"id":"e-104","file":"e-104.html","source":"lore/Shield work","category":"lore","from":11,"names":[{"from":11,"text":"Shield work"}],"featured":false,"blocks":[{"refs":["f-b01-c011-025"],"from":11,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Røkia teaches Varg to hold a gap between shield and torso against penetrating strikes."}]},{"refs":["f-b01-c011-026","f-b01-c011-029"],"from":11,"heading":"Story and connections","kind":"story","tokens":[{"text":"She says a shield is also a weapon and warns him not to lose sight of an opponent."}]},{"refs":["f-b01-c026-009","f-b01-c026-010"],"from":26,"heading":"Story and connections","kind":"story","tokens":[{"text":"Røkia teaches Varg to use the shield's boss and rim as weapons. The overhand spear grip gives Varg longer reach but is weaker than the reverse grip in his training."}]}],"images":[],"curated":false},{"id":"e-008","file":"e-008.html","source":"lore/Snaka","category":"lore","from":1,"names":[{"from":1,"text":"Snaka"}],"featured":false,"blocks":[{"refs":["f-b01-c001-033"],"from":1,"heading":"Story and connections","kind":"introduction","tokens":[{"page":"e-003"},{"text":" calls Snaka a serpent."}]},{"refs":["f-b01-c001-034","f-b01-c001-035","f-b01-c001-036"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"In "},{"page":"e-002"},{"text":"’s tale, Snaka is the father of the gods. He is called Eldest. Thorkel names Eagle, Bear, Wolf and Dragon among his children."}]},{"refs":["f-b01-c001-037","f-b01-c001-038","f-b01-c001-039"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"text":"According to that tale, Snaka is slain by his children. His death shatters the world. The distant mountains are his bones covered with earth."}]},{"refs":["f-b01-c001-040","f-b01-c001-041"],"from":1,"heading":"Story and connections","kind":"story","tokens":[{"page":"e-001"},{"text":" says Snaka’s fall opened the vaesen pit. She says creatures from the world below were released into their land."}]},{"refs":["f-b01-c021-002","f-b01-c021-004","f-b01-c021-005","f-b01-c021-006","f-b01-c021-007"],"from":21,"heading":"Snakavik and the Boneback Mountains","kind":"story","tokens":[{"text":"In B01-C021 the narration identifies the colossal skull at Snakavik as Snaka’s and describes his fall there on Guðfalla. It describes the broken ground admitting the sea to form the fjord and earth settling around his body to create the continental mountain range. His skull, spine and ribs remain after the flesh rotted."}]}],"images":[],"curated":false},{"id":"e-195","file":"e-195.html","source":"lore/Three sisters","category":"lore","from":48,"names":[{"from":48,"text":"Three sisters"}],"featured":false,"blocks":[{"refs":["f-b01-c048-028"],"from":48,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Vörn names Urd, Verdani and Skuld as daughters of Orna and Ulfrir and gaolers of Lik-Rifa beneath Oskutreð. This chapter supplies her account, before the sisters are encountered."}]},{"refs":["f-b01-c052-025","f-b01-c052-029","f-b01-c052-030","f-b01-c052-031","f-b01-c052-032"],"from":52,"heading":"Story and connections","kind":"story","tokens":[{"text":"Three winged women emerge during Lik-Rifa’s escape: a red-haired rust-winged warrior thrown clear, a golden-winged spear fighter and a white-winged archer. Ilska cuts down the golden-winged woman and the dragon kills the white-winged one. The individual names are not assigned to these appearances in chapter 52."}]}],"images":[],"curated":false},{"id":"e-105","file":"e-105.html","source":"lore/Ulfrir-kin","category":"lore","from":12,"names":[{"from":12,"text":"Ulfrir-kin"}],"featured":false,"blocks":[{"refs":["f-b01-c012-019"],"from":12,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Thorkel addresses Sigrún’s warrior-thrall as Ulfrir-kin."}]},{"refs":["f-b01-c012-015","f-b01-c012-036","f-b01-c012-025","f-b01-c012-037"],"from":12,"heading":"Story and connections","kind":"story","tokens":[{"text":"The thrall’s eyes turn amber and her teeth become sharp during her attack. The changes fade during Sigrún’s collar commands."}]}],"images":[],"curated":false},{"id":"e-109","file":"e-109.html","source":"lore/Ulfrir","category":"lore","from":13,"names":[{"from":13,"text":"Ulfrir"}],"featured":false,"blocks":[{"refs":["f-b01-c013-018","f-b01-c013-025"],"from":13,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Galinn’s song calls Ulfrir wolf-waking and breaker of chains. The song says he was slain."}]},{"refs":["f-b01-c020-029"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"Svik says Helka’s Úlfhéðnar bodyguards are descended from Ulfrir, whom he calls the wolf-god. This remains an attributed ancestry claim."}]},{"refs":["f-b01-c048-012","f-b01-c048-013"],"from":48,"heading":"Story and connections","kind":"story","tokens":[{"text":"At Oskutreð Elvar identifies an enormous wolf skeleton as Ulfrir. Grend tentatively identifies nearby broken iron as a link of the wolf’s chain; these are their interpretations of the finds."}]}],"images":[],"curated":false},{"id":"e-050","file":"e-050.html","source":"lore/Weregild","category":"lore","from":4,"names":[{"from":4,"text":"Weregild"}],"featured":false,"blocks":[{"refs":["f-b01-c004-094","f-b01-c004-066"],"from":4,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Leif invokes a right of weregild when claiming Varg as his thrall. He accuses Varg of butchering his father."}]},{"refs":["f-b01-c004-068","f-b01-c004-095"],"from":4,"heading":"Story and connections","kind":"story","tokens":[{"text":"Varg asserts that he earned his freedom. The grey-bearded rescuer declares Varg one of the Bloodsworn. See "},{"text":"the conflicting freedom and ownership claims"},{"text":"."}]}],"images":[],"curated":false},{"id":"e-130","file":"e-130.html","source":"lore/Úlfhéðnar","category":"lore","from":15,"names":[{"from":15,"text":"Úlfhéðnar"}],"featured":false,"blocks":[{"refs":["f-b01-c015-035","f-b01-c015-039"],"from":15,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Thorkel identifies "},{"page":"e-095"},{"text":" as Úlfhéðnar. He argues she is not Hundur and that tasting blood would mean nothing to her."}]},{"refs":["f-b01-c020-029","f-b01-c020-010","f-b01-c020-012"],"from":20,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C020, Svik identifies Helka’s collared bodyguards as Úlfhéðnar, Tainted thralls descended from Ulfrir. Their collars and coordinated movement are observed, while their ancestry remains his account."}]},{"refs":["f-b01-c031-013","f-b01-c031-014"],"from":31,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka identifies the disembarking warriors as Úlfhéðnar descended from Ulfrir. The arriving warriors wear mail and have shaved, tattooed sides to their heads."}]},{"refs":["f-b01-c047-011","f-b01-c047-012"],"from":47,"heading":"Story and connections","kind":"story","tokens":[{"text":"Røkia identifies herself and Varg as Úlfhéðnar in chapter 47, revealing their Ulfrir ancestry at this point in reading chronology. She connects Varg’s red-mist strength and speed to it."}]}],"images":[],"curated":false},{"id":"e-189","file":"e-189.html","source":"artifacts/Bone sword at the excavation","category":"artifacts","from":43,"names":[{"from":43,"text":"Bone sword at the excavation"}],"featured":false,"blocks":[{"refs":["f-b01-c043-014","f-b01-c043-015","f-b01-c043-017","f-b01-c043-018","f-b01-c043-026","f-b01-c043-028"],"from":43,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The unnamed red-eyed man's two-handed sword is curved and yellowed with grey veins like old bone. Varg perceives power, pressure and pain emanating from it. It hurls Glornir back in a weapon clash, cuts a thrown spear apart and eventually breaches Vol's Seiðr-rune. Its origin and precise nature are not established."}]},{"refs":["f-b01-c045-005","f-b01-c045-030","f-b01-c045-031"],"from":45,"heading":"Story and connections","kind":"story","tokens":[{"text":"Torvik identifies this weapon as a talon of the eagle-god Orna. Yrsa later retrieves it in a chest; Varg senses power from the opened chest. The identification is attributed to Torvik at this stage."}]}],"images":[],"curated":false},{"id":"e-039","file":"e-039.html","source":"artifacts/Fellur gate knuckle-bone","category":"artifacts","from":3,"names":[{"from":3,"text":"Fellur gate knuckle-bone"}],"featured":false,"blocks":[{"refs":["f-b01-c003-018","f-b01-c003-019","f-b01-c003-020"],"from":3,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"A dead god’s knuckle-bone is embedded in "},{"page":"e-007"},{"text":"’s gate crossbar. It retains a remnant of power. It helps keep vaesen out of the village."}]},{"refs":["f-b01-c003-021","f-b01-c003-022"],"from":3,"heading":"Story and connections","kind":"story","tokens":[{"text":"While passing the gate, "},{"page":"e-001"},{"text":"feels pressure in her head and chest. The pressure in her head lessens away from the gate. See "},{"text":"her unexplained reaction"},{"text":"."}]}],"images":[],"curated":false},{"id":"e-120","file":"e-120.html","source":"artifacts/Frost-Isles oath stone","category":"artifacts","from":14,"names":[{"from":14,"text":"Frost-Isles oath stone"}],"featured":false,"blocks":[{"refs":["f-b01-c014-004","f-b01-c014-047"],"from":14,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Kráka identifies the granite slab as an oath stone. The narrator also calls it an oath stone."}]},{"refs":["f-b01-c014-009","f-b01-c014-010"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Uspa presses her bloody palm to it and glowing lines burn away the moss."}]},{"refs":["f-b01-c014-011","f-b01-c014-018","f-b01-c014-040","f-b01-c014-041","f-b01-c014-042"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"It reveals images of a caged dragon, a bound wolf, and the gods in animal forms. The images are depictions, not independent confirmation of the tales."}]},{"refs":["f-b01-c014-038"],"from":14,"heading":"Story and connections","kind":"story","tokens":[{"text":"Elvar wonders whether the stone attracted the night-wyrms."}]}],"images":[],"curated":false},{"id":"e-169","file":"e-169.html","source":"artifacts/Graskinna","category":"artifacts","from":29,"names":[{"from":29,"text":"Graskinna"}],"featured":false,"blocks":[{"refs":["f-b01-c029-007","f-b01-c029-008","f-b01-c029-010"],"from":29,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Uspa calls the Graskinna or Grey Skin a Galdrabok of dark magic that gives the way to Oskutreð to those who understand it. Uspa says she destroyed the Graskinna in the fire pool on Iskalt while Berak fought the troll. Uspa says she and Berak stole the Graskinna from the Raven-Feeders, who have hunted them for a long time."}]},{"refs":["f-b01-c044-006"],"from":44,"heading":"Story and connections","kind":"story","tokens":[{"text":"When asked for a precise remaining distance, Uspa describes the Graskinna as a Galdrabok rather than a map."}]}],"images":[],"curated":false},{"id":"e-144","file":"e-144.html","source":"artifacts/Orka’s buried chest","category":"artifacts","from":19,"names":[{"from":19,"text":"Orka’s buried chest"}],"featured":false,"blocks":[{"refs":["f-b01-c019-035","f-b01-c019-038","f-b01-c019-039","f-b01-c019-045","f-b01-c019-048"],"from":19,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Orka digs up this wooden chest near the western tip of her ruined hall. It contains a walrus-ivory-hilted seax in a polished knotworked scabbard, silver and gold arm rings, mail and coin."}]},{"refs":["f-b01-c019-045","f-b01-c019-046","f-b01-c019-047","f-b01-c019-036"],"from":19,"heading":"Story and connections","kind":"story","tokens":[{"text":"The mail has been buried for more than ten years, protected from rust by grease and lack of air. Orka puts it on; its hem hangs just above her knees. The chest evokes memories of her past battles, friends and enemies."}]}],"images":[],"curated":false},{"id":"e-190","file":"e-190.html","source":"artifacts/Raudskinna","category":"artifacts","from":45,"names":[{"from":45,"text":"Raudskinna"}],"featured":false,"blocks":[{"refs":["f-b01-c045-009","f-b01-c045-010"],"from":45,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Torvik cites saga-tales placing Rotta’s Galdrabok in his chamber and describing it as rune-carved on the bloodied skin of Orna’s daughter. The remembered account credits it with knowledge of life and death and spells used to sustain Rotta’s torment. No discovery of the Raudskinna is shown in chapter 45."}]}],"images":[],"curated":false},{"id":"e-145","file":"e-145.html","source":"artifacts/Seaxes that killed Thorkel","category":"artifacts","from":19,"names":[{"from":17,"text":"Seaxes that killed Thorkel"}],"featured":false,"blocks":[{"refs":["f-b01-c017-016","f-b01-c019-040"],"from":19,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The pair is first observed embedded in Thorkel’s chest and belly in B01-C017. Orka removes them before burying him."}]},{"refs":["f-b01-c019-052","f-b01-c019-053"],"from":19,"heading":"Story and connections","kind":"story","tokens":[{"text":"They are forearm-length, wide and single-edged, tapering abruptly towards their tips. Their ash hilts bear knotwork, brass end-caps and leather-threaded pins."}]},{"refs":["f-b01-c019-060","f-b01-c019-061","f-b01-c019-024","f-b01-c019-025"],"from":19,"heading":"Story and connections","kind":"story","tokens":[{"text":"Orka carries both in her belt and says she will find their owner and give them back to him. Vesli’s report of an attacker with two long claws prompts Orka to wonder about these blades, but their owner is not identified."}]},{"refs":["f-b01-c022-029"],"from":22,"heading":"Story and connections","kind":"story","tokens":[{"text":"During the chamber fight in B01-C022, Orka draws one of the blades she removed from Thorkel’s body."}]}],"images":[],"curated":false},{"id":"e-182","file":"e-182.html","source":"artifacts/Thrall-collars","category":"artifacts","from":39,"names":[{"from":39,"text":"Thrall-collars"}],"featured":false,"blocks":[{"refs":["f-b01-c039-016","f-b01-c039-018","f-b01-c039-019"],"from":39,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Skalk says thrall-collars are forged from iron mixed with recovered fragments of "},{"page":"e-183"},{"text":" using Galdur-magic. He identifies Vol's collar as one such restraint, controlled by Galdur-tongue words; Glornir agrees. Skalk says the system also controls Helka's Úlfhéðnar and Störr's Berserkir."}]}],"images":[],"curated":false},{"id":"e-183","file":"e-183.html","source":"artifacts/Ulfrir’s chain","category":"artifacts","from":39,"names":[{"from":39,"text":"Ulfrir’s chain"}],"featured":false,"blocks":[{"refs":["f-b01-c039-014","f-b01-c039-015","f-b01-c039-016","f-b01-c039-017"],"from":39,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Yrsa recounts that Lik-Rifa enchanted the chain to bind Ulfrir before her followers killed him, and that Snaka's fall scattered its fragments. Skalk says the recovered metal was used to make "},{"page":"e-182"},{"text":", and that fortresses grew where fragments were found. These origins remain attributed historical accounts."}]},{"refs":["f-b01-c048-013"],"from":48,"heading":"Story and connections","kind":"story","tokens":[{"text":"Near the giant wolf skeleton Grend wonders whether a broken iron fragment is a link from Ulfrir’s chain. The identification remains tentative."}]}],"images":[],"curated":false},{"id":"e-132","file":"e-132.html","source":"artifacts/Unidentified rafter object","category":"artifacts","from":16,"names":[{"from":16,"text":"Unidentified rafter object"}],"featured":false,"blocks":[{"refs":["f-b01-c016-015","f-b01-c016-016"],"from":16,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Varg sees this pale, long object embedded in a rafter above the dais, describing it as resembling a sliver of bone. One end glints like silver."}]},{"refs":["f-b01-c016-013"],"from":16,"heading":"Story and connections","kind":"story","tokens":[{"text":"Varg feels new head pressure as he approaches the dais, but the object’s nature and any connection to the pressure are unestablished. See "},{"text":"the unresolved question"},{"text":"."}]},{"refs":["f-b01-c018-036","f-b01-c018-043","f-b01-c018-038","f-b01-c018-039"],"from":18,"heading":"Identification reported in B01-C018","kind":"story","tokens":[{"text":"Torvik identifies the sliver over Logur’s high seat as a fragment of the "},{"page":"e-108"},{"text":", and says Skullsplitter gave it to Logur. He credits it with helping make Logur rich. Varg remembers a strange sensation that he felt emanating from the sliver. The identification and power accounts remain attributed; the cause of Varg’s earlier head pressure has not been independently established."}]}],"images":[],"curated":false},{"id":"e-108","file":"e-108.html","source":"artifacts/Vackna Horn","category":"artifacts","from":18,"names":[{"from":13,"text":"Vackna Horn"}],"featured":false,"blocks":[{"refs":["f-b01-c013-017","f-b01-c018-037"],"from":18,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Galinn’s song names Vackna as the waking horn. Torvik says the Vackna Horn summoned the gods to the Battle-Plain on Guðfalla."}]},{"refs":["f-b01-c018-036","f-b01-c018-043"],"from":18,"heading":"Story and connections","kind":"story","tokens":[{"text":"Torvik identifies the "},{"page":"e-132"},{"text":" as a fragment of this horn, given to Logur by Skullsplitter. The claimed identity and origin are attributed accounts, not an observed historical event."}]}],"images":[],"curated":false},{"id":"e-141","file":"e-141.html","source":"ships/Sea-Wolf","category":"ships","from":18,"names":[{"from":18,"text":"Sea-Wolf"}],"featured":false,"blocks":[{"refs":["f-b01-c018-048","f-b01-c018-053","f-b01-c018-054","f-b01-c018-055","f-b01-c018-057","f-b01-c018-060"],"from":18,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"The Sea-Wolf is the Bloodsworn’s ship, moored at Liga’s docks in B01-C018. Jaromir threatens the crew’s ship while torch-bearing riders wait at the pier entrance and figures move aboard it. Glornir refuses to surrender Sulich, and the dockside confrontation turns into a battle."}]},{"refs":["f-b01-c020-047","f-b01-c020-053","f-b01-c020-054","f-b01-c020-051","f-b01-c020-060"],"from":20,"heading":"Layout and departure from Liga","kind":"story","tokens":[{"text":"Sea-chests store gear and serve as rowing seats. A shield rack runs along the top-rail, and Varg opens a shuttered oar-hole to row from his chest. Einar locks the mast in place and commands sixty oars."}]},{"refs":["f-b01-c020-065"],"from":20,"heading":"Layout and departure from Liga","kind":"story","tokens":[{"text":"The sail remains furled as the mast is raised. Its woollen fabric is directly described."}]},{"refs":["f-b01-c020-057","f-b01-c020-058","f-b01-c020-059","f-b01-c020-062","f-b01-c020-056"],"from":20,"heading":"Layout and departure from Liga","kind":"story","tokens":[{"text":"Skalk and two of Helka’s warriors join the crew for the new assignment; Glornir orders them to row. Vol stands at the prow and Glornir takes the steering oar at the stern. The ship casts off from Liga and steers south and west through the fjord. Glornir describes their work as finding and killing an unidentified problem eating Helka’s people in the north."}]}],"images":[{"file":"assets/1ee925ff73d52b.jpg","from":53,"role":"primary","spoiler":false}],"curated":false},{"id":"e-059","file":"e-059.html","source":"ships/Wave-Jarl","category":"ships","from":5,"names":[{"from":5,"text":"Wave-Jarl"}],"featured":false,"blocks":[{"refs":["f-b01-c005-005","f-b01-c005-007"],"from":5,"heading":"Story and connections","kind":"introduction","tokens":[{"text":"Agnar steers the Wave-Jarl. Kráka chants magic to keep sea vaesen away from the ship."}]},{"refs":["f-b01-c009-021","f-b01-c009-022","f-b01-c009-027","f-b01-c009-028"],"from":9,"heading":"Story and connections","kind":"story","tokens":[{"text":"A sea serpent attacks the goats beneath the awning and knocks the boy overboard. The mother’s song precedes the serpent’s withdrawal."}]},{"refs":["f-b01-c021-001","f-b01-c021-017","f-b01-c021-018"],"from":21,"heading":"Story and connections","kind":"story","tokens":[{"text":"In B01-C021, the Wave-Jarl arrives at Snakavik under half a crew of oars. Agnar pays harbour dues and leaves warriors guarding the ship while the party goes ashore."}]},{"refs":["f-b01-c032-002","f-b01-c032-004"],"from":32,"heading":"Story and connections","kind":"story","tokens":[{"text":"The Battle-Grim spend two days in Starl restocking provisions and maintaining the Wave-Jarl. The Wave-Jarl crosses Lake Horndal."}]}],"images":[],"curated":false},{"id":"book-b01","book_id":"B01","type":"book","file":"book-b01.html","category":"books","from":1,"names":[{"from":1,"text":"The Shadow of the Gods"}],"blocks":[{"refs":["f-b01-c001-001","f-b01-c001-003","f-b01-c001-031","f-b01-c001-072"],"from":1,"kind":"introduction","heading":"Introduction","tokens":[{"text":"The first book opens in Vigrið in the year 297 of Friðaröld, the Age of Peace. Orka and her family are out hunting; the world beyond them is introduced through their journey and the stories they tell. The chapter summaries below follow only as far as you have read."}]}],"summaries":[{"id":"B01-C001","from":1,"number":1,"heading":"Chapter One - Orka","blocks":[{"refs":["f-b01-c001-001","f-b01-c001-072","f-b01-c001-008","f-b01-c001-010","f-b01-c001-013","f-b01-c001-024","f-b01-c001-034","f-b01-c001-038","f-b01-c001-040","f-b01-c001-047","f-b01-c001-062","f-b01-c001-064","f-b01-c001-049","f-b01-c001-069","f-b01-c001-071"],"from":1,"heading":"Chapter One - Orka","kind":"chapter","tokens":[{"text":"A spring hunt in the year 297 of Friðaröld brings Orka, Thorkel and Breca into contact with a badly wounded fell-wolf. Screams draw them towards Asgrim's steading, while Thorkel's stories describe Snaka's death and the breaking of the world. The steading holds a more immediate horror: Asgrim is dead and Idrun has been nailed to the gate. Orka puts an axe in Asgrim's hand, and Breca asks where Harek has gone."}]}]},{"id":"B01-C002","from":2,"number":2,"heading":"Chapter Two - Varg","blocks":[{"refs":["f-b01-c002-001","f-b01-c002-004","f-b01-c002-010","f-b01-c002-014","f-b01-c002-021","f-b01-c002-022","f-b01-c002-023","f-b01-c002-039","f-b01-c002-041","f-b01-c002-049","f-b01-c002-062","f-b01-c002-082","f-b01-c002-095","f-b01-c002-086","f-b01-c002-089","f-b01-c002-090"],"from":2,"heading":"Chapter Two - Varg","kind":"chapter","tokens":[{"text":"Varg reaches Liga believing he is being pursued. Before entering, he puts an iron collar around his own neck and names Snepil as his master, although he remembers strangling him; how the killing began is missing from his memory. A trader's account of the Bloodsworn's Seiðr-witch leads him to their longhouse. Svik refuses his request for an akáll, but Varg agrees to enter the weapons trial after watching Einar demolish another challenger's shield."}]}]},{"id":"B01-C003","from":3,"number":3,"heading":"Chapter Three - Orka","blocks":[{"refs":["f-b01-c003-005","f-b01-c003-008","f-b01-c003-021","f-b01-c003-018","f-b01-c003-020","f-b01-c003-028","f-b01-c003-029","f-b01-c003-043","f-b01-c003-045","f-b01-c003-049","f-b01-c003-053","f-b01-c003-054","f-b01-c003-060","f-b01-c003-067","f-b01-c003-068","f-b01-c003-069","f-b01-c003-070","f-b01-c003-074"],"from":3,"heading":"Chapter Three - Orka","kind":"chapter","tokens":[{"text":"With Harek still missing, Thorkel follows the tracks while Orka and Breca take the bodies to Fellur. The village's protection against vaesen does not prevent a dispute over the killings: Guðvarr blames the creatures, Orka rejects his explanation and Virk reports other missing children. Their argument also exposes disagreement over Queen Helka's growing authority. Thorkel returns without finding the killers, reporting tracks to a river and signs of three boats. Orka takes her family home."}]}]},{"id":"B01-C004","from":4,"number":4,"heading":"Chapter Four - Varg","blocks":[{"refs":["f-b01-c004-010","f-b01-c004-013","f-b01-c004-028","f-b01-c004-029","f-b01-c004-033","f-b01-c004-035","f-b01-c004-036","f-b01-c004-039","f-b01-c004-043","f-b01-c004-046","f-b01-c004-048","f-b01-c004-052","f-b01-c004-053","f-b01-c004-054","f-b01-c004-062","f-b01-c004-063","f-b01-c004-070","f-b01-c004-066","f-b01-c004-080","f-b01-c004-068","f-b01-c004-071","f-b01-c004-086","f-b01-c004-089","f-b01-c004-090","f-b01-c004-095"],"from":4,"heading":"Chapter Four - Varg","kind":"chapter","tokens":[{"text":"Varg's trial against Einar ends in a gap in his awareness; he next finds himself injured outside Liga. Thoughts of his dead sister Frøya give him a reason to seek an akáll and vengeance, but Leif Kolskeggson and his men catch him at his camp. Leif accuses him of killings and claims him as a thrall. A grey-bearded warrior orders his release, backed by Einar and Svik, and declares Varg one of the Bloodsworn."}]}]},{"id":"B01-C005","from":5,"number":5,"heading":"Chapter Five - Elvar","blocks":[{"refs":["f-b01-c005-005","f-b01-c005-006","f-b01-c005-007","f-b01-c005-008","f-b01-c005-009","f-b01-c005-012","f-b01-c005-016","f-b01-c005-018","f-b01-c005-027","f-b01-c005-026","f-b01-c005-031","f-b01-c005-030","f-b01-c005-032","f-b01-c005-037","f-b01-c005-038","f-b01-c005-041","f-b01-c005-042"],"from":5,"heading":"Chapter Five - Elvar","kind":"chapter","tokens":[{"text":"The Battle-Grim land on Iskalt Island with Agnar seeking a man he calls Berak and claims is gods-touched. Elvar, the youngest of the warband, is sent after a fleeing girl as the confrontation with the villagers turns violent. Her search finds an empty hut with a hole in its rear wall; Grend follows the signs towards the trees, and Agnar orders the pursuit to continue."}]}]},{"id":"B01-C006","from":6,"number":6,"heading":"Chapter 6 - Orka","blocks":[{"refs":["f-b01-c006-001","f-b01-c006-004","f-b01-c006-013","f-b01-c006-014","f-b01-c006-015","f-b01-c006-016","f-b01-c006-018","f-b01-c006-020","f-b01-c006-023","f-b01-c006-027","f-b01-c006-028","f-b01-c006-029","f-b01-c006-030","f-b01-c006-033","f-b01-c006-035","f-b01-c006-036"],"from":6,"heading":"Chapter 6 - Orka","kind":"chapter","tokens":[{"text":"Waking from images of battle, Orka finds Breca's cot empty. Thorkel follows the boy's tracks to a pool, where he thinks he smells Näcken. Breca is holding an injured tennúr he says is named Vesli, to whom he has given a loose tooth. Orka strikes him and raises her hand again, but the creature shields him and Thorkel catches her wrist. Breca wants to keep his new companion."}]}]},{"id":"B01-C007","from":7,"number":7,"heading":"Chapter 7 - Elvar","blocks":[{"refs":["f-b01-c007-001","f-b01-c007-004","f-b01-c007-008","f-b01-c007-014","f-b01-c007-016","f-b01-c007-020","f-b01-c007-021","f-b01-c007-022","f-b01-c007-023","f-b01-c007-025","f-b01-c007-026","f-b01-c007-032","f-b01-c007-030","f-b01-c007-031","f-b01-c007-034","f-b01-c007-035","f-b01-c007-036","f-b01-c007-040","f-b01-c007-038","f-b01-c007-039","f-b01-c007-041","f-b01-c007-043","f-b01-c007-045"],"from":7,"heading":"Chapter 7 - Elvar","kind":"chapter","tokens":[{"text":"The pursuit brings Elvar, Grend and Biórr to a man fighting a troll beside a molten waterfall. A woman throws an unidentified object into the pool before fleeing with a child. The troll kills warriors before Elvar brings it down, and the man is collared. Agnar calls him Berak, despite his denial; when the boy is threatened, his eyes, teeth and nails change. Commands and flashes from the collar halt him, while Agnar talks of selling him as Berserkir."}]}]},{"id":"B01-C008","from":8,"number":8,"heading":"Chapter 8 - Orka","blocks":[{"refs":["f-b01-c008-002","f-b01-c008-003","f-b01-c008-011","f-b01-c008-014","f-b01-c008-015","f-b01-c008-016","f-b01-c008-018","f-b01-c008-019","f-b01-c008-025","f-b01-c008-026","f-b01-c008-027","f-b01-c008-029","f-b01-c008-032","f-b01-c008-033","f-b01-c008-034"],"from":8,"heading":"Chapter 8 - Orka","kind":"chapter","tokens":[{"text":"Orka and Thorkel disagree over protecting Breca, whose age recalls Thorkel's own years under a collar and lash. Spert demands an oath from Vesli, and she pledges faithfulness to him and Breca with blood. The household's attempt to settle is interrupted by news of Sigrún's return and an Althing in six days. Attendance is compulsory for those who remain in the realm; Thorkel advises going quietly, and Orka agrees."}]}]},{"id":"B01-C009","from":9,"number":9,"heading":"Chapter 9 - Elvar","blocks":[{"refs":["f-b01-c009-006","f-b01-c009-007","f-b01-c009-008","f-b01-c009-014","f-b01-c009-001","f-b01-c009-002","f-b01-c009-003","f-b01-c009-015","f-b01-c009-020","f-b01-c009-022","f-b01-c009-024","f-b01-c009-029","f-b01-c009-026","f-b01-c009-027","f-b01-c009-028","f-b01-c009-031","f-b01-c009-032","f-b01-c009-036","f-b01-c009-037","f-b01-c009-040","f-b01-c009-041","f-b01-c009-042"],"from":9,"heading":"Chapter 9 - Elvar","kind":"chapter","tokens":[{"text":"A sea serpent strikes the Wave-Jarl, throwing Berak's son overboard. Elvar dives after him and Grend helps them back aboard, while the boy's mother's song slows the creature until it withdraws. Agnar calls her a Seiðr-witch and threatens her son. Elvar receives a gold ring for the rescue, in addition to her troll-tusk necklace, but Agnar's plans for the family remain a sale at Snakavik."}]}]},{"id":"B01-C010","from":10,"number":10,"heading":"Chapter 10 - Orka","blocks":[{"refs":["f-b01-c010-005","f-b01-c010-001","f-b01-c010-002","f-b01-c010-003","f-b01-c010-011","f-b01-c010-012","f-b01-c010-021","f-b01-c010-023","f-b01-c010-035","f-b01-c010-010","f-b01-c010-036","f-b01-c010-037","f-b01-c010-038","f-b01-c010-039","f-b01-c010-040","f-b01-c010-041","f-b01-c010-044"],"from":10,"heading":"Chapter 10 - Orka","kind":"chapter","tokens":[{"text":"At the Althing, reports of missing children accompany Sigrún's announcement that she has sworn to Helka. Virk objects to the oath and challenges Guðvarr's account of the search. The argument becomes a formal challenge to holmganga, which Virk accepts. Sigrún orders the preparations, and Orka agrees to stand as Virk's second."}]}]},{"id":"B01-C011","from":11,"number":11,"heading":"Chapter 11 - Varg","blocks":[{"refs":["f-b01-c011-006","f-b01-c011-008","f-b01-c011-010","f-b01-c011-001","f-b01-c011-018","f-b01-c011-003","f-b01-c011-013","f-b01-c011-023","f-b01-c011-025","f-b01-c011-028","f-b01-c011-031"],"from":11,"heading":"Chapter 11 - Varg","kind":"chapter","tokens":[{"text":"Varg wakes with his spear wound treated and learns that six days have passed. Svik explains that the trial measured how people lost rather than whether they won. The blonde warrior and the grey-bearded rescuer are now named as Røkia and Glornir, the company's chief. On Glornir's orders, Røkia begins Varg's shield training; painful mistakes in the moving drills lead him to agree to learn."}]}]},{"id":"B01-C012","from":12,"number":12,"heading":"Chapter 12 - Orka","blocks":[{"refs":["f-b01-c012-007","f-b01-c012-008","f-b01-c012-010","f-b01-c012-011","f-b01-c012-012","f-b01-c012-013","f-b01-c012-014","f-b01-c012-016","f-b01-c012-018","f-b01-c012-017","f-b01-c012-020","f-b01-c012-022","f-b01-c012-021","f-b01-c012-024","f-b01-c012-025","f-b01-c012-037","f-b01-c012-029","f-b01-c012-030","f-b01-c012-032"],"from":12,"heading":"Chapter 12 - Orka","kind":"chapter","tokens":[{"text":"A duel agreed to end in submission becomes fatal. After wounding Guðvarr and declaring him outside the boundary, Virk responds to an insult with a stroke at his head. Sigrún's warrior-thrall attacks and mauls him; Thorkel kicks her away, suffers a cut and restrains Orka. Collar commands accompany the thrall's collapse and fading changes. Sigrún rules that Virk broke the holmganga, and his sons carry his body away with the family's help."}]}]},{"id":"B01-C013","from":13,"number":13,"heading":"Chapter 13 - Varg","blocks":[{"refs":["f-b01-c013-005","f-b01-c013-006","f-b01-c013-008","f-b01-c013-010","f-b01-c013-007","f-b01-c013-011","f-b01-c013-025","f-b01-c013-049","f-b01-c013-050","f-b01-c013-027","f-b01-c013-028","f-b01-c013-029","f-b01-c013-033","f-b01-c013-042","f-b01-c013-038","f-b01-c013-041","f-b01-c013-043","f-b01-c013-045","f-b01-c013-047","f-b01-c013-048"],"from":13,"heading":"Chapter 13 - Varg","kind":"chapter","tokens":[{"text":"At the feast, Varg meets Torvik, another apprentice who has yet to swear the oath, and hears Galinn's account of the gods' war. The gathering is interrupted by Prince Jaromir's demand for Sulich, whom he accuses of crimes. Glornir refuses to surrender a sworn crewmate, and the Bloodsworn rise when he is threatened. Logur requires evidence and witnesses; Jaromir promises to return the next day."}]}]},{"id":"B01-C014","from":14,"number":14,"heading":"Chapter 14 - Elvar","blocks":[{"refs":["f-b01-c014-001","f-b01-c014-004","f-b01-c014-007","f-b01-c014-008","f-b01-c014-009","f-b01-c014-010","f-b01-c014-011","f-b01-c014-020","f-b01-c014-022","f-b01-c014-025","f-b01-c014-027","f-b01-c014-029","f-b01-c014-032","f-b01-c014-034","f-b01-c014-035","f-b01-c014-036","f-b01-c014-037","f-b01-c014-038","f-b01-c014-039"],"from":14,"heading":"Chapter 14 - Elvar","kind":"chapter","tokens":[{"text":"At a surviving oath stone in the Frost-Isles, Uspa uses blood to reveal images and tells of divine jealousy, feud and the creation of the vaesen. She and her son are named as Uspa and Bjarn. That night, swarming night-wyrms pin the sleepers, forcing the company to fight and burn its way free. A warrior dies, and Agnar orders a return to the ship. Elvar's suspicion that the stone attracted the creatures remains a question."}]}]},{"id":"B01-C015","from":15,"number":15,"heading":"Chapter 15 - Orka","blocks":[{"refs":["f-b01-c015-001","f-b01-c015-004","f-b01-c015-006","f-b01-c015-007","f-b01-c015-019","f-b01-c015-016","f-b01-c015-017","f-b01-c015-032","f-b01-c015-033","f-b01-c015-036","f-b01-c015-038","f-b01-c015-042","f-b01-c015-044","f-b01-c015-045","f-b01-c015-048","f-b01-c015-049","f-b01-c015-053","f-b01-c015-057","f-b01-c015-071","f-b01-c015-072"],"from":15,"heading":"Chapter 15 - Orka","kind":"chapter","tokens":[{"text":"After Virk's burial, grief and the desire for revenge reach Orka's home. Breca asks to learn weapons craft, while Thorkel counsels fairness and restraint; the boy later persuades Orka to release a trapped moth. Worried about Sigrún's thrall and her tasting of blood, Orka asks Thorkel to leave the area with her. He agrees. Before dawn she seeks the local Froa's advice, only to find the Ash Tree destroyed and the spirit dead. Screaming comes from the west."}]}]},{"id":"B01-C016","from":16,"number":16,"heading":"Chapter 16 - Varg","blocks":[{"refs":["f-b01-c016-001","f-b01-c016-003","f-b01-c016-004","f-b01-c016-008","f-b01-c016-009","f-b01-c016-019","f-b01-c016-021","f-b01-c016-022","f-b01-c016-024","f-b01-c016-023","f-b01-c016-013","f-b01-c016-015","f-b01-c016-028","f-b01-c016-030","f-b01-c016-031","f-b01-c016-032","f-b01-c016-033","f-b01-c016-039","f-b01-c016-040","f-b01-c016-041","f-b01-c016-043","f-b01-c016-044","f-b01-c016-045","f-b01-c016-046"],"from":16,"heading":"Chapter 16 - Varg","kind":"chapter","tokens":[{"text":"Painful training has left Varg aching, and Svik challenges his habit of refusing help. As the company prepares to sail, Varg again asks Vol for an akáll, which she describes as reliving a life's last moments. Glornir refuses and makes the terms of Varg's position clear: he is an apprentice, offered food, protection and teaching in return for learning, obedience and fighting. Varg accepts coin for equipment, and Svik offers to accompany him shopping."}]}]},{"id":"B01-C017","from":17,"number":17,"heading":"Chapter 17 - Orka","blocks":[{"refs":["f-b01-c017-001","f-b01-c017-004","f-b01-c017-003","f-b01-c017-005","f-b01-c017-016","f-b01-c017-019","f-b01-c017-020","f-b01-c017-023","f-b01-c017-024","f-b01-c017-026","f-b01-c017-027","f-b01-c017-028","f-b01-c017-031","f-b01-c017-032","f-b01-c017-034","f-b01-c017-029","f-b01-c017-038","f-b01-c017-039","f-b01-c017-041","f-b01-c017-044","f-b01-c017-046","f-b01-c017-049","f-b01-c017-050","f-b01-c017-059","f-b01-c017-060","f-b01-c017-061","f-b01-c017-062","f-b01-c017-067","f-b01-c017-068","f-b01-c017-069","f-b01-c017-057","f-b01-c017-070"],"from":17,"heading":"Chapter 17 - Orka","kind":"chapter","tokens":[{"text":"Orka returns to a burning steading. Thorkel tells her Breca has been taken, then dies outside after saying 'Dragon-born' and apologising. Having rescued Vesli and placed an axe in Thorkel's hand, Orka follows the attackers to the river. Her assault leaves her wounded but yields a captive who names Drekr under violent questioning. He claims not to know Breca's destination or route. Orka kills him, with two river channels still leaving the direction uncertain."}]}]},{"id":"B01-C018","from":18,"number":18,"heading":"Chapter 18 - Varg","blocks":[{"refs":["f-b01-c018-001","f-b01-c018-010","f-b01-c018-025","f-b01-c018-026","f-b01-c018-028","f-b01-c018-031","f-b01-c018-032","f-b01-c018-033","f-b01-c018-036","f-b01-c018-043","f-b01-c018-045","f-b01-c018-046","f-b01-c018-048","f-b01-c018-049","f-b01-c018-053","f-b01-c018-055","f-b01-c018-056","f-b01-c018-057","f-b01-c018-060","f-b01-c018-058","f-b01-c018-061","f-b01-c018-063","f-b01-c018-064","f-b01-c018-066","f-b01-c018-067","f-b01-c018-069","f-b01-c018-070","f-b01-c018-073","f-b01-c018-074","f-b01-c018-075"],"from":18,"heading":"Chapter 18 - Varg","kind":"chapter","tokens":[{"text":"Buying equipment with Svik and Røkia gives Varg a new kit and Glornir's gifts of a shield and Aslog's spear. At the docks, Jaromir's renewed demand for Sulich becomes a cavalry attack. Varg's inexperience shows in a forgotten helmet and a covered spearhead, but he climbs onto a horse and wounds its rider through a gap in the armour. The confrontation stops as Logur's guards arrive and Helka's eagle-bannered ships approach."}]}]},{"id":"B01-C019","from":19,"number":19,"heading":"Chapter 19 - Orka","blocks":[{"refs":["f-b01-c019-001","f-b01-c019-007","f-b01-c019-008","f-b01-c019-009","f-b01-c019-012","f-b01-c019-015","f-b01-c019-029","f-b01-c019-016","f-b01-c019-017","f-b01-c019-018","f-b01-c019-019","f-b01-c019-026","f-b01-c019-024","f-b01-c019-027","f-b01-c019-032","f-b01-c019-033","f-b01-c019-035","f-b01-c019-041","f-b01-c019-043","f-b01-c019-044","f-b01-c019-047","f-b01-c019-048","f-b01-c019-050","f-b01-c019-051","f-b01-c019-054","f-b01-c019-055","f-b01-c019-056","f-b01-c019-057","f-b01-c019-060","f-b01-c019-058","f-b01-c019-059","f-b01-c019-061"],"from":19,"heading":"Chapter 19 - Orka","kind":"chapter","tokens":[{"text":"Back at the ruins, Vesli tends Orka's wounds and gives an incomplete account of the attack, including a change in Thorkel and a red-eyed assailant with long claws. Orka releases the two vaesen from their oaths and unearths her old equipment. After burying Thorkel and sealing his barrow, she puts on the recovered mail and leaves with provisions and the blades that killed him, determined to find their owner."}]}]},{"id":"B01-C020","from":20,"number":20,"heading":"Chapter 20 - Varg","blocks":[{"refs":["f-b01-c020-002","f-b01-c020-001","f-b01-c020-005","f-b01-c020-010","f-b01-c020-024","f-b01-c020-025","f-b01-c020-031","f-b01-c020-032","f-b01-c020-036","f-b01-c020-038","f-b01-c020-037","f-b01-c020-043","f-b01-c020-044","f-b01-c020-045","f-b01-c020-048","f-b01-c020-049","f-b01-c020-050","f-b01-c020-052","f-b01-c020-054","f-b01-c020-056","f-b01-c020-057","f-b01-c020-058","f-b01-c020-059","f-b01-c020-060","f-b01-c020-062","f-b01-c020-061","f-b01-c020-063","f-b01-c020-064"],"from":20,"heading":"Chapter 20 - Varg","kind":"chapter","tokens":[{"text":"Helka takes control of the dispute at the docks and invites Glornir to the hall. Varg's reaction to the dead rider gives way to a lesson in battle spoils, and he helps take the man's gear. Glornir returns with orders to sail and work for Helka against whatever is eating people in the north. With passengers made to row, Varg follows Svik's rhythm aboard the Sea-Wolf, feeling excitement alongside his guilt about Frøya."}]}]},{"id":"B01-C021","from":21,"number":21,"heading":"Chapter 21 - Elvar","blocks":[{"refs":["f-b01-c021-001","f-b01-c021-002","f-b01-c021-013","f-b01-c021-012","f-b01-c021-017","f-b01-c021-018","f-b01-c021-026","f-b01-c021-027","f-b01-c021-028","f-b01-c021-030","f-b01-c021-035","f-b01-c021-036","f-b01-c021-037","f-b01-c021-048","f-b01-c021-055","f-b01-c021-041","f-b01-c021-057","f-b01-c021-059","f-b01-c021-060","f-b01-c021-062","f-b01-c021-063","f-b01-c021-064","f-b01-c021-065","f-b01-c021-066","f-b01-c021-067","f-b01-c021-068","f-b01-c021-069"],"from":21,"heading":"Chapter 21 - Elvar","kind":"chapter","tokens":[{"text":"At Snakavik, built around Snaka's immense skull, Agnar takes a small party to Störr's hall to sell Berak. Hrung, a speaking giant head, tastes the captive's blood and pronounces it Berser's blood; Störr offers a price Agnar accepts. As the party leaves, Hrung announces Elvar's presence. She removes her hood and addresses Störr as her father."}]}]},{"id":"B01-C022","from":22,"number":22,"heading":"Chapter 22 - Orka","blocks":[{"refs":["f-b01-c022-001","f-b01-c022-005","f-b01-c022-006","f-b01-c022-008","f-b01-c022-009","f-b01-c022-011","f-b01-c022-012","f-b01-c022-013","f-b01-c022-016","f-b01-c022-018","f-b01-c022-019","f-b01-c022-020","f-b01-c022-021","f-b01-c022-022","f-b01-c022-023","f-b01-c022-024","f-b01-c022-025","f-b01-c022-026","f-b01-c022-027","f-b01-c022-028","f-b01-c022-030","f-b01-c022-032","f-b01-c022-035","f-b01-c022-036","f-b01-c022-038","f-b01-c022-039","f-b01-c022-040","f-b01-c022-041","f-b01-c022-043","f-b01-c022-044","f-b01-c022-045","f-b01-c022-046","f-b01-c022-047"],"from":22,"heading":"Chapter 22 - Orka","kind":"chapter","tokens":[{"text":"Returning to Fellur for information, Orka frees Mord and Lif before entering Sigrún's chamber. Under threat, the warrior-thrall names herself Vafri, claims mixed divine ancestry and identifies Hakon and Drekr as her master and contact. Darl is only her forced guess about Breca's destination. Violence follows: Orka wounds Sigrún, leaves Vafri dying and escapes through the window to the brothers' boat. They row south as Guðvarr vows revenge from the pier."}]}]},{"id":"B01-C023","from":23,"number":23,"heading":"Chapter 23 - Elvar","blocks":[{"refs":["f-b01-c023-001","f-b01-c023-003","f-b01-c023-008","f-b01-c023-010","f-b01-c023-013","f-b01-c023-014","f-b01-c023-017","f-b01-c023-018","f-b01-c023-020","f-b01-c023-021","f-b01-c023-022","f-b01-c023-023","f-b01-c023-025"],"from":23,"heading":"Chapter 23 - Elvar","kind":"chapter","tokens":[{"text":"Störr's visit makes Elvar's parentage public among more of her companions. He claims her departure forced him to shed blood to restore his authority, but she refuses his proposed marriage to Hakon and insists on earning her own reputation. Grend defends what she has achieved. Störr offers reconciliation and a warband of her own, leaving Elvar with an unsettled choice rather than an accepted agreement."}]}]},{"id":"B01-C024","from":24,"number":24,"heading":"Chapter 24 - Orka","blocks":[{"refs":["f-b01-c024-001","f-b01-c024-006","f-b01-c024-007","f-b01-c024-008","f-b01-c024-009","f-b01-c024-010","f-b01-c024-012","f-b01-c024-013","f-b01-c024-015","f-b01-c024-014","f-b01-c024-016","f-b01-c024-020"],"from":24,"heading":"Chapter 24 - Orka","kind":"chapter","tokens":[{"text":"After hiding the boat and misleading their pursuers, Orka tells the brothers about Thorkel's death and Breca's abduction. Their wish for revenge on Guðvarr conflicts with her need to continue the search. She refuses an immediate attack and advises waiting for the alarm in Fellur to subside. They settle on an exchange: she will teach them weapons craft if they row her to Darl."}]}]},{"id":"B01-C025","from":25,"number":25,"heading":"Chapter 25 - Elvar","blocks":[{"refs":["f-b01-c025-002","f-b01-c025-003","f-b01-c025-010","f-b01-c025-011","f-b01-c025-013","f-b01-c025-014","f-b01-c025-016","f-b01-c025-020","f-b01-c025-021","f-b01-c025-022","f-b01-c025-024"],"from":25,"heading":"Chapter 25 - Elvar","kind":"chapter","tokens":[{"text":"Elvar weighs Störr's offer against a place that remains open to her with the Battle-Grim. Grend advises accepting, warns of hidden plans and promises to follow her. Seeking another answer, she takes mead to Hrung and hears his account of survival and confinement in the fjord. His reply to her question is a riddle, and she leaves as her father approaches, still without a settled decision."}]}]},{"id":"B01-C026","from":26,"number":26,"heading":"Chapter 26 - Varg","blocks":[{"refs":["f-b01-c026-001","f-b01-c026-002","f-b01-c026-006","f-b01-c026-007","f-b01-c026-008","f-b01-c026-014","f-b01-c026-021","f-b01-c026-022","f-b01-c026-023","f-b01-c026-024","f-b01-c026-025","f-b01-c026-026","f-b01-c026-027","f-b01-c026-028"],"from":26,"heading":"Chapter 26 - Varg","kind":"chapter","tokens":[{"text":"An oar-dance after the storm gives the Bloodsworn a chance to celebrate, though Varg's fall ends in wet training and an accusation against Einar. Their later sharing of bread follows Varg's promise not to bite again. Skalk describes the northern killings but has no certain creature or witnesses. When he dismisses Vol as a thrall, Glornir insists on the respect due to a crewmate; Skalk yields and promises payment."}]}]},{"id":"B01-C027","from":27,"number":27,"heading":"Chapter 27 - Elvar","blocks":[{"refs":["f-b01-c027-002","f-b01-c027-005","f-b01-c027-006","f-b01-c027-007","f-b01-c027-008","f-b01-c027-009","f-b01-c027-012","f-b01-c027-013","f-b01-c027-024","f-b01-c027-025","f-b01-c027-026","f-b01-c027-027","f-b01-c027-021"],"from":27,"heading":"Chapter 27 - Elvar","kind":"chapter","tokens":[{"text":"Elvar and Grend return to a raid's aftermath: Thrud is dead, Biórr wounded and Bjarn taken. Ilska's ship escapes while Agnar initially refuses an unprofitable pursuit. Uspa says the raiders wanted her and offers knowledge of the way to Oskutreð in exchange for recovering her son. The route is her claim at this point. Elvar gives Grend a silver arm ring in recognition of their friendship."}]}]},{"id":"B01-C028","from":28,"number":28,"heading":"Chapter 28 - Orka","blocks":[{"refs":["f-b01-c028-004","f-b01-c028-007","f-b01-c028-008","f-b01-c028-009","f-b01-c028-011","f-b01-c028-015","f-b01-c028-016","f-b01-c028-018","f-b01-c028-019","f-b01-c028-020","f-b01-c028-021","f-b01-c028-022"],"from":28,"heading":"Chapter 28 - Orka","kind":"chapter","tokens":[{"text":"The smaller waterways chosen to evade pursuit bring Orka and the brothers into danger at the rapids. A melody affects Orka and Lif before Mord is thrown into the water and bitten by a Näcken. Orka dives after him; a strike accompanied by spoken words wounds the creature, though another fails. Lif helps her ashore after its shriek throws her through the water. As it retreats, she plants iron blades on the bank and explains its dislike of iron."}]}]},{"id":"B01-C029","from":29,"number":29,"heading":"Chapter 29 - Elvar","blocks":[{"refs":["f-b01-c029-001","f-b01-c029-007","f-b01-c029-008","f-b01-c029-010","f-b01-c029-012","f-b01-c029-016","f-b01-c029-017","f-b01-c029-018","f-b01-c029-019","f-b01-c029-022","f-b01-c029-023","f-b01-c029-024"],"from":29,"heading":"Chapter 29 - Elvar","kind":"chapter","tokens":[{"text":"Elvar commits to the Battle-Grim before Uspa shares her secret. Uspa identifies the burned book from Iskalt as the Graskinna and says it gave her the route to Oskutreð. She will guide them there before Bjarn's rescue only if they swear a binding blood oath. Six participants mingle their blood, which rises into a hot cord around their joined hands. The fatal consequences of breaking the oath are described by Kráka and Uspa, not demonstrated here."}]}]},{"id":"B01-C030","from":30,"number":30,"heading":"Chapter 30 - Varg","blocks":[{"refs":["f-b01-c030-001","f-b01-c030-002","f-b01-c030-006","f-b01-c030-008","f-b01-c030-009","f-b01-c030-014","f-b01-c030-013","f-b01-c030-015","f-b01-c030-016","f-b01-c030-017"],"from":30,"heading":"Chapter 30 - Varg","kind":"chapter","tokens":[{"text":"The Bloodsworn leave the Sea-Wolf at a deserted farm after five days on the Slågen. Fifty warriors prepare to continue on foot while ten remain behind. Despite Svik's warning, Varg leaves his captured armour. The farm has neither bodies nor blood; supplies are loaded onto ponies and Edel's hounds take a scent. Varg follows with his own purpose unchanged: to live long enough to discover and avenge Frøya's death."}]}]},{"id":"B01-C031","from":31,"number":31,"heading":"Chapter 31 - Orka","blocks":[{"refs":["f-b01-c031-002","f-b01-c031-003","f-b01-c031-004","f-b01-c031-006","f-b01-c031-007","f-b01-c031-008","f-b01-c031-010","f-b01-c031-012","f-b01-c031-013","f-b01-c031-015","f-b01-c031-020","f-b01-c031-021","f-b01-c031-022"],"from":31,"heading":"Chapter 31 - Orka","kind":"chapter","tokens":[{"text":"Nearly fifteen days of indirect travel bring Orka and the brothers to Darl, with Mord healing and their weapons lessons continuing. Helka's fortress stands above the city with its giant eagle remains and Galdur tower. After Helka arrives with warriors Orka identifies as Ulfhednar, Orka ends her arrangement with the brothers, pays them and once more counsels patience before leaving to search for Breca."}]}]},{"id":"B01-C032","from":32,"number":32,"heading":"Chapter 32 - Elvar","blocks":[{"refs":["f-b01-c032-001","f-b01-c032-002","f-b01-c032-004","f-b01-c032-006","f-b01-c032-007","f-b01-c032-010","f-b01-c032-013","f-b01-c032-016","f-b01-c032-018","f-b01-c032-014","f-b01-c032-015","f-b01-c032-019","f-b01-c032-020","f-b01-c032-021"],"from":32,"heading":"Chapter 32 - Elvar","kind":"chapter","tokens":[{"text":"Across Lake Horndal, the journey turns towards Uspa's promised destination. Elvar qualifies her earlier identification of a Raven-Feeder as Tainted, while Agnar tells the company about Oskutreð and his promise to recover Bjarn. They agree to follow him. Later, Biórr speaks of his guilt over Thrud, promises to follow Elvar as well and kisses her, before Grend sends her to watch."}]}]},{"id":"B01-C033","from":33,"number":33,"heading":"Chapter 33 - Orka","blocks":[{"refs":["f-b01-c033-001","f-b01-c033-002","f-b01-c033-004","f-b01-c033-005","f-b01-c033-008","f-b01-c033-011","f-b01-c033-012","f-b01-c033-016","f-b01-c033-013","f-b01-c033-015","f-b01-c033-017","f-b01-c033-018","f-b01-c033-019"],"from":33,"heading":"Chapter 33 - Orka","kind":"chapter","tokens":[{"text":"Searching Darl's taverns leads Orka after a burn-scarred man to the Dead Drengr. At dawn she sees bound children being loaded onto a canal boat, attacks the guards and cuts the captives free. Their answers do not give her Breca: a boy says he is not among them, and a girl reports other children have already left the tavern. Orka entrusts their escape to the older boy and approaches the Dead Drengr after being told Drekr is inside."}]}]},{"id":"B01-C034","from":34,"number":34,"heading":"Chapter 34 - Varg","blocks":[{"refs":["f-b01-c034-001","f-b01-c034-002","f-b01-c034-007","f-b01-c034-008","f-b01-c034-009","f-b01-c034-012","f-b01-c034-013","f-b01-c034-015","f-b01-c034-017","f-b01-c034-018","f-b01-c034-019","f-b01-c034-014"],"from":34,"heading":"Chapter 34 - Varg","kind":"chapter","tokens":[{"text":"With campfires forbidden, Svik shares cheese and tells Varg how he claims to have outwitted a troll. Torvik's brotherly address offers Varg companionship while reminding him of his unresolved duty to Frøya. Glornir's conversation with Vol shows his own concern for an absent woman, but it brings no change in his refusal of an akáll. Varg begins considering whether Skalk might help him instead."}]}]},{"id":"B01-C035","from":35,"number":35,"heading":"Chapter 35 - Orka","blocks":[{"refs":["f-b01-c035-003","f-b01-c035-008","f-b01-c035-009","f-b01-c035-010","f-b01-c035-011","f-b01-c035-012","f-b01-c035-016","f-b01-c035-017","f-b01-c035-020","f-b01-c035-021","f-b01-c035-023","f-b01-c035-024","f-b01-c035-025","f-b01-c035-026","f-b01-c035-027","f-b01-c035-030","f-b01-c035-031"],"from":35,"heading":"Chapter 35 - Orka","kind":"chapter","tokens":[{"text":"Breca's carved sword pendant is what Orka recognises inside the Dead Drengr. Her search becomes a confrontation with Hakon and Drekr, who boasts of stabbing her husband. The fight moves into the street, where Drekr wounds and nearly strangles her while making unexplained claims about Breca. An unnamed inner change restores her strength enough to break free. Lif and Mord ride in to rescue her, leaving Drekr alive."}]}]},{"id":"B01-C036","from":36,"number":36,"heading":"Chapter 36 - Varg","blocks":[{"refs":["f-b01-c036-001","f-b01-c036-002","f-b01-c036-003","f-b01-c036-004","f-b01-c036-005","f-b01-c036-006","f-b01-c036-007","f-b01-c036-008","f-b01-c036-009","f-b01-c036-010"],"from":36,"heading":"Chapter 36 - Varg","kind":"chapter","tokens":[{"text":"Skalk offers Varg an akáll in exchange for a future blood-oath debt, warning that accepting may cost him his place among the Bloodsworn. The company's discovery of twenty-four mutilated bodies makes their own bargain with Helka more troubling. Vol translates the rune as 'Forbidden ground'; the dead are Helka's drengrs, whose dispatch Skalk had not disclosed. Glornir confronts him but continues the hunt despite the incomplete account of their mission."}]}]},{"id":"B01-C037","from":37,"number":37,"heading":"Chapter 37 - Orka","blocks":[{"refs":["f-b01-c037-001","f-b01-c037-002","f-b01-c037-003","f-b01-c037-004","f-b01-c037-005","f-b01-c037-006","f-b01-c037-007","f-b01-c037-008","f-b01-c037-009","f-b01-c037-010","f-b01-c037-011"],"from":37,"heading":"Chapter 37 - Orka","kind":"chapter","tokens":[{"text":"Lif and Mord have sold their boat and bought horses after seeing Sigrún arrive in Darl. While recovering and repairing her mail, Orka plans another attempt to obtain information. She captures the burned man, who names himself Skefil and reports that Drekr has taken Tainted children towards Grimholt Pass. She questions him about Breca and Hakon before killing him. The report points her towards the pass without independently confirming Breca's presence among the children."}]}]},{"id":"B01-C038","from":38,"number":38,"heading":"Chapter 38 - Elvar","blocks":[{"refs":["f-b01-c038-001","f-b01-c038-003","f-b01-c038-010","f-b01-c038-011","f-b01-c038-013","f-b01-c038-016","f-b01-c038-017","f-b01-c038-018","f-b01-c038-020","f-b01-c038-019","f-b01-c038-021","f-b01-c038-022","f-b01-c038-023","f-b01-c038-024","f-b01-c038-025"],"from":38,"heading":"Chapter 38 - Elvar","kind":"chapter","tokens":[{"text":"At the vaesen pit, Uspa's blood and chanting reveal a pawprint and the Isbrún Bridge as she steps over the chasm. Before the company can pass safely, tennúr erupt beneath the camp. Grend falls protecting Elvar, who holds them off until Biórr carries him out; she also rescues Sólín on the retreat. Leaving dead warriors and a pony behind, the survivors reach the ice bridge and continue towards Oskutreð."}]}]},{"id":"B01-C039","from":39,"number":39,"heading":"Chapter 39 - Varg","blocks":[{"refs":["f-b01-c039-002","f-b01-c039-003","f-b01-c039-004","f-b01-c039-006","f-b01-c039-007","f-b01-c039-008","f-b01-c039-009","f-b01-c039-010","f-b01-c039-011","f-b01-c039-012","f-b01-c039-014","f-b01-c039-015","f-b01-c039-016","f-b01-c039-018","f-b01-c039-020","f-b01-c039-021","f-b01-c039-022"],"from":39,"heading":"Chapter 39 - Varg","kind":"chapter","tokens":[{"text":"Showing Torvik the lock of Frøya's hair makes Varg's need for an akáll personal, and Torvik's offer to help hunt her murderers makes leaving harder. At camp, Skalk's hostility towards Vol draws Glornir's intervention. Accounts of inherited Seiðr and learned Galdur lead into the reported binding of Ulfrir and the making of thrall-collars from his chain. Skalk then renews Jaromir's accusation against Sulich, which Sulich denies before Glornir stops the confrontation."}]}]},{"id":"B01-C040","from":40,"number":40,"heading":"Chapter 40 - Orka","blocks":[{"refs":["f-b01-c040-003","f-b01-c040-004","f-b01-c040-005","f-b01-c040-008","f-b01-c040-012","f-b01-c040-013","f-b01-c040-014","f-b01-c040-015","f-b01-c040-016","f-b01-c040-019"],"from":40,"heading":"Chapter 40 - Orka","kind":"chapter","tokens":[{"text":"Feeling a debt to the brothers, Orka proposes using herself as bait to help avenge their father. Guðvarr's arrival at their lodging farm overtakes the plan and forces a flight north towards Grimholt Pass. At a ravine she sets a wooden bridge alight, making the pursuers retreat from the timbers. She intends to keep drawing Guðvarr after them while continuing her search for Drekr and Breca."}]}]},{"id":"B01-C041","from":41,"number":41,"heading":"Chapter 41 - Varg","blocks":[{"refs":["f-b01-c041-001","f-b01-c041-005","f-b01-c041-006","f-b01-c041-007","f-b01-c041-009","f-b01-c041-011","f-b01-c041-012","f-b01-c041-013","f-b01-c041-014","f-b01-c041-016","f-b01-c041-017","f-b01-c041-019","f-b01-c041-020","f-b01-c041-021"],"from":41,"heading":"Chapter 41 - Varg","kind":"chapter","tokens":[{"text":"Following guarded captives leads the Bloodsworn to a cliff excavation, where emaciated people carry rubble from a tunnel. Glornir divides the company for the approach and Torvik guides Svik's group into position. Varg prepares his equipment without mail and weighs the possibility of escape. Svik reminds the two apprentices that they have not taken the oath, but Varg follows when Glornir steps into the glade. The battle has not yet begun."}]}]},{"id":"B01-C042","from":42,"number":42,"heading":"Chapter 42 - Elvar","blocks":[{"refs":["f-b01-c042-001","f-b01-c042-002","f-b01-c042-003","f-b01-c042-004","f-b01-c042-005","f-b01-c042-006","f-b01-c042-009","f-b01-c042-010","f-b01-c042-011","f-b01-c042-012","f-b01-c042-013","f-b01-c042-014","f-b01-c042-016","f-b01-c042-017","f-b01-c042-018","f-b01-c042-020","f-b01-c042-021"],"from":42,"heading":"Chapter 42 - Elvar","kind":"chapter","tokens":[{"text":"The survivors of the bridge attack count their losses while Grend lies unconscious in a cart. Uspa says his skull is not broken, and Agnar brings Elvar food and speaks of the family he has chosen. Grend eventually wakes and speaks to her before sleeping again. Sólín acknowledges the rescue as a blood-debt, which Elvar answers by calling them shield-sisters. Elvar then thanks Biórr, kisses him and leads him away from camp."}]}]},{"id":"B01-C043","from":43,"number":43,"heading":"Chapter 43 - Varg","blocks":[{"refs":["f-b01-c043-001","f-b01-c043-003","f-b01-c043-006","f-b01-c043-008","f-b01-c043-009","f-b01-c043-010","f-b01-c043-011","f-b01-c043-012","f-b01-c043-013","f-b01-c043-014","f-b01-c043-017","f-b01-c043-025","f-b01-c043-019","f-b01-c043-020","f-b01-c043-021","f-b01-c043-022","f-b01-c043-024","f-b01-c043-026","f-b01-c043-027","f-b01-c043-028","f-b01-c043-029","f-b01-c043-030","f-b01-c043-032","f-b01-c043-033"],"from":43,"heading":"Chapter 43 - Varg","kind":"chapter","tokens":[{"text":"The assault on the excavation breaks Varg and Torvik from the shield line, but Einar kills the skraeling threatening them. A troll blocks the route to Glornir while a red-eyed swordsman throws and wounds the chief. Vol's blood-and-flame rune offers only brief protection before the bone sword breaks it. Varg intervenes, releases his restrained rage and drives his cleaver into the man's head. The falling sword strikes his waist, ending his awareness before the fight's outcome is known."}]}]},{"id":"B01-C044","from":44,"number":44,"heading":"Chapter 44 - Elvar","blocks":[{"refs":["f-b01-c044-001","f-b01-c044-002","f-b01-c044-003","f-b01-c044-005","f-b01-c044-004","f-b01-c044-007","f-b01-c044-008","f-b01-c044-009","f-b01-c044-010","f-b01-c044-011","f-b01-c044-012","f-b01-c044-013","f-b01-c044-014","f-b01-c044-015","f-b01-c044-016","f-b01-c044-017","f-b01-c044-018","f-b01-c044-019","f-b01-c044-020","f-b01-c044-021"],"from":44,"heading":"Chapter 44 - Elvar","kind":"chapter","tokens":[{"text":"Travelling through the Dark-of-Moon Hills, the Battle-Grim remain in full battle gear and Agnar voices a concern he cannot identify. Biórr and Elvar continue their relationship; his account of whip scars and dead kin adds to what she knows of him. Uspa admits uncertainty about when they will reach Oskutreð and warns against carrying its treasures south, while putting Bjarn's recovery above her principles. Their debate turns to fame, love, chosen kin and the consequences of individual choices."}]}]},{"id":"B01-C045","from":45,"number":45,"heading":"Chapter 45 - Varg","blocks":[{"refs":["f-b01-c045-001","f-b01-c045-002","f-b01-c045-003","f-b01-c045-013","f-b01-c045-017","f-b01-c045-004","f-b01-c045-005","f-b01-c045-006","f-b01-c045-008","f-b01-c045-009","f-b01-c045-010","f-b01-c045-011","f-b01-c045-012","f-b01-c045-018","f-b01-c045-019","f-b01-c045-020","f-b01-c045-021","f-b01-c045-022","f-b01-c045-023","f-b01-c045-024","f-b01-c045-025","f-b01-c045-026","f-b01-c045-027","f-b01-c045-028","f-b01-c045-029","f-b01-c045-030","f-b01-c045-032","f-b01-c045-033","f-b01-c045-034","f-b01-c045-035"],"from":45,"heading":"Chapter 45 - Varg","kind":"chapter","tokens":[{"text":"Varg wakes alive in the catacomb, where Vol tends his pain and Torvik explains the chamber through identifications and saga-tales. Vol names her missing sister as Uspa, then hears Varg's fragmented account of Frøya's death and the killings on the farm. Their conversation ends in betrayal: Skalk knocks Vol unconscious, Yrsa mortally wounds Torvik and Olvir restrains Varg. Offered an akáll for his oath, Varg attacks Olvir instead. Skalk kicks him unconscious as Vol is carried away."}]}]},{"id":"B01-C046","from":46,"number":46,"heading":"Chapter 46 - Orka","blocks":[{"refs":["f-b01-c046-001","f-b01-c046-002","f-b01-c046-003","f-b01-c046-004","f-b01-c046-006","f-b01-c046-007","f-b01-c046-008","f-b01-c046-009","f-b01-c046-010","f-b01-c046-011","f-b01-c046-016","f-b01-c046-012","f-b01-c046-013","f-b01-c046-015","f-b01-c046-017","f-b01-c046-020","f-b01-c046-021","f-b01-c046-022"],"from":46,"heading":"Chapter 46 - Orka","kind":"chapter","tokens":[{"text":"Orka and the brothers climb towards Grimholt with smoke marking Guðvarr's pursuit behind them. A broken oath stone beneath a hanging dead eagle bears a fresh, blood-coated carving, which Orka identifies with Lik-Rifa worship; its connection to Breca remains speculation. Training continues while her own wounds heal. She plans to reach Grimholt before deciding whether to press on or confront their pursuers, and prepares the brothers for fighting armoured opponents."}]}]},{"id":"B01-C047","from":47,"number":47,"heading":"Chapter 47 - Varg","blocks":[{"refs":["f-b01-c047-001","f-b01-c047-002","f-b01-c047-003","f-b01-c047-004","f-b01-c047-005","f-b01-c047-006","f-b01-c047-007","f-b01-c047-009","f-b01-c047-010","f-b01-c047-011","f-b01-c047-014","f-b01-c047-016","f-b01-c047-017","f-b01-c047-018","f-b01-c047-019","f-b01-c047-020","f-b01-c047-021","f-b01-c047-022","f-b01-c047-023","f-b01-c047-024","f-b01-c047-025","f-b01-c047-026","f-b01-c047-027","f-b01-c047-028","f-b01-c047-029"],"from":47,"heading":"Chapter 47 - Varg","kind":"chapter","tokens":[{"text":"Varg wakes to a company whose secrets are being disclosed. Svik reveals fox ancestry with a reversible change of face, eyes and teeth, while Edel and Røkia identify the wolf in Varg's blood. The companions explain that secrecy let them judge his trustworthiness. Glornir, grieving Vol's abduction and explicitly naming her as his wife, invites Varg into the Bloodsworn. Varg accepts a silver arm ring, but the formal oath-words must wait while they pursue her rescue."}]}]},{"id":"B01-C048","from":48,"number":48,"heading":"Chapter 48 - Elvar","blocks":[{"refs":["f-b01-c048-001","f-b01-c048-002","f-b01-c048-006","f-b01-c048-007","f-b01-c048-008","f-b01-c048-010","f-b01-c048-012","f-b01-c048-013","f-b01-c048-014","f-b01-c048-016","f-b01-c048-017","f-b01-c048-018","f-b01-c048-019","f-b01-c048-022","f-b01-c048-023","f-b01-c048-024","f-b01-c048-025","f-b01-c048-026","f-b01-c048-027","f-b01-c048-028","f-b01-c048-029","f-b01-c048-030","f-b01-c048-031","f-b01-c048-032"],"from":48,"heading":"Chapter 48 - Elvar","kind":"chapter","tokens":[{"text":"Beyond the Gallows Wood, the Battle-Grim reach Oskutreð's immense ruined stump and the remains around it. Vörn emerges from a living tree and forbids entry onto the dead one; when Sighvat attacks, she binds him in vines. She says Lik-Rifa is imprisoned below and names the dragon's gaolers. Agnar promises to keep his company away from the tree. Their gathering of relics is interrupted by Ilska's approaching force."}]}]},{"id":"B01-C049","from":49,"number":49,"heading":"Chapter 49 - Orka","blocks":[{"refs":["f-b01-c049-001","f-b01-c049-002","f-b01-c049-003","f-b01-c049-004","f-b01-c049-005","f-b01-c049-006","f-b01-c049-007","f-b01-c049-008","f-b01-c049-009","f-b01-c049-010","f-b01-c049-011","f-b01-c049-012","f-b01-c049-013","f-b01-c049-016","f-b01-c049-017","f-b01-c049-018","f-b01-c049-019","f-b01-c049-020","f-b01-c049-021","f-b01-c049-022","f-b01-c049-023","f-b01-c049-024","f-b01-c049-025","f-b01-c049-026"],"from":49,"heading":"Chapter 49 - Orka","kind":"chapter","tokens":[{"text":"Unable to assault Grimholt directly, Orka follows a disturbance and finds two speaking ravens threatened by frost-spiders. Remembering Breca and the moth, she intervenes with the brothers. Lif is bitten, web numbs her leg and Mord becomes entangled, although the freed ravens help her before flying away. Arriving riders include a blond staff-bearer who burns the spiders. More warriors surround the party, and he strikes Orka down as she tries to carry Lif out."}]}]},{"id":"B01-C050","from":50,"number":50,"heading":"Chapter 50 - Elvar","blocks":[{"refs":["f-b01-c050-001","f-b01-c050-003","f-b01-c050-005","f-b01-c050-006","f-b01-c050-007","f-b01-c050-008","f-b01-c050-009","f-b01-c050-010","f-b01-c050-011","f-b01-c050-013","f-b01-c050-014","f-b01-c050-015","f-b01-c050-016","f-b01-c050-017","f-b01-c050-018","f-b01-c050-020","f-b01-c050-021","f-b01-c050-022","f-b01-c050-023","f-b01-c050-024"],"from":50,"heading":"Chapter 50 - Elvar","kind":"chapter","tokens":[{"text":"Ilska refuses Uspa's demand for Bjarn and offers a holmganga between Agnar and her brother Skrið. Despite his opponent's suddenly heightened strength and speed, Agnar wins while suffering severe wounds. Vörn recognises dragon-born blood and forbids their approach. Ilska's carts reveal scores of collared children, including Bjarn. When Biórr reaches the wounded Agnar, he drives his spear into the chief's mouth and throat, leaving Elvar screaming as he falls."}]}]},{"id":"B01-C051","from":51,"number":51,"heading":"Chapter 51 - Orka","blocks":[{"refs":["f-b01-c051-001","f-b01-c051-004","f-b01-c051-005","f-b01-c051-006","f-b01-c051-007","f-b01-c051-008","f-b01-c051-009","f-b01-c051-010","f-b01-c051-011","f-b01-c051-012","f-b01-c051-013","f-b01-c051-014","f-b01-c051-015","f-b01-c051-016","f-b01-c051-017","f-b01-c051-018","f-b01-c051-019","f-b01-c051-020","f-b01-c051-021","f-b01-c051-022","f-b01-c051-023","f-b01-c051-024"],"from":51,"heading":"Chapter 51 - Orka","kind":"chapter","tokens":[{"text":"Captured inside Grimholt, Orka hears a child and calls for Breca, but the guards subdue her. Interrogation exposes Hakon's order to accommodate Drekr's traffic. Guðvarr's stabbing of the bound Mord brings a surge of strength and sharpened senses; Orka bites through her bonds, frees Lif and wounds Skalk. The ravens repay her rescue by opening the roof and bringing Spert and Vesli. With their aid she drives the guards into retreat and pursues them towards the courtyard."}]}]},{"id":"B01-C052","from":52,"number":52,"heading":"Chapter 52 - Elvar","blocks":[{"refs":["f-b01-c052-001","f-b01-c052-002","f-b01-c052-003","f-b01-c052-004","f-b01-c052-006","f-b01-c052-008","f-b01-c052-009","f-b01-c052-010","f-b01-c052-011","f-b01-c052-012","f-b01-c052-015","f-b01-c052-016","f-b01-c052-017","f-b01-c052-018","f-b01-c052-019","f-b01-c052-020","f-b01-c052-021","f-b01-c052-022","f-b01-c052-023","f-b01-c052-024","f-b01-c052-025","f-b01-c052-026","f-b01-c052-027","f-b01-c052-028","f-b01-c052-029","f-b01-c052-030","f-b01-c052-031","f-b01-c052-032","f-b01-c052-033","f-b01-c052-034","f-b01-c052-035","f-b01-c052-039","f-b01-c052-040","f-b01-c052-041"],"from":52,"heading":"Chapter 52 - Elvar","kind":"chapter","tokens":[{"text":"Agnar dies and Biórr declares his allegiance to Ilska, acknowledging Thrud's killing. Grend draws Elvar back into the Battle-Grim's defence and carries her behind the line after she is wounded. At the tree, Ilska overcomes resistance and uses a blood ritual involving the collared children to open the door. Lik-Rifa emerges and fights her gaolers. Elvar and Grend survive the blast but cannot prevent the dragon's departure or Ilska's company leaving with the children."}]}]},{"id":"B01-C053","from":53,"number":53,"heading":"Chapter 53 - Varg","blocks":[{"refs":["f-b01-c053-001","f-b01-c053-002","f-b01-c053-004","f-b01-c053-005","f-b01-c053-006","f-b01-c053-007","f-b01-c053-008","f-b01-c053-009","f-b01-c053-010","f-b01-c053-011","f-b01-c053-012","f-b01-c053-013","f-b01-c053-014","f-b01-c053-015","f-b01-c053-016"],"from":53,"heading":"Chapter 53 - Varg","kind":"chapter","tokens":[{"text":"Following Skalk's trail, Varg runs with Edel's scouts in his newly won armour, increasingly accepting his place among the Bloodsworn. Smoke and blood lead them to a devastated fortress. On its steps a woman sits with two vaesen and a group of children, but says the person she seeks is not there. Glornir recognises her as Orka Skullsplitter, asks after his brother and embraces her after hearing of a killing and her son's abduction."}]}]}],"images":[],"featured":false,"curated":true}]};
